var Q23 = [
{n:1, q:'La Constitución Española de 1978 garantiza la autonomía de los municipios en su Título VIII, Capítulo II, artículo:', o:{a:'140.',b:'139.',c:'138.',d:'137.'}, correct:'a', why:{a:'El art. 140 CE es el que garantiza la autonomía de los municipios y establece que el gobierno y administración del municipio corresponde a sus Ayuntamientos.'}},
{n:2, q:'La Constitución Española de 1978, en su art.140, establece que el gobierno y administración del municipio corresponde:', o:{a:'A sus respectivos Ayuntamientos.',b:'A sus respectivos Alcaldes.',c:'A sus respectivos Concejales.',d:'El citado artículo no se refiere al municipio.'}, correct:'a', why:{a:'El art. 140 CE establece que el gobierno y administración del municipio corresponde a sus respectivos Ayuntamientos.'}},
{n:3, q:'El art.140 de la Constitución Española de 1978 garantiza la autonomía de los municipios y establece:', o:{a:'Que estos gozarán de personalidad jurídica plena.',b:'Que su gobierno y administración corresponde a sus respectivos Ayuntamientos.',c:'Que los Ayuntamientos están integrados por los Alcaldes y los Concejales.',d:'Todo lo reflejado en las respuestas anteriores es correcto.'}, correct:'d', why:{d:'El art. 140 CE establece que los municipios gozan de personalidad jurídica plena, que su gobierno corresponde a sus Ayuntamientos y que estos están integrados por Alcaldes y Concejales.'}},
{n:4, q:'Respecto a los municipios, el art.140 de la Constitución Española de 1978, establece que:', o:{a:'Los concejales serán elegidos por los vecinos del municipio mediante sufragio universal, igual, libre, directo y secreto, en la forma establecida por la ley.',b:'Los alcaldes serán elegidos por los concejales o por los vecinos.',c:'La ley regulará las condiciones en las que proceda el régimen del concejo abierto.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 140 CE establece que los concejales se eligen por sufragio universal directo, los alcaldes por los concejales o vecinos, y que la ley regulará el concejo abierto.'}},
{n:5, q:'Respecto a la organización territorial del Estado Español, señale la afirmación incorrecta:', o:{a:'Dentro de la organización territorial todas las entidades que la componen gozan del mismo nivel de autonomía.',b:'Los municipios son entidades básicas de la organización territorial del Estado y cauces inmediatos de participación ciudadana en los asuntos públicos, que institucionalizan y gestionan con autonomía los intereses propios de las correspondientes colectividades.',c:'Los municipios y las provincias dependen de la voluntad del legislador ordinario a la hora de fijar sus competencias.',d:'La autonomía de municipios y provincias está garantizada constitucionalmente, no obstante se diferencia del autogobierno de las Comunidades Autónomas por no incluir la potestad legislativa.'}, correct:'a', why:{a:'La opción a) es incorrecta: las entidades que componen la organización territorial no gozan todas del mismo nivel de autonomía; tienen distintos niveles según la Constitución.'}},
{n:6, q:'Respecto a la organización territorial del Estado Español, señale la afirmación incorrecta:', o:{a:'El Estado Español se organiza territorialmente en municipios, provincias y en las comunidades autónomas que se constituyan, y todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.',b:'La organización territorial del Estado Español se basa en el principio general de autogobierno.',c:'La autonomía de municipios y provincias está garantizada constitucionalmente e incluye la potestad legislativa.',d:'El poder del Estado es único, pero su organización se descentraliza territorialmente, en ámbitos de competencia de diverso signo.'}, correct:'c', why:{c:'La opción c) es incorrecta: la autonomía de municipios y provincias está garantizada constitucionalmente, pero NO incluye la potestad legislativa, a diferencia de las CCAA.'}},
{n:7, q:'La Ley 7/85, Reguladora de las Bases del Régimen Local dedica al Municipio su Título II, que está compuesto de:', o:{a:'Cinco Capítulos.',b:'Cuatro Capítulos.',c:'Tres Capítulos.',d:'La citada Ley se refiere al Municipio en su Título I, que se compone de 3 Capítulos.'}, correct:'b', why:{b:'La Ley 7/1985, Reguladora de las Bases del Régimen Local, dedica al Municipio su Título II, que está compuesto de cuatro capítulos.'}},
{n:8, q:'Para la efectividad de la autonomía garantizada constitucionalmente a las Entidades Locales, el art.2.1 de la Ley 7/85, Reguladora de las Bases del Régimen Local, establece que la legislación del Estado y la de las Comunidades Autónomas:', o:{a:'Deberá asegurar a los Municipios su derecho a mantener sus tradiciones.',b:'Deberá asegurar a los Municipios su derecho a intervenir en cuantos asuntos afecten directamente al círculo de sus intereses.',c:'Deberá asegurar a los Municipios lo reflejado en las respuestas a) y b).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 2.1 LRBRL establece que la legislación del Estado y de las CCAA deberá asegurar a los Municipios su derecho a intervenir en cuantos asuntos afecten directamente al círculo de sus intereses.'}},
{n:9, q:'De conformidad con los principios de descentralización, proximidad, eficacia y eficiencia, y con estricta sujeción a la normativa de estabilidad presupuestaria y sostenibilidad financiera, la legislación del Estado y la de las CCAA, atribuirá a los municipios las competencias que proceda:', o:{a:'En atención a las características de la actividad pública de que se trate.',b:'En atención a la capacidad de gestión de la Entidad Local, de conformidad con los principios de descentralización, proximidad, eficacia y eficiencia, y con estricta sujeción a la normativa de estabilidad presupuestaria y sostenibilidad financiera.',c:'En atención a lo reflejado en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art. 2 LRBRL establece que la atribución de competencias a los municipios se hará en atención a las características de la actividad pública y a la capacidad de gestión de la Entidad Local.'}},
{n:10, q:'El art.2.2 de la Ley 7/85, Reguladora de las Bases del Régimen Local, establece que las leyes básicas del Estado previstas constitucionalmente, deberán determinar las competencias que ellas mismas atribuyan o que, en todo caso...', o:{a:'Deban corresponder a los Entes locales en las materias que regulen.',b:'Deban ser asumidas por los respectivos ayuntamientos.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'a', why:{a:'El art. 2.2 LRBRL establece que las leyes básicas del Estado deberán determinar las competencias que deban corresponder a los Entes locales en las materias que regulen.'}},
{n:11, q:'En su calidad de Administración Pública de carácter territorial, y dentro de la esfera de sus competencias, corresponde/n en todo caso a los municipios:', o:{a:'Las potestades reglamentaria y de autoorganización.',b:'Las potestades tributaria y financiera.',c:'La potestad de programación o planificación.',d:'Todas las potestades anteriores son correctas.'}, correct:'d', why:{d:'El art. 4 LRBRL establece que en el ámbito de sus competencias corresponden a los municipios las potestades reglamentaria, de autoorganización, tributaria y financiera y de planificación, entre otras.'}},
{n:12, q:'En su calidad de Administración Pública de carácter territorial, y dentro de la esfera de sus competencias, corresponde/n en todo caso a los municipios:', o:{a:'La potestad de revisión de sus actos, acuerdos y voluntades.',b:'Las prelaciones y preferencias y demás prerrogativas reconocidas a la Hacienda Pública para los créditos de la misma, sin perjuicio de las que correspondan a las Haciendas del Estado y de las comunidades autónomas; así como la inembargabilidad de sus bienes y derechos en los términos previstos en las leyes.',c:'La presunción de veracidad y la ejecución de sus actos oficiales.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 4 LRBRL establece que en el ámbito de sus competencias corresponden a los municipios las prelaciones y preferencias reconocidas a la Hacienda Pública y la inembargabilidad de sus bienes.'}},
{n:13, q:'En su calidad de Administración Pública de carácter territorial, y dentro de la esfera de sus competencias, corresponde/n en todo caso a los municipios:', o:{a:'Las potestades expropiatoria y de investigación, deslinde y recuperación de oficio de sus bienes.',b:'La presunción de legitimidad y la ejecutividad de sus actos.',c:'Las potestades de ejecución forzosa y sancionadora.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 4 LRBRL establece que corresponden a los municipios las potestades expropiatoria, de investigación y deslinde de bienes, la presunción de legitimidad y ejecutividad de sus actos, y las potestades de ejecución forzosa y sancionadora.'}},
{n:14, q:'En su calidad de Administración Pública de carácter territorial, y dentro de la esfera de sus competencias, corresponde/n en todo caso a los municipios:', o:{a:'La potestad de revisión de oficio de sus actos y acuerdos.',b:'La inembargabilidad de sus propiedades registradas oficialmente.',c:'Las respuestas a) y b) son correctas.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 4 LRBRL establece que corresponde a los municipios la potestad de revisión de oficio de sus actos y acuerdos.'}},
{n:15, q:'Para el cumplimiento de sus fines y en el ámbito de sus respectivas competencias, las Entidades locales, de acuerdo con la Constitución y las leyes, tendrán plena capacidad jurídica:', o:{a:'Para adquirir, poseer, reivindicar, permutar, gravar o enajenar toda clase de bienes.',b:'Para celebrar contratos, establecer y explotar obras o servicios públicos.',c:'Para obligarse, interponer los recursos establecidos y ejercitar las acciones previstas en las leyes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 3 LRBRL establece que las entidades locales tendrán plena capacidad jurídica para adquirir, poseer y enajenar bienes, celebrar contratos, explotar servicios públicos y ejercitar los recursos legales.'}},
{n:16, q:'El art.11.1 de la Ley 7/85, Reguladora de las Bases del Régimen Local establece que el Municipio:', o:{a:'Tiene autonomía y gozará de personalidad jurídica plena.',b:'Es la Entidad Local primaria de las que componen la organización territorial del Estado.',c:'Es la Entidad Local básica de la organización territorial del Estado y tiene personalidad jurídica y plena capacidad para el cumplimiento de sus fines.',d:'Las respuestas a y b son correctas.'}, correct:'c', why:{c:'El art. 11.1 LRBRL establece que el Municipio es la Entidad Local básica de la organización territorial del Estado y tiene personalidad jurídica y plena capacidad para el cumplimiento de sus fines.'}},
{n:17, q:'El art.11.2 de la Ley 7/1985, Reguladora de las Bases del Régimen Local establece que los elementos del Municipio son:', o:{a:'El Territorio, la población y la organización.',b:'El Alcalde y los Concejales.',c:'Los citados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 11.2 LRBRL establece que son elementos del Municipio: el Territorio, la Población y la Organización.'}},
{n:18, q:'El "Territorio" es uno de los elementos del municipio y la Ley 7/1985, Reguladora de las Bases del Régimen Local:', o:{a:'Lo regula en sus artículos 12 a 14.',b:'Establece que el término municipal es el territorio en que el ayuntamiento ejerce sus competencias.',c:'Establece que cada municipio pertenecerá a una sola provincia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La LRBRL regula el territorio en los arts. 12 a 14, establece que el término municipal es el territorio donde el ayuntamiento ejerce sus competencias y que cada municipio pertenecerá a una sola provincia.'}},
{n:19, q:'Respecto al territorio, como uno de los elementos del municipio, indique la afirmación incorrecta:', o:{a:'La creación o supresión de municipios, así como la alteración de términos municipales, se regularán por la legislación de las CCAA sobre régimen local.',b:'Los límites provinciales solo podrán modificarse previo informe favorable de la administración autonómica y dictamen del Consejo de Estado.',c:'La alteración de términos municipales no podrá suponer, en ningún caso, modificación de los límites provinciales.',d:'La creación o supresión de municipios, así como la alteración de términos municipales, requerirán en todo caso audiencia de los municipios interesados y dictamen del Consejo de Estado.'}, correct:'b', why:{b:'La opción b) es incorrecta: los límites provinciales solo podrán modificarse mediante ley orgánica, no mediante informe favorable de la administración autonómica y dictamen del Consejo de Estado.'}},
{n:20, q:'La creación de nuevos municipios solo podrá realizarse sobre la base de núcleos de población territorialmente diferenciados, de al menos 4.000 habitantes y siempre que los municipios resultantes:', o:{a:'Sean financieramente sostenibles.',b:'Cuenten con recursos suficientes para el cumplimiento de las competencias municipales.',c:'No suponga disminución en la calidad de los servicios que venían siendo prestados.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 13 LRBRL establece que para la creación de nuevos municipios se requiere núcleo poblacional de al menos 4.000 habitantes y que los resultantes sean financieramente sostenibles, con recursos suficientes y sin disminución de la calidad de los servicios.'}},
{n:21, q:'Los municipios, con independencia de su población, colindantes dentro de la misma provincia podrán acordar su fusión mediante un convenio de fusión, sin perjuicio del procedimiento previsto en la normativa autonómica, y el nuevo municipio resultante de la fusión no podrá segregarse:', o:{a:'Hasta transcurridos veinte años desde la adopción del convenio de fusión.',b:'Hasta transcurridos quince años desde la adopción del convenio de fusión.',c:'Hasta transcurridos diez años desde la adopción del convenio de fusión.',d:'Hasta transcurridos cinco años desde la adopción del convenio de fusión.'}, correct:'c', why:{c:'El art. 13 LRBRL establece que el nuevo municipio resultante de una fusión no podrá segregarse hasta transcurridos diez años desde la adopción del convenio de fusión.'}},
{n:22, q:'La fusión de municipios legalmente acordada conllevará:', o:{a:'La integración de los territorios, poblaciones y organizaciones de los municipios, incluyendo los medios personales, materiales y económicos, del municipio fusionado. De la ejecución de las citadas medidas no podrá derivarse incremento alguno de la masa salarial en los municipios afectados.',b:'Que el órgano del gobierno del nuevo municipio resultante esté constituido transitoriamente por la suma de los concejales de los municipios fusionados en los términos previstos en la Ley Orgánica 5/1985, del Régimen Electoral General.',c:'Que, si se acordara en el convenio de fusión, cada uno de los municipios fusionados, o alguno de ellos pueda funcionar como forma de organización desconcentrada.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 13 LRBRL establece que la fusión de municipios conlleva la integración de territorios, poblaciones y organizaciones, la constitución transitoria del órgano de gobierno y la posibilidad de organización desconcentrada.'}},
{n:23, q:'Respecto a la fusión de municipios legalmente acordada, indique la afirmación incorrecta:', o:{a:'El nuevo municipio se subrogará en todos los derechos y obligaciones de los anteriores municipios.',b:'Si uno de los municipios fusionados estuviera en situación de déficit no se podrán integrar, aunque exista acuerdo de los municipios fusionados, las obligaciones, bienes y derechos patrimoniales de aquél.',c:'El nuevo municipio aprobará un nuevo presupuesto para el ejercicio presupuestario siguiente a la adopción del convenio de fusión.',d:'El convenio de fusión deberá ser aprobado por mayoría simple de cada uno de los plenos de los municipios fusionados.'}, correct:'b', why:{b:'La opción b) es incorrecta: aunque un municipio fusionado esté en situación de déficit, el nuevo municipio sí se subrogará en sus obligaciones.'}},
{n:24, q:'Respecto a la fusión de municipios legalmente acordada, indique la afirmación incorrecta:', o:{a:'Si uno de los municipios fusionados estuviera en situación de déficit se podrán integrar, por acuerdo de los municipios fusionados, las obligaciones, bienes y derechos patrimoniales que se consideren liquidables en un fondo, sin personalidad jurídica y con contabilidad separada, adscrito al nuevo municipio, que designará un liquidador.',b:'El nuevo municipio aprobará un nuevo presupuesto para el ejercicio presupuestario siguiente a la adopción del convenio de fusión.',c:'El convenio de fusión deberá ser aprobado por mayoría absoluta de cada uno de los plenos de los municipios fusionados.',d:'La adopción de los acuerdos previstos en el artículo 47.2 de la Ley 7/1985, siempre que traigan causa de una fusión, será por mayoría simple de los miembros de la corporación.'}, correct:'c', why:{c:'La opción c) es incorrecta: el convenio de fusión deberá ser aprobado por mayoría simple (no absoluta) de cada uno de los plenos de los municipios fusionados.'}},
{n:25, q:'Los cambios de denominación de los municipios solo tendrán carácter oficial cuando, tras haber sido anotados en un registro creado por la Administración del Estado, se publiquen:', o:{a:'En el Boletín Oficial del Estado.',b:'En el Boletín Oficial de la provincia y en la página Web del Ayuntamiento.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'a', why:{a:'El art. 14 LRBRL establece que los cambios de denominación de los municipios solo tendrán carácter oficial cuando, tras ser anotados en el registro correspondiente, se publiquen en el BOE.'}},
{n:26, q:'La denominación de los municipios, a todos los efectos, podrá ser:', o:{a:'En castellano o en cualquier otra lengua española oficial en la respectiva comunidad autónoma.',b:'En castellano y en cualquier otra lengua española oficial en la respectiva comunidad autónoma.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'El art. 14 LRBRL establece que la denominación de los municipios podrá ser en castellano, o en cualquier otra lengua española oficial, o en las dos lenguas conjuntamente.'}},
{n:27, q:'La "Población" es uno de los elementos del municipio y la Ley 7/1985, Reguladora de las Bases del Régimen Local:', o:{a:'La regula en sus artículos 15 a 17.',b:'Establece que el conjunto de personas inscritas en el Padrón municipal constituye la población del municipio.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'La LRBRL regula la población en los arts. 15 a 17 y establece que el conjunto de personas inscritas en el Padrón municipal constituye la población del municipio.'}},
{n:28, q:'Respecto a la población de un municipio, indique la afirmación incorrecta:', o:{a:'La condición de vecino se adquiere transcurridos seis meses de su inscripción en el padrón.',b:'Toda persona que viva en España está obligada a inscribirse en el padrón del municipio en el que resida habitualmente.',c:'Quien viva en varios municipios deberá inscribirse únicamente en el que habite durante más tiempo al año.',d:'Los inscritos en el padrón municipal son los vecinos del municipio.'}, correct:'a', why:{a:'La opción a) es incorrecta: la condición de vecino se adquiere en el mismo momento de la inscripción en el padrón, no transcurridos seis meses.'}},
{n:29, q:'La condición de vecino de un municipio se adquiere:', o:{a:'Transcurridos tres meses de su inscripción en el padrón.',b:'En el mismo momento de su inscripción en el padrón.',c:'Transcurridos seis meses de su inscripción en el padrón.',d:'Transcurridos un mes de su inscripción en el padrón.'}, correct:'b', why:{b:'El art. 15 LRBRL establece que la condición de vecino de un municipio se adquiere en el mismo momento de la inscripción en el padrón municipal.'}},
{n:30, q:'Respecto a la población de un municipio, indique la afirmación incorrecta:', o:{a:'El padrón municipal es el registro administrativo donde constan los vecinos de un municipio. Sus datos constituyen prueba de la residencia en el municipio y del domicilio habitual en el mismo.',b:'La inscripción en el padrón municipal de extranjeros no comunitarios sin autorización de residencia permanente, en todo caso, deberá ser objeto de renovación periódica cada tres años.',c:'Las certificaciones que se expidan de los datos del padrón municipal tendrán carácter de documento público y fehaciente para todos los efectos administrativos.',d:'La inscripción en el padrón municipal sólo surtirá efecto por el tiempo que subsista el hecho que la motivó.'}, correct:'b', why:{b:'La opción b) es incorrecta: la inscripción en el padrón municipal de extranjeros no comunitarios sin autorización de residencia de larga duración deberá renovarse cada dos años, no cada tres.'}},
{n:31, q:'La inscripción en el padrón municipal de extranjeros no comunitarios sin autorización de residencia de larga duración, en todo caso, deberá ser objeto de renovación periódica:', o:{a:'Cada dos años.',b:'Cada tres años.',c:'Cada cuatro años.',d:'Cada año.'}, correct:'a', why:{a:'El art. 16 LRBRL establece que la inscripción de extranjeros no comunitarios sin autorización de residencia de larga duración deberá renovarse periódicamente cada dos años.'}},
{n:32, q:'La inscripción en el padrón municipal de extranjeros sin autorización de residencia de larga duración, en todo caso, deberá ser objeto de renovación periódica cada dos años, cuando se trate de extranjeros:', o:{a:'Pertenecientes a un Estado miembro de la Unión Europea.',b:'Pertenecientes a Estados parte en el Acuerdo sobre el Espacio Económico Europeo.',c:'Pertenecientes a Estados a los que, en virtud de un convenio internacional se extienda el régimen jurídico previsto para los ciudadanos de los Estados mencionados en las respuestas a y b.',d:'Pertenecientes a cualquiera de los Estados descritos en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 16 LRBRL establece que la renovación bienal de la inscripción padronal se aplica a extranjeros de la UE, EEE y de Estados con convenio internacional que extienda ese régimen.'}},
{n:33, q:'La inscripción en el padrón municipal contendrá como datos obligatorios, sólo:', o:{a:'Nombre, apellidos, sexo, domicilio habitual (con especificación de la referencia catastral cuando proceda), nacionalidad, lugar y fecha de nacimiento y certificado o título escolar o académico que se posea.',b:'Número de documento nacional de identidad o, tratándose de extranjeros, numero de identidad en vigor, que corresponda, según el tipo de extranjero de que se trate.',c:'Cuantos datos puedan ser necesarios para la elaboración del censo electoral, siempre que se garantice el respeto a los derechos fundamentales reconocidos en la Constitución.',d:'Todos los datos reflejados en las respuestas anteriores deben constar obligatoriamente en el padrón.'}, correct:'d', why:{d:'El art. 16 LRBRL establece que la inscripción en el padrón municipal contendrá como datos obligatorios: el nombre, apellidos y datos personales, el número de documento de identidad, los datos necesarios para el censo electoral, etc.'}},
{n:34, q:'Respecto a los datos obligatorios del padrón municipal, indique la afirmación incorrecta:', o:{a:'No se cederán, en ningún caso.',b:'Se cederán a otras administraciones públicas que lo soliciten sin consentimiento previo al afectado solamente cuando les sean necesarios para el ejercicio de sus respectivas competencias.',c:'Se cederán a otras administraciones públicas exclusivamente para asuntos en los que la residencia o el domicilio sean datos relevantes.',d:'Pueden servir para elaborar estadísticas oficiales sometidas al secreto estadístico.'}, correct:'a', why:{a:'La opción a) es incorrecta: los datos del padrón municipal sí pueden cederse a otras administraciones públicas para el ejercicio de sus competencias.'}},
{n:35, q:'De conformidad con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, la inscripción en el Padrón municipal podrá recoger la aportación voluntaria de los datos relativos:', o:{a:'A la designación de las personas que pueden representar a cada vecino ante la administración municipal a efectos padronales.',b:'Al número de teléfono de contacto y la dirección de correo electrónico.',c:'A lo reflejado en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art. 16 LRBRL establece que la inscripción en el padrón municipal podrá recoger la aportación voluntaria de los datos relativos a la designación de representantes padronales y al número de teléfono y correo electrónico.'}},
{n:36, q:'Respecto a los datos de aportación voluntaria en el Padrón municipal, indique la afirmación correcta:', o:{a:'No serán susceptibles de cesión en ningún caso.',b:'Se cederán a otras administraciones públicas que lo soliciten sin consentimiento previo al afectado solamente cuando les sean necesarios para el ejercicio de sus respectivas competencias.',c:'Se cederán a otras administraciones públicas exclusivamente para asuntos en los que la residencia o el domicilio sean datos relevantes.',d:'Pueden servir para elaborar estadísticas oficiales sometidas al secreto estadístico.'}, correct:'a', why:{a:'El art. 16 LRBRL establece que los datos de aportación voluntaria al padrón no serán susceptibles de cesión en ningún caso.'}},
{n:37, q:'Con respecto al padrón municipal, indique la afirmación incorrecta:', o:{a:'La formación, mantenimiento, revisión y custodia del padrón municipal corresponde al ayuntamiento, de acuerdo con lo que establezca la legislación del Estado.',b:'Las diputaciones provinciales, cabildos y consejos insulares asumirán la gestión administrativa de los padrones de los municipios que, por su insuficiente capacidad económica y de gestión, no puedan mantener los datos de forma que garantice su seguridad.',c:'Los ayuntamientos realizarán las actuaciones y operaciones necesarias para mantener actualizados sus padrones de modo que los datos contenidos en éstos concuerden con la realidad.',d:'Si un ayuntamiento no llevara a cabo las actuaciones que legalmente el corresponden, el Instituto Nacional de Estadística, previo informe del Consejo de Empadronamiento, podrá requerirle previamente concretando la inactividad, y si fuere rechazado, sin perjuicio de los recursos jurisdiccionales que procedan, podrá acudir a la ejecución sustitutoria prevista en el artículo 60 de la Ley 7/1985.'}, correct:'b', why:{b:'La opción b) es incorrecta: las diputaciones provinciales asumirán la gestión cuando los municipios no puedan mantener los datos de forma que garantice su seguridad, no solo su automatización.'}},
{n:38, q:'La gestión del padrón municipal se llevará por los ayuntamientos:', o:{a:'Con medios informáticos.',b:'Con cualquier medio que garantice su seguridad.',c:'Con medios manuales o electrónicos, según la disponibilidad.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 17 LRBRL establece que la gestión del padrón municipal se llevará por los ayuntamientos con medios informáticos.'}},
{n:39, q:'Las diputaciones provinciales o entidades equivalentes, cabildos y consejos insulares asumirán la gestión informatizada de los padrones de los municipios que, por su insuficiente capacidad económica y de gestión:', o:{a:'No puedan mantener los datos de forma automatizada.',b:'No puedan garantizar la seguridad de los datos registrados.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'El art. 17 LRBRL establece que las diputaciones asumirán la gestión informatizada de los padrones de los municipios que no puedan mantener los datos de forma automatizada o garantizar su seguridad.'}},
{n:40, q:'Según lo establecido en el RDL 6/2023, que modifica algunos artículos de la Ley 7/1985, corresponderá a la persona que ejerza la Presidencia del Instituto Nacional de Estadística:', o:{a:'La resolución de las discrepancias que, en materia de empadronamiento, surjan entre los Ayuntamientos, Diputaciones Provinciales o entidades equivalentes, Cabildos y Consejos insulares o entre estos entes y el Instituto Nacional de Estadística.',b:'Elevar al Gobierno de la Nación la propuesta de cifras oficiales de población de los municipios españoles, comunicándolo en los términos que reglamentariamente se determinan al Ayuntamiento interesado.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'c', why:{c:'Según el RDL 6/2023, las funciones descritas corresponden al Instituto Nacional de Estadística pero no necesariamente a la Presidencia del mismo. Según el solucionario la respuesta es c.'}},
{n:41, q:'La "Organización" es uno de los elementos del municipio y la Ley 7/1985, Reguladora de las Bases del Régimen Local, dedica a ella:', o:{a:'El Capítulo Primero, del Título I, artículos 15 a 17.',b:'El Capítulo Segundo, del Título II, artículos 19 a 24 bis.',c:'El Capítulo Tercero, del Título I, artículos 25 a 29 ter.',d:'El Capítulo Cuarto, del Título II, artículos 34 a 39 bis.'}, correct:'b', why:{b:'La LRBRL dedica a la Organización del Municipio el Capítulo Segundo del Título II, artículos 19 a 24 bis.'}},
{n:42, q:'La Ley 7/1985, Reguladora de las Bases del Régimen Local, establece dos regímenes de organización municipal, siendo éstos:', o:{a:'El de los municipios de gran población regulados en el título X (art.121 a 138) y el de los municipios de régimen común, de aplicación a todos los demás municipios y también a los anteriores de modo supletorio.',b:'El de los municipios de gran población y el de los municipios en régimen de concejo abierto.',c:'El de los municipios de régimen común o de gran población y el de los municipios con población inferior a 5000 habitantes.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'La LRBRL establece dos regímenes de organización municipal: el de los municipios de gran población (Título X, arts. 121-138) y el régimen común, aplicable a todos los demás municipios y supletoriamente a los de gran población.'}},
{n:43, q:'Los órganos de gobierno de los Ayuntamientos pueden ser:', o:{a:'Órganos políticos y personal al servicio de la Corporación.',b:'Órganos políticos y órganos administrativos.',c:'Órganos unipersonales y órganos colegiados.',d:'Las respuestas b y c son correctas.'}, correct:'c', why:{c:'Los órganos de gobierno de los Ayuntamientos pueden ser unipersonales (como el Alcalde) y colegiados (como el Pleno o la Junta de Gobierno Local).'}},
{n:44, q:'Son órganos unipersonales de gobierno de los Ayuntamientos:', o:{a:'El Alcalde y los Tenientes de Alcalde exclusivamente.',b:'Los Concejales exclusivamente.',c:'El Alcalde exclusivamente.',d:'El Alcalde, los Concejales y los Tenientes de Alcalde.'}, correct:'d', why:{d:'El art. 19 LRBRL establece que son órganos del Ayuntamiento el Alcalde, los Tenientes de Alcalde y los Concejales, siendo los unipersonales el Alcalde y los Tenientes de Alcalde.'}},
{n:45, q:'De conformidad con la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, y con respecto al régimen de gestión compartida, indique la respuesta correcta:', o:{a:'El programa de reorganización de la gestión municipal se articulará a través de convenios suscritos entre el municipio y la diputación provincial respectiva, así como a través de fórmulas de colaboración que se determinen con los diferentes departamentos de la Generalitat.',b:'La aplicación de éste régimen especial se llevará a efecto, previo informe del municipio correspondiente, mediante Decreto del Consell.',c:'Este régimen requiere la petición de la mayoría de los vecinos y el acuerdo favorable de dos tercios del número legal de miembros del Ayuntamiento.',d:'El gobierno y administración de estos municipios corresponde al alcalde, a la asamblea vecinal y a una comisión mixta de diputados provinciales y de las Cortes Valencianas.'}, correct:'d', why:{d:'La Ley 8/2010 de Régimen Local de la Comunitat Valenciana establece que en el régimen de gestión compartida el gobierno corresponde al alcalde, a la asamblea vecinal y a una comisión mixta. Según el solucionario la respuesta es d.'}},
{n:46, q:'De conformidad con la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, y con respecto al régimen de gestión compartida, indique la respuesta incorrecta:', o:{a:'El régimen de gestión compartida podrá aplicarse a municipios con población inferior a 500 habitantes.',b:'Este régimen requiere la petición de la mayoría de los vecinos y el acuerdo favorable de dos tercios del número legal de miembros del Ayuntamiento.',c:'Este régimen se podrá aplicar a municipios con población comprendida entre 500 y 1000 habitantes en los que la evolución demográfica sea negativa de forma persistente.',d:'La aplicación de este régimen supondrá la dispensa en la prestación de los servicios municipales obligatorios, el diseño de un régimen simplificado de organización y funcionamiento mediante un sistema de gestión compartida que se articulará a través de convenios entre el municipio y la diputación provincial.'}, correct:'c', why:{c:'La opción c) es incorrecta: el régimen de gestión compartida se puede aplicar a municipios entre 500 y 1000 habitantes cuando la evolución demográfica sea negativa de forma persistente.'}},
{n:47, q:'La Ley 7/1985, Reguladora de las Bases del Régimen Local, se refiere a la organización y funcionamiento de los Municipios de gran población:', o:{a:'En el Título X, artículos 121 a 138.',b:'En el Título I, Capítulo II, artículos 21 a 28.',c:'En el Título II, artículos 29 a 38.',d:'En el Título IV, artículos 91 a 98.'}, correct:'a', why:{a:'La LRBRL regula la organización y funcionamiento de los Municipios de gran población en el Título X, artículos 121 a 138.'}},
{n:48, q:'La Ley 7/1985, Reguladora de las Bases del Régimen Local, para los Ayuntamientos de municipios considerados "de gran población", con respecto a los que no gozan de tal cualidad, establece:', o:{a:'Un reparto de competencias distinto.',b:'Un reparto de competencias progresivo y proporcional.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'La LRBRL para los municipios de gran población establece una organización diferente, no un reparto de competencias distinto o progresivo. Según el solucionario la respuesta es d.'}},
{n:49, q:'La Ley 7/85, Reguladora de las Bases del Régimen Local, establece cuales son los municipios considerados de gran población:', o:{a:'En su artículo 127.',b:'En su artículo 121.',c:'En su artículo 131.',d:'En su artículo 137.'}, correct:'d', why:{d:'La LRBRL establece cuáles son los municipios de gran población en su artículo 121. Según el solucionario la respuesta es d.'}},
{n:50, q:'El régimen de organización de los municipios de gran población es aplicable, en todo caso:', o:{a:'A los municipios cuya población supere los 250.000 habitantes.',b:'A los municipios que sean capitales de provincia.',c:'A los municipios reflejados en las respuestas a) y b).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 121 LRBRL establece que el régimen de los municipios de gran población es aplicable en todo caso a los municipios cuya población supere los 250.000 habitantes.'}},
{n:51, q:'El régimen de organización de los municipios de gran población es aplicable, en todo caso:', o:{a:'A los municipios capitales de provincia cuya población supere los 175.000 habitantes.',b:'A los municipios que sean capital de Comunidad Autónoma.',c:'A los municipios reflejados en las respuestas a) y b).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 121 LRBRL establece que el régimen de los municipios de gran población es aplicable en todo caso a los municipios capitales de provincia con más de 175.000 habitantes y a los que sean capital de Comunidad Autónoma.'}},
{n:52, q:'El régimen de organización de los municipios de gran población es aplicable:', o:{a:'A los municipios que sean capitales de provincia, capitales autonómicas o sedes de las instituciones autonómicas.',b:'A los municipios cuya población supere los 75.000 habitantes, que presenten circunstancias económicas, sociales, históricas o culturales especiales.',c:'A los municipios reflejados en las respuestas a y b), aunque se les exigirá que así lo decidan las Asambleas Legislativas correspondientes a iniciativa de los respectivos ayuntamientos.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 121 LRBRL establece que el régimen de los municipios de gran población es aplicable a los municipios con más de 75.000 habitantes que presenten circunstancias económicas, sociales, históricas o culturales especiales.'}},
{n:53, q:'El régimen de organización de los municipios de gran población es aplicable:', o:{a:'A los municipios cuya población supere los 250.000 habitantes, y a los que sean capitales de provincia con población superior a los 175.000 habitantes, en todo caso.',b:'A los municipios cuya población supere los 75.000 habitantes, que presenten circunstancias económicas, sociales, históricas o culturales especiales siempre y cuando lo decidan las asambleas legislativas correspondientes a iniciativa de los respectivos Ayuntamientos.',c:'A los municipios que sean capitales de provincia, capitales autonómicas o sedes de instituciones autonómicas, siempre y cuando lo decidan las asambleas legislativas correspondientes a iniciativa de los respectivos Ayuntamientos.',d:'A todos los municipios reflejados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 121 LRBRL establece todos estos supuestos de aplicación del régimen de los municipios de gran población.'}},
{n:54, q:'Cuando un municipio alcance la población requerida para la aplicación del régimen de organización de municipio de gran población, la nueva corporación deberá adaptar su organización al contenido de las disposiciones previstas en el Título X de la Ley 7/1985:', o:{a:'En el plazo máximo de seis meses desde su constitución.',b:'En el plazo máximo de cinco meses desde su constitución.',c:'En el plazo máximo de cuatro meses desde su constitución.',d:'En el plazo máximo de tres meses desde su constitución.'}, correct:'b', why:{b:'El art. 121 LRBRL establece que cuando un municipio alcance la población requerida, la nueva corporación deberá adaptar su organización en el plazo máximo de cinco meses desde su constitución.'}},
{n:55, q:'Cuando un municipio alcance la población requerida para la aplicación del régimen de organización de municipio de gran población, la nueva corporación deberá adaptar su organización al contenido de las disposiciones previstas en el Título X de la Ley 7/1985, teniendo en cuenta:', o:{a:'Exclusivamente la población resultante de la revisión del padrón, con referencia al 1 de enero del año anterior al del inicio de cada mandato de su ayuntamiento.',b:'Exclusivamente la población resultante del padrón actualizado.',c:'La población correspondiente a otros años de cada mandato.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 121 LRBRL establece que para la aplicación del régimen de los municipios de gran población se tiene en cuenta exclusivamente la población resultante de la revisión del padrón con referencia al 1 de enero del año anterior al inicio de cada mandato.'}},
{n:56, q:'Los municipios a los que resulte de aplicación el régimen de organización de los municipios de gran población:', o:{a:'Dispondrá del plazo máximo de tres meses para adaptar su organización a las disposiciones previstas en el título X de la Ley 7/1985.',b:'Continuarán rigiéndose por el mismo aun cuando su cifra oficial de población se reduzca posteriormente por debajo del límite establecido en la Ley 7/1985.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 121 LRBRL establece que los municipios que resulte de aplicación el régimen de gran población continuarán rigiéndose por el mismo aun cuando su población se reduzca posteriormente por debajo del límite establecido.'}},
{n:57, q:'De conformidad con la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, y con respecto al régimen de gestión compartida, indique la respuesta correcta:', o:{a:'Puede aplicarse a municipios entre 500 y 1000 habitantes, en los que la evolución demográfica sea negativa de forma persistente.',b:'Podrá aplicarse a los municipios reflejados en las respuestas a) y b).',c:'Ninguna de las respuestas anteriores es correcta.',d:'Las respuestas a) y b) son correctas.'}, correct:'c', why:{c:'El régimen de gestión compartida de la Ley 8/2010 CV puede aplicarse a municipios con población inferior a 500 habitantes. Según el solucionario la respuesta es c.'}},
{n:58, q:'De conformidad con la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, y con respecto al régimen de gestión compartida, indique la respuesta correcta:', o:{a:'El programa de reorganización de la gestión municipal se articulará a través de convenios suscritos entre el municipio y la diputación provincial respectiva, así como a través de fórmulas de colaboración que se determinen con los diferentes departamentos de la Generalitat.',b:'La aplicación de éste régimen especial se llevará a efecto, previo informe del municipio correspondiente, mediante Decreto del Consell.',c:'Este régimen requiere la petición de la mayoría de los vecinos y el acuerdo favorable de dos tercios del número legal de miembros del Ayuntamiento.',d:'El gobierno y administración de estos municipios corresponde al alcalde, a la asamblea vecinal y a una comisión mixta de diputados provinciales y de las Cortes Valencianas.'}, correct:'a', why:{a:'La Ley 8/2010 CV establece que el programa de reorganización de la gestión municipal se articulará a través de convenios con la diputación provincial y con los departamentos de la Generalitat.'}},
{n:59, q:'De conformidad con la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, y con respecto al régimen de gestión compartida, indique la respuesta incorrecta:', o:{a:'El régimen de gestión compartida podrá aplicarse a municipios con población inferior a 500 habitantes.',b:'Este régimen requiere la petición de la mayoría de los vecinos y el acuerdo favorable de dos tercios del número legal de miembros del Ayuntamiento.',c:'Este régimen se podrá aplicar a municipios con población comprendida entre 500 y 1000 habitantes en los que la evolución demográfica sea negativa de forma persistente.',d:'La aplicación de este régimen supondrá la dispensa en la prestación de los servicios municipales obligatorios.'}, correct:'b', why:{b:'La opción b) es incorrecta: el régimen de gestión compartida no requiere la petición de la mayoría de los vecinos ni el acuerdo favorable de dos tercios del Ayuntamiento.'}},
{n:60, q:'Según el art.130 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, son Órganos superiores en municipios de gran población:', o:{a:'El Alcalde y los miembros de la Junta de Gobierno Local.',b:'Los coordinadores generales de cada área o concejalía.',c:'Los directores generales u órganos similares que culminen la organización administrativa dentro de cada una de las grandes áreas o concejalías.',d:'Todos los citados en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 130 LRBRL establece que son órganos superiores en municipios de gran población el Alcalde y los miembros de la Junta de Gobierno Local.'}},
{n:61, q:'Según el art.130 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, son Órganos directivos en municipios de gran población:', o:{a:'Los coordinadores generales de cada área o concejalía.',b:'Los directores generales u órganos similares que culminen la organización administrativa dentro de cada una de las grandes áreas o concejalías.',c:'El titular del órgano de apoyo a la Junta de Gobierno Local y al concejal-secretario de la misma.',d:'Todos los citados en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 130 LRBRL establece que son órganos directivos en municipios de gran población los coordinadores generales de cada área o concejalía.'}},
{n:62, q:'Según el art.130 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, son Órganos directivos en municipios de gran población:', o:{a:'El titular de la asesoría jurídica y, en su caso, el titular del órgano de gestión tributaria.',b:'El Secretario general del Pleno y el interventor general municipal.',c:'Los citados en las respuestas a y b.',d:'Todas las respuestas son incorrectas.'}, correct:'b', why:{b:'El art. 130 LRBRL establece que son órganos directivos en municipios de gran población el Secretario general del Pleno y el interventor general municipal.'}},
{n:63, q:'Además de los establecidos expresamente en el art.130 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, tendrán también la consideración de Órganos directivos en municipios de gran población:', o:{a:'Los titulares de los máximos órganos de dirección de los organismos autónomos.',b:'Los titulares de los máximos órganos de dirección de las entidades públicas empresariales locales.',c:'Los citados en las respuestas a y b.',d:'Todas las respuestas son incorrectas.'}, correct:'a', why:{a:'El art. 130 LRBRL establece que además de los órganos directivos expresamente establecidos, también tendrán esa consideración los titulares de los máximos órganos de dirección de los organismos autónomos.'}},
{n:64, q:'En municipios de gran población, el nombramiento de los coordinadores generales y de los directores generales, atendiendo a criterios de competencia profesional y experiencia, deberá efectuarse:', o:{a:'Entre funcionarios de carrera del Estado, de las Comunidades Autónomas, de las Entidades Locales o con habilitación de carácter nacional.',b:'Entre funcionaros de carrera que pertenezcan a cuerpos o escalas clasificados en el subgrupo A1, salvo que el Reglamento Orgánico Municipal permita que, en atención a las características específicas de las funciones de tales órganos directivos, su titular no reúna dicha condición de funcionario.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'El art. 130 LRBRL establece que los coordinadores y directores generales deben nombrarse entre funcionarios de carrera del Estado, CCAA, Entidades Locales o con habilitación de carácter nacional.'}},
{n:65, q:'Los órganos superiores y directivos de los municipios de gran población, quedan sometidos al régimen de incompatibilidades establecido:', o:{a:'En la Ley 53/1984 de Incompatibilidades del personal al servicio de las Administraciones públicas, y en otras normas estatales o autonómicas que resulten de aplicación.',b:'En el RDL 17/1998 de Incompatibilidades del personal al servicio de las Administraciones Públicas de ámbito local y autonómico.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'c', why:{c:'Los órganos superiores y directivos de los municipios de gran población quedan sometidos al régimen de incompatibilidades de la Ley 53/1984, de la LRBRL y de otras normas aplicables. Según el solucionario la respuesta es c.'}},
{n:66, q:'La Ley 7/1985, Reguladora de las Bases del Régimen Local, dedica sus artículos 122 y 123:', o:{a:'Al Alcalde de los municipios de gran población.',b:'Al Pleno de los municipios de gran población.',c:'A la Junta de gobierno Local de los municipios de gran población.',d:'A todos los órganos citados en las respuestas anteriores.'}, correct:'d', why:{d:'La LRBRL dedica los artículos 122 y 123 al Pleno y a la Junta de Gobierno Local de los municipios de gran población. Según el solucionario la respuesta es d.'}},
{n:67, q:'Con respecto al Pleno de los municipios de gran población, indique la afirmación incorrecta:', o:{a:'El Pleno, formado por el Alcalde y los Concejales, es el órgano de máxima representación política de los ciudadanos en el gobierno municipal.',b:'El Pleno será convocado y presidido por el Alcalde, salvo en los supuestos previstos en esta ley y en la legislación electoral general, al que corresponde decidir los empates con voto de calidad.',c:'El Pleno puede delegar todas sus competencias en el Alcalde o en las Comisiones del pleno, dependiendo de la materia de que se trate.',d:'El Pleno se dotará de su propio reglamento, que tendrá la naturaleza de orgánico. No obstante, la regulación de su organización y funcionamiento podrá contenerse también en el reglamento orgánico municipal.'}, correct:'a', why:{a:'La opción a) es incorrecta: el Pleno de los municipios de gran población está formado por el Alcalde y los Concejales, pero el Alcalde NO forma parte del Pleno en el régimen de gran población.'}},
{n:68, q:'En Municipios de gran población, el Ayuntamiento Pleno es competente para:', o:{a:'La aprobación y modificación de los Reglamentos de naturaleza orgánica.',b:'Acordar la creación de organismos autónomos, entidades públicas empresariales y sociedades mercantiles para la gestión de servicios de competencia municipal.',c:'Establecer el régimen retributivo del Secretario General del Pleno.',d:'Todo lo reflejado en las respuestas anteriores.'}, correct:'a', why:{a:'En municipios de gran población el Pleno es competente para la aprobación y modificación de los Reglamentos de naturaleza orgánica.'}},
{n:69, q:'En Municipios de gran población, el Ayuntamiento Pleno es competente para:', o:{a:'Establecer el régimen retributivo de sus propios miembros y del Alcalde.',b:'Establecer el régimen retributivo de los miembros de la Junta de Gobierno Local.',c:'Establecer el régimen retributivo de los reflejados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'En municipios de gran población el Pleno es competente para establecer el régimen retributivo de los miembros de la Junta de Gobierno Local.'}},
{n:70, q:'En Municipios de gran población, el Ayuntamiento Pleno es competente para:', o:{a:'Establecer el régimen retributivo de los órganos directivos municipales.',b:'Establecer el régimen retributivo de los funcionarios con habilitación de carácter estatal.',c:'Establecer el régimen retributivo de los reflejados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'En municipios de gran población el Pleno es competente para establecer el régimen retributivo de los órganos directivos municipales.'}},
{n:71, q:'Indique cual de las siguientes no es competencia del Pleno del Ayuntamiento en municipios de gran población:', o:{a:'Establecer directrices generales de la acción de gobierno municipal y asegurar su continuidad.',b:'El control y la fiscalización de los órganos de gobierno.',c:'La votación de la moción de censura al Alcalde y de la cuestión de confianza planteada por éste, que será pública y se realizará mediante llamamiento nominal en todo caso y se regirá en todos sus aspectos por lo dispuesto en la legislación electoral general.',d:'La aprobación y modificación de las ordenanzas y reglamentos municipales.'}, correct:'d', why:{d:'La aprobación y modificación de las ordenanzas y reglamentos municipales es competencia del Pleno en el régimen común, pero en municipios de gran población puede haber variaciones. Según el solucionario la respuesta es d.'}},
{n:72, q:'Indique cual de las siguientes no es competencia del Pleno del Ayuntamiento en municipios de gran población:', o:{a:'Los acuerdos relativos a la participación en organizaciones supramunicipales y la determinación de los recursos propios de carácter tributario.',b:'La aprobación de los presupuestos, de la plantilla de personal, así como la autorización de gastos en las materias de su competencia. Asimismo, aprobará la cuenta general del ejercicio correspondiente.',c:'Establecer directrices generales de la acción de gobierno municipal y asegurar su continuidad.',d:'La aprobación inicial del planeamiento general y la aprobación que ponga fin a la tramitación municipal de los planes y demás instrumentos de ordenación previstos en la legislación urbanística.'}, correct:'c', why:{c:'Establecer directrices generales de la acción de gobierno municipal es competencia de la Junta de Gobierno Local en municipios de gran población, no del Pleno. Según el solucionario la respuesta es c.'}},
{n:73, q:'Según el art.130 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, son Órganos superiores en municipios de gran población:', o:{a:'El Alcalde y los miembros de la Junta de Gobierno Local.',b:'Los coordinadores generales de cada área o concejalía.',c:'Los citados en las respuestas a y b.',d:'Todas las respuestas son incorrectas.'}, correct:'c', why:{c:'El art. 130 LRBRL establece que son órganos superiores en municipios de gran población el Alcalde y los miembros de la Junta de Gobierno Local.'}},
{n:74, q:'Según el art.130 de la Ley 7/1985, son Órganos directivos en municipios de gran población:', o:{a:'El titular de la asesoría jurídica y, en su caso, el titular del órgano de gestión tributaria.',b:'El Secretario general del Pleno y el interventor general municipal.',c:'Los coordinadores generales de cada área o concejalía.',d:'Todos los citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 130 LRBRL establece que son órganos directivos los coordinadores generales, directores generales, el Secretario general del Pleno, el interventor general y el titular de la asesoría jurídica.'}},
{n:75, q:'En municipios de gran población, el nombramiento de los coordinadores generales y directores generales deberá efectuarse:', o:{a:'Entre funcionarios de carrera del Estado, de las Comunidades Autónomas, de las Entidades Locales o con habilitación de carácter nacional.',b:'Entre funcionaros de carrera del subgrupo A1, salvo que el ROM permita excepción atendiendo a las características de las funciones.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'El art. 130 LRBRL establece que los coordinadores y directores generales deben nombrarse entre funcionarios de carrera del Estado, CCAA o Entidades Locales, o con habilitación de carácter nacional.'}},
{n:76, q:'La Ley 7/1985, Reguladora de las Bases del Régimen Local, dedica sus artículos 122 y 123:', o:{a:'Al Alcalde de los municipios de gran población.',b:'Al Pleno de los municipios de gran población.',c:'A la Junta de gobierno Local de los municipios de gran población.',d:'A todos los órganos citados en las respuestas anteriores.'}, correct:'b', why:{b:'La LRBRL dedica los artículos 122 y 123 al Pleno de los municipios de gran población.'}},
{n:77, q:'Con respecto al Pleno de los municipios de gran población, indique la afirmación incorrecta:', o:{a:'El Pleno, formado por el Alcalde y los Concejales, es el órgano de máxima representación política.',b:'El Pleno será convocado y presidido por el Alcalde, salvo los supuestos previstos en esta ley y en la legislación electoral general.',c:'El Pleno puede delegar todas sus competencias en el Alcalde o en las Comisiones del pleno.',d:'El Pleno se dotará de su propio reglamento de naturaleza orgánica.'}, correct:'c', why:{c:'La opción c) es incorrecta: el Pleno NO puede delegar todas sus competencias; hay competencias indelegables del Pleno en los municipios de gran población.'}},
{n:78, q:'En Municipios de gran población, el Ayuntamiento Pleno es competente para:', o:{a:'La aprobación y modificación de los Reglamentos de naturaleza orgánica.',b:'Acordar la creación de organismos autónomos, entidades públicas empresariales y sociedades mercantiles para la gestión de servicios de competencia municipal.',c:'Establecer el régimen retributivo del Secretario General del Pleno.',d:'Todo lo reflejado en las respuestas anteriores.'}, correct:'d', why:{d:'En municipios de gran población el Pleno es competente para la aprobación de reglamentos orgánicos, la creación de organismos autónomos y el establecimiento del régimen retributivo del Secretario General del Pleno.'}},
{n:79, q:'En Municipios de gran población, el Ayuntamiento Pleno es competente para:', o:{a:'Establecer el régimen retributivo de sus propios miembros y del Alcalde.',b:'Establecer el régimen retributivo de los miembros de la Junta de Gobierno Local.',c:'Establecer el régimen retributivo de los reflejados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'En municipios de gran población el Pleno es competente para establecer el régimen retributivo de sus propios miembros y del Alcalde. Según el solucionario la respuesta es d.'}},
{n:80, q:'En Municipios de gran población, el Ayuntamiento Pleno es competente para:', o:{a:'Establecer el régimen retributivo de los órganos directivos municipales.',b:'Establecer el régimen retributivo de los funcionarios con habilitación de carácter estatal.',c:'Establecer el régimen retributivo de los reflejados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'En municipios de gran población el Pleno es competente para establecer el régimen retributivo de los órganos directivos municipales.'}},
{n:81, q:'Indique cual de las siguientes no es competencia del Pleno del Ayuntamiento en municipios de gran población:', o:{a:'Establecer directrices generales de la acción de gobierno municipal y asegurar su continuidad.',b:'El control y la fiscalización de los órganos de gobierno.',c:'La votación de la moción de censura al Alcalde y de la cuestión de confianza planteada por éste, que será pública y se realizará mediante llamamiento nominal en todo caso y se regirá en todos sus aspectos por lo dispuesto en la legislación electoral general.',d:'La aprobación y modificación de las ordenanzas y reglamentos municipales.'}, correct:'c', why:{c:'La opción c) no es competencia del Pleno en su sentido de "no competencia". La votación de la moción de censura sí es competencia del Pleno. Según el solucionario la respuesta es c.'}},
{n:82, q:'Indique cual de las siguientes no es competencia del Pleno del Ayuntamiento en municipios de gran población:', o:{a:'Los acuerdos relativos a la participación en organizaciones supramunicipales y la determinación de los recursos propios de carácter tributario.',b:'La aprobación de los presupuestos, de la plantilla de personal, así como la autorización de gastos en las materias de su competencia. Asimismo, aprobará la cuenta general del ejercicio correspondiente.',c:'Establecer directrices generales de la acción de gobierno municipal y asegurar su continuidad.',d:'La aprobación inicial del planeamiento general y la aprobación que ponga fin a la tramitación municipal de los planes y demás instrumentos de ordenación previstos en la legislación urbanística.'}, correct:'c', why:{c:'Establecer directrices generales de la acción de gobierno municipal es competencia de la Junta de Gobierno Local, no del Pleno, en municipios de gran población.'}},
{n:83, q:'Indique cual de las siguientes no es competencia del Pleno del Ayuntamiento en municipios de gran población:', o:{a:'Establecer la organización y estructura de la Administración municipal ejecutiva, sin perjuicio de las competencias atribuidas a otros órganos.',b:'Los acuerdos relativos a la delimitación y alteración del término municipal.',c:'La creación o supresión de las entidades de ámbito territorial al municipio, la alteración de la capitalidad del municipio y el cambio de denominación de éste o de aquellas entidades.',d:'La adopción o modificación de su bandera, enseña o escudo.'}, correct:'a', why:{a:'La opción a) no es competencia del Pleno en municipios de gran población: establecer la organización y estructura de la Administración municipal ejecutiva corresponde al Alcalde.'}},
{n:84, q:'Si un municipio de gran población desea adoptar un acuerdo relativo a la alteración de la capitalidad del mismo ¿qué órgano debe aprobar este acuerdo?', o:{a:'La Junta de Gobierno Local.',b:'El Pleno.',c:'El Alcalde.',d:'Quien determine su propio Reglamento Orgánico.'}, correct:'b', why:{b:'El art. 123 LRBRL establece que la alteración de la capitalidad del municipio es competencia del Pleno del Ayuntamiento.'}},
{n:85, q:'Indique cual de las siguientes no es competencia del Pleno del Ayuntamiento en municipios de gran población:', o:{a:'La transferencia de funciones o actividades a otras Administraciones públicas, así como la aceptación de las delegaciones o encomiendas de gestión realizadas por otras Administraciones, salvo que por ley se impongan obligatoriamente.',b:'Ordenar la publicación, ejecución y cumplimiento de los acuerdos de los órganos ejecutivos del ayuntamiento.',c:'La determinación de las formas de gestión de los servicios y la aprobación de los expedientes de municipalización.',d:'Las facultades de revisión de oficio de sus propios actos y disposiciones de carácter general.'}, correct:'b', why:{b:'La opción b) no es competencia del Pleno: ordenar la publicación, ejecución y cumplimiento de los acuerdos de los órganos ejecutivos corresponde al Alcalde.'}},
{n:86, q:'Además de las competencias que expresamente le confieran las leyes, el Pleno del Ayuntamiento en municipios de gran población es competente para:', o:{a:'El ejercicio de acciones judiciales y administrativas y la defensa jurídica del Pleno en las materias de su competencia.',b:'El planteamiento de conflictos de competencia a otras entidades locales y otras Administraciones públicas.',c:'Acordar la iniciativa prevista en el último inciso del artículo 121.1, para que el municipio pueda ser incluido en el ámbito de aplicación del título X de esta ley.',d:'Todo lo reflejado en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 123 LRBRL establece que el Pleno es competente para el ejercicio de acciones judiciales, el planteamiento de conflictos de competencia y acordar la iniciativa para ser incluido en el régimen de gran población.'}},
{n:87, q:'En municipios de gran población, tienen la consideración de Reglamentos de naturaleza orgánica:', o:{a:'El que se ocupa de la regulación del Pleno.',b:'El que regula el Consejo Social de la Ciudad.',c:'El que regula la Comisión Especial de Sugerencias y Reclamaciones.',d:'Todos los reflejados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 123 LRBRL establece que tienen la consideración de reglamentos de naturaleza orgánica los que regulan el Pleno, el Consejo Social de la Ciudad y la Comisión Especial de Sugerencias y Reclamaciones.'}},
{n:88, q:'En municipios de gran población, tienen la consideración de Reglamentos de naturaleza orgánica:', o:{a:'El que se ocupa de la regulación de los procedimientos de participación ciudadana.',b:'El que regula los órganos complementarios.',c:'El que se ocupa de la división del municipio en distritos.',d:'Todos los reflejados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 123 LRBRL establece que también tienen la consideración de reglamentos orgánicos los que regulan los procedimientos de participación ciudadana, los órganos complementarios y la división en distritos.'}},
{n:89, q:'En municipios de gran población, tienen la consideración de Reglamentos de naturaleza orgánica:', o:{a:'El que se ocupa de la determinación de los niveles esenciales de la organización municipal.',b:'El que regule el órgano para la resolución de reclamaciones económico administrativas.',c:'Los reflejados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 123 LRBRL establece que también tienen la consideración de reglamentos orgánicos los que determinan los niveles esenciales de la organización municipal y los que regulan el órgano de resolución de reclamaciones económico-administrativas.'}},
{n:90, q:'En municipios de gran población, el voto favorable de la mayoría absoluta del número legal de miembros del Pleno, se requiere:', o:{a:'Para la adopción de los acuerdos referidos en los párrafos c), e), f), j) y o) del art.123.1 de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',b:'Para la adopción de los acuerdos referidos en los párrafos a), d), h) y p) del art.123.1 de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',c:'Para la adopción de los acuerdos reflejados en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 123.2 LRBRL establece que se requiere el voto favorable de la mayoría absoluta del número legal de miembros del Pleno para los acuerdos referidos en los párrafos c), e), f), j) y o) del art. 123.1.'}},
{n:91, q:'En municipios de gran población, el voto favorable de la mayoría absoluta del número legal de miembros del Pleno, se requiere:', o:{a:'Para los acuerdos que corresponda adoptar al Pleno en la tramitación de los instrumentos de planeamiento general previstos en la legislación urbanística.',b:'Para la adopción de los acuerdos referidos en los párrafos a), d), h) y p) del art.123.1 de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',c:'Para la adopción de los acuerdos reflejados en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 123.2 LRBRL establece que también se requiere mayoría absoluta para los acuerdos del Pleno en la tramitación de los instrumentos de planeamiento general previstos en la legislación urbanística.'}},
{n:92, q:'En municipios de gran población, los acuerdos del Pleno se adoptarán:', o:{a:'Por mayoría absoluta para la adopción de los acuerdos referidos en los párrafos c), e), f), j) y o) del art.123.1 de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',b:'Por mayoría absoluta para los acuerdos que corresponda adoptar al Pleno en la tramitación de los instrumentos de planeamiento general previstos en la legislación urbanística.',c:'Por mayoría simple en acuerdos que no se encuentren entre los referidos en las respuestas a y b.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 123.2 LRBRL establece que los acuerdos del Pleno se adoptan por mayoría absoluta para los supuestos expresamente previstos y por mayoría simple para el resto.'}},
{n:93, q:'En municipios de gran población, el Pleno del Ayuntamiento:', o:{a:'Puede delegar determinadas competencias, pero solo en sus Comisiones.',b:'Puede delegar algunas competencias, pero solo en la Junta de Gobierno Local.',c:'Puede delegar cualquiera de sus competencias, pero solo en sus comisiones.',d:'Puede delegar algunas de sus competencias, pero solo en sus comisiones o en la Junta de Gobierno Local.'}, correct:'a', why:{a:'El art. 123 LRBRL establece que el Pleno puede delegar en sus Comisiones determinadas competencias, salvo las que requieren mayoría cualificada o son indelegables.'}},
{n:94, q:'En municipios de gran población, el Pleno del Ayuntamiento puede delegar en sus Comisiones:', o:{a:'La aprobación y modificación de las ordenanzas y reglamentos municipales.',b:'El ejercicio de acciones judiciales y administrativas y la defensa jurídica del Pleno en materias de su competencia.',c:'Lo reflejado en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El art. 123 LRBRL establece que el Pleno puede delegar en sus Comisiones el ejercicio de acciones judiciales y administrativas. La aprobación de ordenanzas no es delegable. Según el solucionario la respuesta es d.'}},
{n:95, q:'En municipios de gran población, el Pleno del Ayuntamiento puede delegar en sus Comisiones:', o:{a:'Las facultades de revisión de oficio de sus propios actos y disposiciones de carácter general.',b:'Los acuerdos relativos a la participación en organizaciones supramunicipales.',c:'Lo reflejado en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Las facultades de revisión de oficio y los acuerdos de participación en organizaciones supramunicipales son competencias indelegables del Pleno. Según el solucionario la respuesta es d.'}},
{n:96, q:'En municipios de gran población, el Pleno del Ayuntamiento puede delegar en sus Comisiones:', o:{a:'La determinación de las formas de gestión de los servicios y los acuerdos de creación de organismos autónomos, entidades públicas empresariales y sociedades mercantiles encargadas de realizar los servicios de competencia municipal.',b:'El planteamiento de conflictos de competencia a otras administraciones públicas.',c:'Lo reflejado en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 123 LRBRL permite al Pleno delegar en sus Comisiones la determinación de las formas de gestión de servicios y el planteamiento de conflictos de competencia.'}},
{n:97, q:'Si un municipio de gran población desea adoptar un acuerdo relativo al cambio de nombre de éste ¿qué órgano deberá aprobarlo?', o:{a:'El Pleno.',b:'El Alcalde.',c:'La Junta de Gobierno Local.',d:'La Comisión especial creada al efecto.'}, correct:'a', why:{a:'El art. 123 LRBRL establece que el cambio de nombre del municipio es competencia del Pleno.'}},
{n:98, q:'En municipios de gran población, el Pleno contará con un Secretario General, que lo será también de las comisiones, a quien corresponderá, entre otras funciones:', o:{a:'La redacción y custodia de las actas, así como la supervisión y autorización de las mismas, con el visto bueno del Presidente del Pleno.',b:'La expedición, con el visto bueno del Presidente del Pleno, de las certificaciones de los actos y acuerdos que se adopten.',c:'d) La comunicación, publicación y ejecución de los acuerdos plenarios.',d:'Le corresponderán todas las funciones citadas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 122 LRBRL establece que el Secretario General del Pleno tiene entre sus funciones la redacción y custodia de actas, la expedición de certificaciones y la comunicación y ejecución de los acuerdos plenarios.'}},
{n:99, q:'En municipios de gran población, el Pleno contará con un Secretario General, que lo será también de las comisiones, a quien corresponderá, entre otras funciones:', o:{a:'La asistencia al Presidente del Pleno para asegurar la convocatoria de las sesiones, el orden en los debates y la correcta celebración de las votaciones.',b:'La colaboración en el normal desarrollo de los trabajos del Pleno y de las comisiones.',c:'El asesoramiento legal al Pleno y a las Comisiones.',d:'Le corresponderán todas las funciones citadas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 122 LRBRL establece que el Secretario General también debe asistir al Presidente, colaborar en el desarrollo de los trabajos del Pleno y de las comisiones, y asesorar legalmente al Pleno.'}},
{n:100, q:'En municipios de gran población, el asesoramiento legal al Pleno y a las Comisiones por parte del Secretario General, será preceptivo:', o:{a:'Cuando así lo ordene el Presidente o cuando lo soliciten los miembros de las Comisiones y siempre que se trate de asuntos sobre materias para las que se exija una mayoría de dos tercios.',b:'Cuando una ley así lo exija en las materias de la competencia plenaria.',c:'Cuando, en el ejercicio de la función de control y fiscalización de los órganos de gobierno, lo solicite el Presidente o la mayoría de los Concejales.',d:'Será preceptivo en todos los casos citados en las respuestas anteriores.'}, correct:'b', why:{b:'El art. 122 LRBRL establece que el asesoramiento legal preceptivo del Secretario General al Pleno se produce cuando una ley así lo exija en las materias de la competencia plenaria.'}},
{n:101, q:'En municipios de gran población, las funciones del Secretario General quedan reservadas:', o:{a:'A funcionarios de administración local con habilitación de carácter nacional.',b:'A funcionarios de Administración General.',c:'A funcionarios del Grupo A, subgrupos A1 y A2.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 122 LRBRL establece que las funciones del Secretario General del Pleno en municipios de gran población quedan reservadas a funcionarios de administración local con habilitación de carácter nacional.'}},
{n:102, q:'En municipios de gran población, el asesoramiento legal al Pleno y a las Comisiones por parte del Secretario General, será preceptivo:', o:{a:'Cuando así lo ordene el Presidente o cuando lo solicite un tercio de sus miembros con antelación suficiente a la celebración de la sesión en que el asunto hubiere de tratarse.',b:'Siempre que se trate de asuntos sobre materias para las que se exija una mayoría especial y cuando una ley así lo exija en las materias de la competencia plenaria.',c:'Cuando, en el ejercicio de la función de control y fiscalización de los órganos de gobierno, lo solicite el Presidente o la cuarta parte, al menos, de los Concejales.',d:'Será preceptivo en todos los casos citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 122 LRBRL establece que el asesoramiento legal preceptivo del Secretario General es obligatorio en todos los supuestos descritos: cuando lo ordene el Presidente, cuando lo solicite un tercio de los miembros, cuando la ley lo exija y cuando lo solicite la cuarta parte de los Concejales en funciones de control.'}},
{n:103, q:'En municipios de gran población el Pleno dispondrá de una serie de Comisiones que estarán formadas:', o:{a:'Para el control de la gestión del personal al servicio del Ayuntamiento.',b:'Por los miembros que designen los grupos políticos, en proporción al número de concejales que tenga el Pleno.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 122 LRBRL establece que las Comisiones del Pleno estarán formadas por los miembros que designen los grupos políticos, en proporción al número de concejales que tenga el Pleno.'}},
{n:104, q:'En municipios de gran población, el Pleno dispondrá de una serie de Comisiones que estarán formadas por los miembros que designen los grupos políticos, siendo una de sus funciones:', o:{a:'El estudio, informe o consulta de los asuntos que han de ser sometidos a la decisión del Pleno y aquellas otras funciones que el Pleno les delegue.',b:'El seguimiento de la gestión del Alcalde y su equipo de gobierno.',c:'Aquéllas que el Pleno les delegue, de acuerdo con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local.',d:'Todas las reflejadas en las respuestas anteriores son funciones que corresponden a las Comisiones del Pleno.'}, correct:'d', why:{d:'El art. 122 LRBRL establece que las Comisiones del Pleno tienen como funciones: el estudio e informe de asuntos que han de ser sometidos al Pleno, el seguimiento de la gestión del Alcalde y las que el Pleno les delegue.'}},
{n:105, q:'En municipios de gran población, en todo caso, serán de aplicación a las Comisiones las previsiones referidas a la antelación con que deben convocarse las sesiones plenarias, el quorum exigido para celebrar válidamente las sesiones y las formas de votación de los asuntos sometidos a la aprobación del Pleno, conforme a lo previsto:', o:{a:'En el artículo 46.2, párrafos b), c) y d) de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',b:'En el artículo 46.2, párrafos e), j) y n) de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',c:'En el artículo 43.2 de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',d:'En el artículo 42.3 de la Ley 7/1985, Reguladora de las Bases del Régimen Local.'}, correct:'a', why:{a:'El art. 122 LRBRL establece que en todo caso serán de aplicación a las Comisiones las previsiones del art. 46.2, párrafos b), c) y d) de la LRBRL.'}},
{n:106, q:'De conformidad con lo establecido en el art.124 de la Ley 7/1985, Reguladora de las Bases de Régimen Local, en municipios de gran población, el Alcalde ostenta la máxima representación del municipio y es responsable de su gestión política ante el Pleno, teniendo tratamiento de:', o:{a:'Ilustrísima.',b:'Excelencia.',c:'Señoría.',d:'Señoría o Ilustrísima, según se trate de municipio capital de provincia o no.'}, correct:'b', why:{b:'El art. 124 LRBRL establece que el Alcalde en municipios de gran población tendrá tratamiento de Excelencia.'}},
{n:107, q:'En municipios de gran población, el alcalde...', o:{a:'Aprueba los proyectos de ordenanzas.',b:'Aprueba la relación de puestos de trabajo.',c:'Lo reflejado en las respuestas a y b) es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 124 LRBRL establece que el Alcalde en municipios de gran población aprueba los proyectos de ordenanzas y la relación de puestos de trabajo, entre otras competencias.'}},
{n:108, q:'Indique cual de las siguientes atribuciones no corresponde al Alcalde en municipios de gran población:', o:{a:'Representar al Ayuntamiento.',b:'El control y la fiscalización de los órganos de gobierno.',c:'Dirigir la política, el gobierno y la administración municipal, sin perjuicio de la acción colegiada de colaboración que realiza la Junta de Gobierno Local.',d:'Establecer directrices generales de la acción de gobierno municipal y asegurar su continuidad.'}, correct:'b', why:{b:'El control y la fiscalización de los órganos de gobierno no corresponde al Alcalde sino al Pleno del Ayuntamiento en municipios de gran población.'}},
{n:109, q:'En municipios de gran población no es competencia del Alcalde:', o:{a:'Determinar los recursos propios de carácter tributario.',b:'Nombrar y cesar a los Tenientes de Alcalde y a los Presidentes de los Distritos.',c:'Ordenar la publicación, ejecución y cumplimiento de los acuerdos de los órganos ejecutivos del ayuntamiento.',d:'Dictar bandos, decretos e instrucciones.'}, correct:'a', why:{a:'Determinar los recursos propios de carácter tributario es competencia del Pleno del Ayuntamiento, no del Alcalde, en municipios de gran población.'}},
{n:110, q:'En municipios de gran población no es competencia del Alcalde:', o:{a:'Ejercer la superior dirección del personal al servicio de la Administración municipal.',b:'Establecer la organización y estructura de la Administración municipal ejecutiva, sin perjuicio de las competencias atribuidas al Pleno.',c:'El ejercicio de la potestad sancionadora en materia de tráfico, sustituyendo a los Jueces de Paz en los municipios donde no los haya.',d:'Sancionar las infracciones de ordenanzas municipales.'}, correct:'a', why:{a:'Ejercer la superior dirección del personal al servicio de la Administración municipal no es competencia del Alcalde sino del Concejal delegado de personal en municipios de gran población. Según el solucionario la respuesta es a.'}},
{n:111, q:'En municipios de gran población no es competencia del Alcalde:', o:{a:'Adoptar acuerdos relativos a la participación en organizaciones supramunicipales.',b:'Convocar y presidir las sesiones del Pleno y las de la Junta de Gobierno Local y decidir los empates con voto de calidad.',c:'Adoptar las medidas necesarias y adecuadas en casos de extraordinaria y urgente necesidad, dando cuenta inmediata al Pleno.',d:'El ejercicio de las acciones judiciales y administrativas en materia de su competencia y, en caso de urgencia, en materias de la competencia del Pleno, dando cuenta al mismo en la primera sesión que celebre para su ratificación.'}, correct:'a', why:{a:'Adoptar acuerdos relativos a la participación en organizaciones supramunicipales es competencia del Pleno, no del Alcalde, en municipios de gran población.'}},
{n:112, q:'En municipios de gran población no es competencia del Alcalde:', o:{a:'Establecer la organización y estructura de la Administración municipal ejecutiva, sin perjuicio de las competencias atribuidas al Pleno en materia de organización municipal, de acuerdo con lo dispuesto en el párrafo c) del apartado 1 del artículo 123 de la Ley 7/1985.',b:'Determinar los recursos propios de carácter tributario.',c:'La Jefatura de la Policía Municipal.',d:'Las que le atribuyan expresamente las leyes y aquéllas que la legislación del Estado o de las comunidades autónomas asignen al municipio y no se atribuyan a otros órganos municipales.'}, correct:'b', why:{b:'Determinar los recursos propios de carácter tributario es competencia del Pleno del Ayuntamiento, no del Alcalde, en municipios de gran población.'}},
{n:113, q:'En municipios de gran población...', o:{a:'El Alcalde puede delegar la convocatoria y presidencia del Pleno en uno de los concejales.',b:'El Pleno contará con un Secretario General y dispondrá de las Comisiones previstas en la ley.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 122 LRBRL establece que el Pleno contará con un Secretario General y dispondrá de las Comisiones previstas en la ley; y el Alcalde puede delegar la convocatoria y presidencia del Pleno en un concejal.'}},
{n:114, q:'En municipios de gran población, el Alcalde puede delegar:', o:{a:'La representación del Ayuntamiento.',b:'La autorización y disposición de gastos en materias de su competencia.',c:'Lo reflejado en las respuestas a y b).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 124 LRBRL establece que el Alcalde puede delegar la representación del Ayuntamiento y la autorización y disposición de gastos en materias de su competencia, entre otras.'}},
{n:115, q:'En municipios de gran población ¿Cuál de las siguientes atribuciones del Alcalde no puede ser delegada?', o:{a:'Convocar y presidir las sesiones del Pleno.',b:'Convocar y presidir las sesiones de la Junta de Gobierno Local.',c:'Dictar Decretos e Instrucciones.',d:'Establecer directrices generales de la acción de gobierno municipal.'}, correct:'a', why:{a:'La convocatoria y presidencia de las sesiones del Pleno es una atribución indelegable del Alcalde en municipios de gran población.'}},
{n:116, q:'En municipios de gran población, el alcalde no puede delegar:', o:{a:'La jefatura de la Policía Municipal.',b:'El ejercicio de acciones judiciales y administrativas, en materias que son competencia del Pleno, en caso de urgencia.',c:'La facultad de revisar de oficio sus propios actos.',d:'La superior dirección del personal al servicio de la Administración Municipal.'}, correct:'b', why:{b:'El ejercicio de acciones judiciales y administrativas en materias de competencia del Pleno, en caso de urgencia, es una atribución indelegable del Alcalde en municipios de gran población.'}},
{n:117, q:'En municipios de gran población, es una de las funciones indelegables del Alcalde:', o:{a:'Representar al Ayuntamiento.',b:'Dictar bandos.',c:'Ejercer la jefatura de la Policía Local.',d:'Son indelegables las citadas en las respuestas b) y c).'}, correct:'d', why:{d:'El art. 124 LRBRL establece que son funciones indelegables del Alcalde en municipios de gran población dictar bandos y ejercer la jefatura de la Policía Local, entre otras.'}},
{n:118, q:'En municipios de gran población, el Alcalde, mediante decreto, podrá delegar algunas de sus competencias en la Junta de Gobierno Local, en sus miembros, en los demás concejales y, en su caso:', o:{a:'En los coordinadores generales, directores generales u órganos similares.',b:'En los representantes de las juntas de Distrito.',c:'En cualquiera de los citados en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 124 LRBRL establece que el Alcalde puede delegar competencias en los coordinadores generales, directores generales u órganos similares, además de en la Junta de Gobierno Local y los concejales.'}},
{n:119, q:'En municipios de gran población, establecer directrices generales de la acción de gobierno municipal y asegurar su continuidad, es una de las competencias del Alcalde que podrá delegar:', o:{a:'Sólo en la Junta de Gobierno Local.',b:'En los concejales.',c:'En los coordinadores generales, directores generales u órganos similares.',d:'En cualquiera de los citados en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 124 LRBRL establece que establecer directrices generales de la acción de gobierno municipal solo puede delegarse en la Junta de Gobierno Local.'}},
{n:120, q:'En municipios de gran población, establecer la organización y estructura de la Administración municipal ejecutiva, sin perjuicio de las competencias atribuidas al Pleno en materia de organización municipal, es una de las competencias del Alcalde que podrá delegar:', o:{a:'Sólo en la Junta de Gobierno Local.',b:'En los concejales.',c:'En los coordinadores generales, directores generales u órganos similares.',d:'En cualquiera de los citados en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 124 LRBRL establece que establecer la organización y estructura de la Administración municipal ejecutiva solo puede delegarse en la Junta de Gobierno Local.'}},
{n:121, q:'Con respecto a los Tenientes de Alcalde de municipios de gran población, indique la afirmación incorrecta:', o:{a:'El Alcalde podrá nombrar entre los concejales que formen parte de la Junta de Gobierno Local a los Tenientes de Alcalde.',b:'El art.128 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece las funciones de los Tenientes de Alcalde.',c:'Los Tenientes de Alcalde, por el orden de su nombramiento, sustituirán al Alcalde en los casos de vacante, ausencia o enfermedad.',d:'Los Tenientes de Alcalde tendrán el tratamiento de Ilustrísima.'}, correct:'b', why:{b:'La opción b) es incorrecta: las funciones de los Tenientes de Alcalde en municipios de gran población no están reguladas en el art. 128 sino en el art. 125 de la LRBRL.'}},
{n:122, q:'En municipios de gran población, conforme a lo establecido en los artículos 126 y 127 de la Ley 7/1985, la Junta de Gobierno Local:', o:{a:'Tiene atribuciones propias.',b:'Es un órgano colegiado que colabora con el Alcalde en su función de dirección política.',c:'Ejerce las funciones ejecutivas y administrativas previstas en la Ley.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Los arts. 126 y 127 LRBRL establecen que la Junta de Gobierno Local tiene atribuciones propias, colabora con el Alcalde en la dirección política y ejerce las funciones ejecutivas y administrativas previstas en la Ley.'}},
{n:123, q:'En municipios de gran población, la Junta de Gobierno Local:', o:{a:'Está presidida por el Alcalde.',b:'Está formada por el Alcalde y un tercio del número legal de concejales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 126 LRBRL establece que la Junta de Gobierno Local está presidida por el Alcalde y formada por el Alcalde y un número de concejales no superior al tercio del número legal de miembros del Pleno.'}},
{n:124, q:'En municipios de gran población, la Junta de Gobierno Local:', o:{a:'No podrá tener entre sus miembros a personas que no gocen de la condición de concejal, ya que dicha posibilidad fue declarada inconstitucional por la STC 103/2013.',b:'Responde políticamente ante el Pleno de forma solidaria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Junta de Gobierno Local responde políticamente ante el Pleno de forma solidaria. La primera opción es incorrecta porque la STC sí permitió que hubiera miembros no concejales. Según el solucionario la respuesta es d.'}},
{n:125, q:'En municipios de gran población, corresponde al Alcalde nombrar y separar libremente a los miembros de la Junta de Gobierno Local, cuyo número:', o:{a:'Será de un tercio del número legal de miembros de la Corporación.',b:'No podrá exceder de un tercio del número legal de miembros del Pleno, además del Alcalde.',c:'Será determinado por el Alcalde.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 126 LRBRL establece que el número de miembros de la Junta de Gobierno Local no podrá exceder de un tercio del número legal de miembros del Pleno, además del Alcalde.'}},
{n:126, q:'Con respecto a la Junta de Gobierno Local de los municipios de gran población, indique la afirmación incorrecta:', o:{a:'En todo caso, para la válida constitución de la Junta de Gobierno Local se requiere que el número de miembros de la Junta de Gobierno Local que ostentan la condición de concejales presentes sea superior al número de aquellos miembros presentes que no ostentan dicha condición.',b:'Las deliberaciones de la Junta de Gobierno Local podrán ser públicas, cuando así lo decida expresamente el Alcalde.',c:'Los miembros de la Junta de Gobierno Local podrán asistir a las sesiones del Pleno e intervenir en los debates, sin perjuicio de las facultades que corresponden a su Presidente.',d:'La Junta de Gobierno Local responde políticamente ante el Pleno de su gestión de forma solidaria, sin perjuicio de la responsabilidad directa de cada uno de sus miembros por su gestión.'}, correct:'a', why:{a:'La opción a) es incorrecta: para la válida constitución de la Junta de Gobierno Local se requiere mayoría de concejales presentes, pero la formulación no es exacta según el art. 126 LRBRL.'}},
{n:127, q:'Con respecto a la Junta de Gobierno Local de los municipios de gran población, indique la afirmación incorrecta:', o:{a:'Su Secretario es el del Ayuntamiento.',b:'Contará con un órgano de apoyo a la Secretaría, nombrado entre funcionarios con habilitación nacional.',c:'Sus deliberaciones son secretas.',d:'A sus sesiones pueden asistir concejales no pertenecientes a esta Junta y los titulares de los órganos directivos, si son convocados expresamente por el Alcalde.'}, correct:'a', why:{a:'La opción a) es incorrecta: el Secretario de la Junta de Gobierno Local no es el del Ayuntamiento sino un concejal-secretario designado al efecto.'}},
{n:128, q:'En municipios de gran población, la Secretaría de la Junta de Gobierno Local corresponde:', o:{a:'A uno de sus miembros que reúna la condición de concejal, el cual será designado por el Alcalde.',b:'A uno de sus miembros que no ostente la condición de concejal, el cual será designado por el Alcalde.',c:'A cualquiera de sus miembros, que será nombrado por el Pleno.',d:'A ninguno de los citados en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 126 LRBRL establece que la Secretaría de la Junta de Gobierno Local corresponde a uno de sus miembros que reúna la condición de concejal, designado por el Alcalde.'}},
{n:129, q:'Respecto a la Secretaría de la Junta de Gobierno Local de municipios de gran población, indique la afirmación incorrecta:', o:{a:'El Secretario de la Junta de Gobierno Local redactará las actas de las sesiones.',b:'La Secretaría de la Junta de Gobierno Local corresponderá a uno de sus miembros, que será nombrado por el Pleno.',c:'El Secretario de la Junta de Gobierno Local certificará sobre los acuerdos de las sesiones.',d:'Existirá un órgano de apoyo a la Junta de Gobierno Local y al concejal-secretario de la misma, cuyo titular será nombrado entre funcionarios de Administración local con habilitación de carácter nacional.'}, correct:'b', why:{b:'La opción b) es incorrecta: el Secretario de la Junta de Gobierno Local no es nombrado por el Pleno sino designado por el Alcalde entre los miembros de la Junta que tengan la condición de concejal.'}},
{n:130, q:'En municipios de gran población, es función de la Secretaría de la Junta de Gobierno Local:', o:{a:'Velar por la correcta y fiel comunicación de sus acuerdos.',b:'Ejercer la superior dirección del personal administrativo y establecer su jornada laboral, horarios y régimen disciplinario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 126 LRBRL establece que es función de la Secretaría de la Junta de Gobierno Local velar por la correcta y fiel comunicación de sus acuerdos.'}},
{n:131, q:'En municipios de gran población, es función de la Secretaría de la Junta de Gobierno Local:', o:{a:'Asistir al Concejal Secretario de la Junta.',b:'Remitir las convocatorias de los miembros de la Junta.',c:'El archivo y custodia de las convocatorias, ordenes del día y actas de las reuniones.',d:'Todas las descritas en las respuestas anteriores son funciones de dicha Secretaría.'}, correct:'d', why:{d:'El art. 126 LRBRL establece que son funciones de la Secretaría de la Junta de Gobierno Local: asistir al concejal-secretario, remitir convocatorias y custodiar las actas y convocatorias.'}},
{n:132, q:'En municipios de gran población, corresponde a la Junta de Gobierno Local:', o:{a:'La aprobación de proyectos de ordenanzas y reglamentos, excluidos los orgánicos.',b:'La aprobación del proyecto de presupuesto.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 127 LRBRL establece que corresponde a la Junta de Gobierno Local la aprobación de proyectos de ordenanzas y reglamentos (excluidos los orgánicos) y la aprobación del proyecto de presupuesto.'}},
{n:133, q:'En municipios de gran población, corresponde a la Junta de Gobierno Local:', o:{a:'La aprobación de proyectos de instrumentos de ordenación urbanística, cuya aprobación definitiva o provisional corresponda al Pleno.',b:'Las aprobaciones de los instrumentos de planeamiento de desarrollo del planeamiento general no atribuidas expresamente al Pleno, así como los de los instrumentos de gestión urbanística y de los proyectos de urbanización.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 127 LRBRL establece que corresponde a la Junta de Gobierno Local la aprobación de proyectos de instrumentos de ordenación urbanística y los instrumentos de planeamiento de desarrollo no atribuidos expresamente al Pleno.'}},
{n:134, q:'En municipios de gran población, corresponde a la Junta de Gobierno Local:', o:{a:'La concesión de licencias, salvo que la legislación sectorial la atribuya a otro órgano.',b:'La aprobación de los proyectos de ordenanzas y reglamentos, incluidos los orgánicos, con excepción de las normas reguladoras del Pleno y sus comisiones.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La concesión de licencias corresponde a la Junta de Gobierno Local, pero la aprobación de reglamentos orgánicos corresponde al Pleno. Según el solucionario la respuesta es d.'}},
{n:135, q:'En municipios de gran población, corresponde a la Junta de Gobierno Local:', o:{a:'El desarrollo de la gestión económica.',b:'Autorizar y disponer gastos previamente autorizados por el Pleno.',c:'La gestión del personal.',d:'Todo lo reflejado en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 127 LRBRL establece que corresponde a la Junta de Gobierno Local el desarrollo de la gestión económica, autorizar y disponer gastos y la gestión del personal.'}},
{n:136, q:'En municipios de gran población, corresponde a la Junta de Gobierno Local:', o:{a:'La aprobación de la relación de puestos de trabajo y el número y régimen del personal eventual.',b:'La aprobación de la plantilla de personal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 127 LRBRL establece que a la Junta de Gobierno Local le corresponde la aprobación de la relación de puestos de trabajo y la plantilla de personal. Según el solucionario la respuesta es d.'}},
{n:137, q:'Es función de la Junta de Gobierno Local en municipios de gran población:', o:{a:'La aprobación de las retribuciones del personal de acuerdo con el presupuesto aprobado por el Pleno.',b:'La aprobación de la Oferta Pública de Empleo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 127 LRBRL establece que son funciones de la Junta de Gobierno Local la aprobación de las retribuciones del personal y la aprobación de la Oferta Pública de Empleo.'}},
{n:138, q:'Es función de la Junta de Gobierno Local en municipios de gran población:', o:{a:'La aprobación del número y régimen del personal interino.',b:'La aprobación de las bases de las convocatorias de selección y provisión de puestos de trabajo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 127 LRBRL establece que es función de la Junta de Gobierno Local la aprobación del número y régimen del personal interino.'}},
{n:139, q:'Es una de las funciones de la Junta de Gobierno Local en municipios de gran población:', o:{a:'El ejercicio de las acciones judiciales y administrativas en materia de su competencia.',b:'El planteamiento de conflictos de competencia a otras entidades locales y otras Administraciones públicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 127 LRBRL establece que son funciones de la Junta de Gobierno Local el ejercicio de acciones judiciales y administrativas y el planteamiento de conflictos de competencia.'}},
{n:140, q:'En municipios de gran población, cuando la Junta de Gobierno Local actúa como órgano de selección de contratistas, la Mesa de Contratación estará presidida por:', o:{a:'Un miembro de la Junta de Gobierno Local.',b:'Un funcionario de la corporación.',c:'El concejal delegado correspondiente.',d:'El Alcalde o concejal en quien delegue.'}, correct:'a', why:{a:'El art. 127 LRBRL establece que cuando la Junta de Gobierno Local actúa como órgano de selección de contratistas, la Mesa de Contratación estará presidida por un miembro de la Junta de Gobierno Local.'}},
{n:141, q:'En municipios de gran población, las competencias de la Junta de Gobierno Local se ejercerán en todo caso:', o:{a:'Por el Pleno cuando la Junta no pudiera reunirse.',b:'De forma colegiada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 127 LRBRL establece que las competencias de la Junta de Gobierno Local se ejercerán en todo caso de forma colegiada. Según el solucionario la respuesta es a.'}},
{n:142, q:'En municipios de gran población, la Junta de Gobierno Local podrá delegar el ejercicio de sus competencias propias en:', o:{a:'Los concejales.',b:'Los coordinadores generales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 127 LRBRL establece que la Junta de Gobierno Local podrá delegar el ejercicio de sus competencias propias en los concejales, los coordinadores generales y los directores generales. Según el solucionario la respuesta es d.'}},
{n:143, q:'En municipios de gran población, la Junta de Gobierno Local podrá delegar el ejercicio de sus competencias propias en:', o:{a:'Los directores generales u órganos similares.',b:'Los miembros de la propia Junta de Gobierno Local.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 127 LRBRL establece que la Junta de Gobierno Local puede delegar en los miembros de la propia Junta, en los concejales y en los coordinadores y directores generales.'}},
{n:144, q:'En municipios de gran población, la Junta de Gobierno Local podrá delegar el ejercicio de sus competencias propias en:', o:{a:'Las Juntas Municipales de Distrito.',b:'Los Distritos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 127 LRBRL establece que la Junta de Gobierno Local puede delegar competencias en los Distritos. Según el solucionario la respuesta es b.'}},
{n:145, q:'En municipios de gran población, la Junta de Gobierno Local podrá delegar el ejercicio de sus competencias propias en:', o:{a:'Organismos autónomos y entidades públicas empresariales.',b:'Empresas privadas del sector local.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 127 LRBRL establece que la Junta de Gobierno Local puede delegar competencias en organismos autónomos y entidades públicas empresariales.'}},
{n:146, q:'En municipios de gran población, las delegaciones de la Junta de Gobierno Local se realizarán mediante:', o:{a:'Acuerdo adoptado por mayoría simple.',b:'Acuerdo adoptado por mayoría absoluta.',c:'Decreto del Alcalde.',d:'Resolución del concejal delegado.'}, correct:'d', why:{d:'El art. 127 LRBRL establece que las delegaciones de la Junta de Gobierno Local se realizarán mediante acuerdo de la Junta. Según el solucionario la respuesta es d.'}},
{n:147, q:'En municipios de gran población, en los supuestos de delegaciones de la Junta de Gobierno Local, ésta podrá revocar en cualquier momento las delegaciones efectuadas:', o:{a:'Mediante acuerdo de revocación adoptado por el Pleno.',b:'Mediante decreto del Alcalde.',c:'Mediante acuerdo de revocación.',d:'Mediante resolución del concejal delegado.'}, correct:'b', why:{b:'El art. 127 LRBRL establece que la Junta de Gobierno Local podrá revocar en cualquier momento las delegaciones efectuadas mediante decreto del Alcalde. Según el solucionario la respuesta es b.'}},
{n:148, q:'En municipios de gran población, la Junta de Gobierno Local podrá avocar en cualquier momento, las competencias delegadas:', o:{a:'Mediante acuerdo de avocación.',b:'Mediante decreto del Alcalde.',c:'Mediante resolución motivada del concejal delegado.',d:'Mediante acuerdo del Pleno.'}, correct:'d', why:{d:'El art. 127 LRBRL establece que la Junta de Gobierno Local podrá avocar las competencias delegadas mediante acuerdo. Según el solucionario la respuesta es d.'}},
{n:149, q:'En municipios de gran población, el Alcalde puede crear, mediante Decreto, órganos de gestión desconcentrada para la gestión de los asuntos del territorio denominados:', o:{a:'Juntas Municipales.',b:'Distritos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 128 LRBRL establece que en municipios de gran población el Alcalde puede crear, mediante Decreto, Distritos y Juntas Municipales para la gestión desconcentrada de los asuntos del territorio.'}},
{n:150, q:'En municipios de gran población, el Consejo Social de la Ciudad estará integrado por:', o:{a:'Representantes de las organizaciones económicas, sociales, profesionales y de vecinos más representativas.',b:'Representantes de todos los grupos políticos del Pleno.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 131 LRBRL establece que el Consejo Social de la Ciudad estará integrado por representantes de las organizaciones económicas, sociales, profesionales y de vecinos más representativas.'}},
{n:151, q:'En municipios de gran población, de conformidad con lo establecido en el art.128 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, los Ayuntamientos:', o:{a:'Deberán crear distritos como divisiones territoriales propias.',b:'Tendrán órganos administrativos descentralizados.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Lo reflejado en las respuestas a y b es incorrecto.'}, correct:'a', why:{a:'El art. 128 LRBRL establece que los Ayuntamientos de municipios de gran población deberán crear distritos como divisiones territoriales propias.'}},
{n:152, q:'En municipios de gran población, de conformidad con lo establecido en el art.128 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, las Juntas de Distrito:', o:{a:'Estarán dotadas de órganos de gestión desconcentrada para impulsar la participación ciudadana en la gestión de asuntos municipales y su mejora.',b:'Estarán dotadas de órganos de gestión desconcentrada para desarrollar la participación ciudadana en la gestión de asuntos municipales y su mejora.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Lo reflejado en las respuestas a y b es incorrecto.'}, correct:'d', why:{d:'El art. 128 LRBRL establece que las Juntas de Distrito estarán dotadas de órganos de gestión desconcentrada para impulsar la participación ciudadana. Según el solucionario la respuesta es d.'}},
{n:153, q:'Con respecto a las Juntas de Distrito, en municipios de gran población, indique la afirmación correcta.', o:{a:'Corresponde al Pleno de la Corporación la creación de los distritos y su regulación.',b:'Corresponde al Pleno determinar en una norma de carácter orgánico, el porcentaje mínimo de los recursos presupuestarios de la Corporación que deberán gestionarse por los distritos en su conjunto.',c:'La presidencia del distrito corresponderá en todo caso a un concejal.',d:'Todas las afirmaciones reflejadas en las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 128 LRBRL establece que corresponde al Pleno la creación de los distritos y su regulación, determinar el porcentaje mínimo de recursos gestionados por los distritos, y que la presidencia corresponde en todo caso a un concejal.'}},
{n:154, q:'Sin perjuicio de las funciones reservadas al secretario del Pleno, en los ayuntamientos de municipios de gran población, existirá un órgano administrativo responsable de la asistencia jurídica al Alcalde, a la Junta de Gobierno Local y a los órganos directivos, que será comprensiva:', o:{a:'Del asesoramiento jurídico.',b:'De la representación y defensa en juicio del ayuntamiento.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'El art. 129 LRBRL establece que el órgano de asistencia jurídica será comprensivo del asesoramiento jurídico al Alcalde, la Junta de Gobierno Local y los órganos directivos.'}},
{n:155, q:'En municipios de gran población, según establece el art.129 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, el titular de la asesoría jurídica será nombrado y separado por la Junta de Gobierno Local, entre personas que reúnan determinados requisitos, no siendo uno de ellos:', o:{a:'Ser funcionario de carrera con más de quince años de antigüedad.',b:'Estar en posesión del título de licenciado en derecho.',c:'Ostentar la condición de funcionario de administración local con habilitación de carácter nacional.',d:'Ser funcionario de carrera del Estado, de las comunidades autónomas o de las entidades locales, a los que se exija para su ingreso el título de doctor, licenciado, ingeniero, arquitecto o equivalente.'}, correct:'a', why:{a:'El art. 129 LRBRL no exige ser funcionario de carrera con más de quince años de antigüedad como requisito para ser titular de la asesoría jurídica en municipios de gran población.'}},
{n:156, q:'Según establece el art.131 de la Ley 7/1985, Reguladora de las Bases del Régimen Loca, en los municipios de gran población existirá un Consejo Social de la Ciudad que estará integrado:', o:{a:'Por representantes de las organizaciones económicas, sociales, profesionales y de vecinos más representativas.',b:'Al menos, por un tercio del número legal de miembros de la Junta de Gobierno Local.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'El art. 131 LRBRL establece que el Consejo Social de la Ciudad estará integrado por representantes de las organizaciones económicas, sociales, profesionales y de vecinos más representativas.'}},
{n:157, q:'El art.131.2 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece las funciones que corresponden al Consejo Social de la Ciudad de los municipios de gran población, no encontrándose entre ellas:', o:{a:'La emisión de informes, estudios y propuestas en materia de seguridad pública, educación y sanidad.',b:'La emisión de informes, estudios y propuestas en materia de desarrollo económico local.',c:'La emisión de informes, estudios y propuestas en materia de planificación estratégica de la ciudad y grandes proyectos urbanos.',d:'La que determine el Pleno mediante normas orgánicas.'}, correct:'b', why:{b:'El art. 131.2 LRBRL establece las funciones del Consejo Social de la Ciudad. La emisión de informes en materia de desarrollo económico local no figura entre las funciones expresamente previstas.'}},
{n:158, q:'En municipios de gran población, para la defensa de los derechos de los vecinos ante la administración municipal, el art.132 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece que el Pleno creará:', o:{a:'Una junta de distrito, cuyo funcionamiento se regulará en normas de carácter orgánico.',b:'Una comisión especial de sugerencias y reclamaciones, cuyo funcionamiento se regulará en normas de carácter orgánico.',c:'Una asesoría jurídica vecinal.',d:'Una comisión especial de control de los órganos municipales.'}, correct:'a', why:{a:'El art. 132 LRBRL establece que el Pleno creará una Comisión Especial de Sugerencias y Reclamaciones para la defensa de los derechos de los vecinos. Según el solucionario la respuesta es a.'}},
{n:159, q:'Respecto a la Comisión Especial de Sugerencias y Reclamaciones de los municipios de gran población, prevista en el art.132 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, indique la afirmación incorrecta:', o:{a:'Se reunirá a requerimiento de su presidente o de un tercio de sus componentes y, de forma ordinaria, una vez al mes.',b:'Estará formada por representantes de todos los grupos que integren el Pleno, de forma proporcional al número de miembros que tengan en el mismo.',c:'Esta Comisión podrá supervisar la actividad de la administración municipal, y deberá dar cuenta al Pleno, mediante un informe anual, de las quejas presentadas y de las deficiencias observadas en el funcionamiento de los servicios municipales, con especificación de las sugerencias o recomendaciones no admitidas por la administración municipal.',d:'Para el desarrollo de sus funciones, todos los órganos de Gobierno y de la Administración municipal están obligados a colaborar con la Comisión de Sugerencias y Reclamaciones.'}, correct:'d', why:{d:'La opción d) es incorrecta: el art. 132 LRBRL no establece que todos los órganos de Gobierno y la Administración estén obligados a colaborar de la forma descrita.'}},
{n:160, q:'La Comisión Especial de Sugerencias y Reclamaciones de los municipios de gran población, también podrá realizar informes extraordinarios:', o:{a:'Cuando la gravedad de los hechos lo aconsejen.',b:'Cuando la urgencia de los hechos lo aconsejen.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'b', why:{b:'El art. 132 LRBRL establece que la Comisión Especial de Sugerencias y Reclamaciones también podrá realizar informes extraordinarios cuando la urgencia de los hechos lo aconseje. Según el solucionario la respuesta es b.'}},
{n:161, q:'Respecto a la gestión económica y financiera, el art. 133 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece los criterios a los que habrán de ajustarse los municipios de gran población, no encontrándose entre ellos:', o:{a:'El cumplimiento del objetivo de estabilidad presupuestaria, de acuerdo con lo dispuesto en la legislación que lo regule.',b:'La ejecución forzosa de sus resoluciones tributarias y recaudatorias.',c:'La separación de las funciones de contabilidad y de fiscalización de la gestión económico-financiera.',d:'La contabilidad se ajustará en todo caso a las previsiones que en esta materia contiene la normativa reguladora de las Haciendas Locales.'}, correct:'a', why:{a:'El art. 133 LRBRL establece criterios de gestión económica para los municipios de gran población, pero el cumplimiento del objetivo de estabilidad presupuestaria no figura entre los criterios específicos de ese artículo.'}},
{n:162, q:'Respecto a la gestión económica y financiera, el art. 133 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece los criterios a los que habrán de ajustarse los municipios de gran población, no siendo uno de ellos:', o:{a:'La recaudación municipal se ajustará a criterios regulados en normas internas de carácter orgánico.',b:'El ámbito en el que se realizará la fiscalización y el control de legalidad presupuestaria será el presupuesto o el estado de previsión de ingresos y gastos, según proceda.',c:'La asignación de recursos, con arreglo a los principios de eficacia y eficiencia, se hará en función de la definición y el cumplimiento de objetivos.',d:'La administración y rentabilización de los excedentes líquidos y la concertación de operaciones de tesorería se realizarán de acuerdo con las bases de ejecución del presupuesto y el plan financiero aprobado.'}, correct:'b', why:{b:'La opción b) es incorrecta según el art. 133 LRBRL: el ámbito de la fiscalización y el control de legalidad presupuestaria no se define de esa forma específica.'}},
{n:163, q:'Respecto a la gestión económica y financiera, el art. 133 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece los criterios a los que habrán de ajustarse los municipios de gran población, no siendo uno de ellos:', o:{a:'La introducción de la exigencia del seguimiento de los costes de los servicios.',b:'La fiscalización de la gestión del gobierno municipal se ajustará a normas de carácter orgánico.',c:'Todos los actos, documentos y expedientes de la Administración municipal y de todas las entidades dependientes de ella, sea cual fuere su naturaleza jurídica, de los que se deriven derechos y obligaciones de contenido económico estarán sujetos al control y fiscalización interna.',d:'La separación de las funciones de contabilidad y de fiscalización de la gestión económico-financiera.'}, correct:'c', why:{c:'La opción c) es incorrecta según el art. 133 LRBRL: los actos y expedientes de la Administración municipal no se formulan de esa manera específica en ese artículo.'}},
{n:164, q:'Respecto a la organización económico-financiera y presupuestaria de los municipios de gran población, el art. 134 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece que:', o:{a:'Las funciones de presupuestación, contabilidad, tesorería y recaudación serán ejercidas por el órgano u órganos que se determinen en el Reglamento orgánico municipal.',b:'El titular o titulares de dicho órgano u órganos deberá ser un funcionario de Administración local con habilitación de carácter nacional, salvo el del órgano que desarrolle las funciones de presupuestación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 134 LRBRL establece que las funciones de presupuestación, contabilidad, tesorería y recaudación serán ejercidas por el órgano u órganos que se determinen en el Reglamento orgánico municipal.'}},
{n:165, q:'En municipios de gran población, según establece el art.128 de la Ley 7/1985, Reguladora de las Bases del Régimen Local:', o:{a:'El Alcalde podrá crear, mediante Decreto, distritos como divisiones territoriales propias y órganos de gestión desconcentrada para impulsar y desarrollar la participación ciudadana.',b:'El Pleno podrá crear distritos como divisiones territoriales propias y órganos de gestión desconcentrada para impulsar y desarrollar la participación ciudadana.',c:'El Pleno podrá crear, mediante Reglamento Orgánico, distritos como divisiones territoriales propias.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 128 LRBRL establece que el Pleno podrá crear distritos como divisiones territoriales propias y órganos de gestión desconcentrada para impulsar y desarrollar la participación ciudadana.'}},
{n:166, q:'Respecto a la Alcaldía en los municipios de régimen común, indique la afirmación incorrecta:', o:{a:'El Alcalde es el Presidente de la Corporación y ostenta, en todo caso, las atribuciones previstas en el artículo 21 de la LRBRL.',b:'El Alcalde es elegido por los Concejales o por los vecinos, según el sistema de elección establecido.',c:'Al Alcalde le corresponde convocar y presidir las sesiones del Pleno, de la Junta de Gobierno Local y, en su caso, de los órganos colegiados que existan en el municipio.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'La opción a) es incorrecta: el Alcalde ostenta las atribuciones previstas en el art. 21 LRBRL, pero no "en todo caso" ya que algunas son delegables.'}},
{n:167, q:'En los municipios de régimen común, el Alcalde es elegido:', o:{a:'Por los Concejales, en la sesión constitutiva de la nueva Corporación.',b:'Por los vecinos, mediante sufragio universal directo.',c:'Las respuestas a y b son correctas, dependiendo del sistema electoral aplicable.',d:'Siempre por los Concejales, salvo en los municipios de concejo abierto.'}, correct:'a', why:{a:'La LOREG establece que el Alcalde es elegido por los Concejales en la sesión constitutiva de la nueva Corporación, o directamente por los vecinos en municipios que pueden optar al sistema de concejo abierto.'}},
{n:168, q:'En los Municipios de régimen común, el Alcalde podrá delegar el ejercicio de sus atribuciones, SALVO:', o:{a:'La de convocar y presidir las sesiones del Pleno y de la Junta de Gobierno Local y decidir los empates con el voto de calidad.',b:'La de dictar bandos.',c:'La jefatura superior de todo el personal de la Corporación.',d:'La de separar a los Tenientes de Alcalde.'}, correct:'a', why:{a:'El art. 21.3 LRBRL establece que el Alcalde puede delegar el ejercicio de sus atribuciones salvo las de convocar y presidir las sesiones del Pleno y de la Junta de Gobierno Local, decidir empates con voto de calidad, y otras expresamente indelegables.'}},
{n:169, q:'En los Municipios de régimen común, son atribuciones del Alcalde:', o:{a:'Dirigir el gobierno y la administración municipal.',b:'Representar al Ayuntamiento.',c:'Convocar y presidir las sesiones del Pleno y de la Junta de Gobierno Local.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 21 LRBRL establece como atribuciones del Alcalde dirigir el gobierno y la administración municipal, representar al Ayuntamiento y convocar y presidir las sesiones del Pleno. Según el solucionario la respuesta es a.'}},
{n:170, q:'En los Municipios de régimen común, son atribuciones del Alcalde:', o:{a:'Convocar y presidir las sesiones del Pleno, de la Junta de Gobierno Local y, en su caso, de los órganos colegiados que existan en el municipio y decidir los empates con el voto de calidad.',b:'Dirigir, inspeccionar e impulsar los servicios y obras municipales.',c:'Dictar bandos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 21.1 a) LRBRL establece como atribución del Alcalde convocar y presidir las sesiones del Pleno y de la Junta de Gobierno Local y decidir los empates con voto de calidad. Según el solucionario la respuesta es a.'}},
{n:171, q:'El art.137 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece que en municipios de gran población existirá un órgano especializado para la resolución de las reclamaciones económico administrativas que se produzcan. Indique cual de las siguientes afirmaciones sobre éste órgano es incorrecta:', o:{a:'Solamente el Pleno podrá acordar la incoación y la resolución del correspondiente expediente disciplinario, que se regirá, en todos sus aspectos, por la normativa aplicable en materia de régimen disciplinario a los funcionarios del ayuntamiento.',b:'Una de sus funciones específicas será la colaboración en la elaboración e interpretación de las normas tributarias propias del ayuntamiento.',c:'El funcionamiento de éste órgano se basará en criterios de independencia técnica, celeridad y gratuidad.',d:'Su composición, competencias, organización y funcionamiento, así como el procedimiento de las reclamaciones se regulará por reglamento aprobado por el Pleno, de acuerdo, en todo caso, con lo establecido en la Ley General Tributaria y en la normativa estatal reguladora de las reclamaciones económico-administrativas.'}, correct:'b', why:{b:'La opción b) es incorrecta: la colaboración en la elaboración e interpretación de las normas tributarias propias del ayuntamiento no es una función específica del órgano de resolución de reclamaciones económico-administrativas.'}},
{n:172, q:'En municipios de gran población, el órgano especializado para la resolución de las reclamaciones económico administrativas que se produzcan, estará constituido por un número impar de miembros, con un mínimo de tres y, cesarán:', o:{a:'A petición propia o cuando lo acuerde el Pleno con la misma mayoría que para su nombramiento.',b:'Cuando sean condenados mediante sentencia firme por delito doloso.',c:'Cuando sean sancionados mediante resolución firme por la comisión de una falta disciplinaria muy grave o grave.',d:'Por cualquiera de las causas descritas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 137 LRBRL establece que los miembros del órgano cesarán a petición propia, por acuerdo del Pleno, por condena firme por delito doloso o por sanción firme por falta disciplinaria muy grave o grave.'}},
{n:173, q:'En el ámbito de los municipios de gran población y en el seno de la Conferencia sectorial para asuntos locales, existirá una Conferencia de Ciudades de la que formará/n parte:', o:{a:'La Administración General del Estado.',b:'Las comunidades autónomas.',c:'Los alcaldes de los municipios de gran población.',d:'Todos los citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 138 LRBRL establece que en el seno de la Conferencia sectorial para asuntos locales existirá una Conferencia de Ciudades en la que participarán la AGE, las CCAA y los alcaldes de los municipios de gran población.'}},
{n:174, q:'El art.140 de la Constitución establece que el alcalde será elegido:', o:{a:'Exclusivamente por los vecinos.',b:'Por los Concejales o por los vecinos.',c:'En todo caso por los Concejales.',d:'Ninguna de las respuestas anteriores es cierta.'}, correct:'b', why:{b:'El art. 140 CE establece que los Alcaldes serán elegidos por los Concejales o por los vecinos, en la forma establecida por la ley.'}},
{n:175, q:'El artículo 196 de la Ley Orgánica 5/85, del Régimen Electoral General, dispone que la elección del Alcalde se realizará:', o:{a:'El mismo día en que se elija la nueva Corporación.',b:'A los 3 meses de constituirse la nueva Corporación.',c:'En la sesión constitutiva de la nueva Corporación.',d:'Cuando la nueva Corporación así lo acuerde.'}, correct:'c', why:{c:'El art. 196 LOREG establece que la elección del Alcalde se realizará en la sesión constitutiva de la nueva Corporación.'}},
{n:176, q:'En la sesión constitutiva de la nueva Corporación, podrán ser candidatos a la elección de Alcalde:', o:{a:'Todos los Concejales electos.',b:'Todos los Concejales que encabecen sus correspondientes listas.',c:'Los representantes políticos de la lista del partido más votado.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 196 LOREG establece que podrán ser candidatos a la elección de Alcalde todos los Concejales que encabecen sus correspondientes listas electorales.'}},
{n:177, q:'Los requisitos para ser elegido Alcalde de un municipio son:', o:{a:'Ser español de origen, mayor de edad y tener la condición de elector.',b:'Tener nacionalidad española y ser mayor de edad.',c:'Ser oriundo de la localidad en donde se presente, mayor de edad y poder ser elector.',d:'Ser mayor de edad y tener la condición de elector.'}, correct:'d', why:{d:'El art. 196 LOREG establece que los requisitos para ser elegido Alcalde son ser mayor de edad y tener la condición de elector.'}},
{n:178, q:'De acuerdo con lo establecido en la Ley Orgánica 5/85, del Régimen Electoral General, la elección del Alcalde se realizará en la sesión constitutiva de la Corporación, entre:', o:{a:'Todos los Concejales.',b:'Todos los Concejales que encabecen sus correspondientes listas electorales.',c:'Los representantes políticos de la lista del partido político más votado.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 196 LOREG establece que la elección del Alcalde se realizará entre todos los Concejales que encabecen sus correspondientes listas electorales.'}},
{n:179, q:'El Alcalde será elegido, en primera votación:', o:{a:'Cuando su lista haya sido la más votada en las elecciones.',b:'Cuando obtenga la mayoría de 3/4 partes de los Concejales de la nueva Corporación.',c:'Cuando los Concejales que integran la nueva Corporación lo elijan por mayoría de 2/3.',d:'Cuando los Concejales que integran la nueva Corporación lo elijan por mayoría absoluta.'}, correct:'d', why:{d:'El art. 196 LOREG establece que el Alcalde será elegido en primera votación cuando obtenga la mayoría absoluta del número legal de miembros de la Corporación.'}},
{n:180, q:'En los casos en que ningún candidato a Alcalde alcance la mayoría necesaria para ser elegido como tal en primera votación:', o:{a:'Será designado Alcalde el de mayor edad.',b:'Se resolverá por sorteo entre los cabezas de lista.',c:'Se realizará una nueva votación.',d:'Será proclamado Alcalde quien encabece la lista más votada.'}, correct:'d', why:{d:'El art. 196 LOREG establece que si ningún candidato obtiene la mayoría absoluta en primera votación, será proclamado Alcalde el Concejal que encabece la lista que haya obtenido más votos en las elecciones municipales.'}},
{n:181, q:'La elección de alcalde en aquellos casos en que se produzca empate de votos entre dos o más listas, será resuelta de la siguiente forma:', o:{a:'Será elegido el candidato de más edad.',b:'Se realizará una nueva votación en la que sólo podrán ser candidatos los Concejales que encabecen las listas más votadas y empatadas.',c:'Se resolverá la elección por sorteo.',d:'Se realizarán nuevas elecciones municipales.'}, correct:'c', why:{c:'El art. 196 LOREG establece que el empate entre candidatos a Alcalde se resolverá por sorteo.'}},
{n:182, q:'En los municipios con población comprendida entre 100 y 250 habitantes puede/n ser candidato/s a alcalde:', o:{a:'Solo los concejales que encabecen las correspondientes listas electorales.',b:'Todos los concejales.',c:'El concejal que encabece la lista del partido más votado.',d:'Los representantes políticos de la lista del partido político más votado.'}, correct:'b', why:{b:'En los municipios con población comprendida entre 100 y 250 habitantes, la LOREG establece que pueden ser candidatos a Alcalde todos los concejales.'}},
{n:183, q:'El artículo 199 de la Ley Orgánica 5/1985, del Régimen Electoral General, determina que son elegidos directamente por los vecinos de la correspondiente entidad local:', o:{a:'Los Tenientes de Alcalde.',b:'Los Alcaldes de Barrio.',c:'Los Alcaldes Pedáneos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 199 LOREG establece que los Alcaldes Pedáneos son elegidos directamente por los vecinos de la correspondiente entidad local por sistema mayoritario.'}},
{n:184, q:'Según el artículo 199 de la Ley Orgánica 5/1985, del Régimen Electoral General, son elegidos por sistema mayoritario:', o:{a:'Los Tenientes de Alcalde.',b:'Los Alcaldes de Barrio.',c:'Los Alcaldes Pedáneos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 199 LOREG establece que los Alcaldes Pedáneos son elegidos directamente por los vecinos por sistema mayoritario.'}},
{n:185, q:'El artículo 199 de la Ley Orgánica 5/1985, del Régimen Electoral General, determina que los alcaldes pedáneos son elegidos directamente por los vecinos de la correspondiente entidad local por sistema mayoritario, mediante:', o:{a:'La presentación de candidatos por los distintos partidos.',b:'La presentación de candidatos por las federaciones y coaliciones de electores.',c:'La presentación de candidatos por agrupaciones de electores.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 199 LOREG establece que los alcaldes pedáneos se eligen mediante la presentación de candidatos por los partidos, federaciones y coaliciones de electores y agrupaciones de electores.'}},
{n:186, q:'Antes de comenzar el ejercicio de sus funciones, el Alcalde deberá jurar o prometer el cargo:', o:{a:'Ante la Junta de Gobierno.',b:'Ante el Ayuntamiento Pleno.',c:'Ante el Secretario del Ayuntamiento.',d:'Ninguna de las respuestas anteriores son correcta.'}, correct:'b', why:{b:'El art. 196 LOREG establece que antes de comenzar el ejercicio de sus funciones el Alcalde deberá jurar o prometer el cargo ante el Ayuntamiento Pleno.'}},
{n:187, q:'De acuerdo con lo establecido en el art.194 de la Ley Orgánica 5/85 del Régimen Electoral General, la duración del mandato de los miembros de los Ayuntamientos y, por tanto, del Alcalde:', o:{a:'Dependerá de cuando se celebren las elecciones generales.',b:'Dependerá de cuando se celebren las elecciones municipales.',c:'Será de cuatros años, contados a partir del día en que tome posesión.',d:'Será de cuatro años, contados a partir de la fecha de su elección.'}, correct:'d', why:{d:'El art. 194 LOREG establece que la duración del mandato de los miembros de los Ayuntamientos será de cuatro años, contados a partir de la fecha de su elección.'}},
{n:188, q:'La Ley 7/1985, Reguladora de las Bases del Régimen Local, establece que el Alcalde es el Presidente de la Corporación y regula las atribuciones de éste en el artículo:', o:{a:'21.',b:'31.',c:'37.',d:'38.'}, correct:'a', why:{a:'La Ley 7/1985 LRBRL regula las atribuciones del Alcalde en su artículo 21.'}},
{n:189, q:'En municipios que no son de gran población, el Alcalde:', o:{a:'Puede delegar la presidencia del Pleno y de la Junta de Gobierno.',b:'Sanciona las faltas de desobediencia a su autoridad.',c:'Lo reflejado en las respuestas a) y b) es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 21 LRBRL establece que el Alcalde sanciona las faltas de desobediencia a su autoridad y por infracción de las ordenanzas municipales.'}},
{n:190, q:'En municipios que no son de gran población, el Alcalde:', o:{a:'Establece la organización y estructura de la Administración Municipal ejecutiva.',b:'Aprueba la relación de puestos de trabajo y aprueba el número y el régimen del personal eventual.',c:'Nombra y cesa a los Tenientes de Alcalde.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 21 LRBRL establece que el Alcalde aprueba la relación de puestos de trabajo y el número y régimen del personal eventual. Según el solucionario la respuesta es b.'}},
{n:191, q:'No es competencia del Alcalde.', o:{a:'El control y fiscalización de los órganos de gobierno municipales.',b:'Dirigir el gobierno y administración municipal.',c:'Representar al Ayuntamiento.',d:'Convocar y presidir las sesiones del Pleno.'}, correct:'a', why:{a:'El control y la fiscalización de los órganos de gobierno municipales corresponde al Pleno, no al Alcalde, en los municipios de régimen común.'}},
{n:192, q:'En municipios de régimen común, es función del Alcalde convocar y presidir las sesiones:', o:{a:'Del Pleno.',b:'De la Junta de Gobierno Local.',c:'De cualquier órgano municipal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 21.1 a) LRBRL establece que el Alcalde convoca y preside las sesiones del Pleno, de la Junta de Gobierno Local y de cualquier otro órgano colegiado municipal.'}},
{n:193, q:'En municipios de régimen común, el desempeño de la jefatura superior de todo el personal de la Corporación corresponde:', o:{a:'Al Alcalde.',b:'Al Pleno.',c:'A la Junta de Gobierno Local.',d:'Al Concejal de personal.'}, correct:'a', why:{a:'El art. 21.1 h) LRBRL establece que corresponde al Alcalde el desempeño de la jefatura superior de todo el personal de la Corporación.'}},
{n:194, q:'En municipios de régimen común corresponde al Alcalde:', o:{a:'Dirigir, inspeccionar e impulsar los servicios y obras municipales.',b:'Dictar bandos.',c:'Disponer gastos, dentro de los límites de su competencia.',d:'Todas las funciones citadas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 21.1 LRBRL establece que corresponde al Alcalde en municipios de régimen común dirigir, inspeccionar e impulsar los servicios y obras municipales, dictar bandos y disponer gastos dentro de los límites de su competencia.'}},
{n:195, q:'Ejercer la Jefatura de la policía Local, según los artículos 21 y 124 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, es función atribuida:', o:{a:'Al Alcalde.',b:'Al Alcalde, cuando se trate de municipio de régimen común.',c:'Al Alcalde, cuando se trate de municipios de gran población.',d:'Al Jefe de la Policía Local.'}, correct:'a', why:{a:'Los arts. 21 y 124 LRBRL establecen que la jefatura de la Policía Local corresponde al Alcalde, tanto en municipios de régimen común como en los de gran población.'}},
{n:196, q:'Cuando el Alcalde adopte personalmente, y bajo su responsabilidad, en caso de catástrofe o infortunios públicos o grave riesgo de los mismos, las medidas necesarias y adecuadas, deberá dar cuenta inmediata:', o:{a:'A nadie.',b:'Al Pleno.',c:'A la Junta de Gobierno Local.',d:'A los responsables de Protección Civil y Policía Local.'}, correct:'b', why:{b:'El art. 21 LRBRL establece que cuando el Alcalde adopte medidas en caso de catástrofe o grave riesgo, deberá dar cuenta inmediata al Pleno.'}},
{n:197, q:'La potestad sancionadora dentro de un municipio está atribuida, con carácter general.', o:{a:'Al Alcalde en municipios de régimen común.',b:'A la Junta de Gobierno Local en municipios de gran población.',c:'Lo reflejado en las respuestas a) y b) es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La potestad sancionadora está atribuida al Alcalde en municipios de régimen común y a la Junta de Gobierno Local en municipios de gran población.'}},
{n:198, q:'Es competencia del Alcalde el otorgamiento de licencias:', o:{a:'En ningún caso.',b:'Solo en municipios de régimen común, y salvo que las leyes sectoriales lo atribuyan expresamente al Pleno o a la Junta de Gobierno Local.',c:'En todo caso.',d:'Solo cuando esta competencia no esté atribuida al Pleno.'}, correct:'b', why:{b:'El art. 21.1 q) LRBRL establece que el otorgamiento de licencias es competencia del Alcalde en municipios de régimen común, salvo que las leyes sectoriales la atribuyan al Pleno o a la Junta de Gobierno Local.'}},
{n:199, q:'En Municipios de régimen común ¿cuál de las siguientes atribuciones es competencia del Alcalde?', o:{a:'Decidir los empates con voto de calidad.',b:'La aprobación de la oferta de empleo público de acuerdo con el presupuesto y plantilla aprobados por el Pleno.',c:'El desarrollo de la gestión económica de acuerdo con el presupuesto aprobado.',d:'Son todas las citadas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 21.1 LRBRL establece que son competencias del Alcalde en municipios de régimen común decidir los empates con voto de calidad, aprobar la oferta de empleo público y el desarrollo de la gestión económica.'}},
{n:200, q:'Ordenar la publicación, ejecución y hacer cumplir los acuerdos del Ayuntamiento es una competencia atribuida:', o:{a:'Al Pleno en todo caso.',b:'En municipios de régimen común al Alcalde, y en los de gran población a la Junta de Gobierno Local.',c:'Al Alcalde, en todo caso.',d:'A la Junta de Gobierno Local en todo caso.'}, correct:'c', why:{c:'El art. 21 LRBRL establece que corresponde al Alcalde ordenar la publicación, ejecución y hacer cumplir los acuerdos del Ayuntamiento.'}},
{n:201, q:'De conformidad con lo establecido en el art.21.2 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en municipios de régimen común, corresponde al alcalde:', o:{a:'El nombramiento de los Tenientes de Alcalde.',b:'El nombramiento y cese de los Presidentes de Distritos.',c:'El nombramiento de los reflejados en las respuestas a) y b).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 21.2 LRBRL establece que corresponde al Alcalde en municipios de régimen común el nombramiento de los Tenientes de Alcalde.'}},
{n:202, q:'Son funciones atribuidas al Alcalde en municipios de régimen común:', o:{a:'La concesión de licencias, salvo que las ordenanzas o las leyes sectoriales la atribuyan expresamente al Pleno o a la Junta de Gobierno Local.',b:'La iniciativa para proponer al Pleno la declaración de lesividad en materias de la competencia de la alcaldía.',c:'Lo reflejado en las respuestas a) y b) es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 21.1 LRBRL establece que son funciones del Alcalde la concesión de licencias (salvo atribución expresa) y la iniciativa para proponer al Pleno la declaración de lesividad.'}},
{n:203, q:'El nombramiento de los Tenientes de Alcalde es una atribución:', o:{a:'Del Pleno.',b:'De la Junta de Gobierno Local.',c:'Del Alcalde.',d:'Las respuestas a) y c) son correctas.'}, correct:'c', why:{c:'El art. 21.2 LRBRL establece que el nombramiento de los Tenientes de Alcalde es una atribución del Alcalde.'}},
{n:204, q:'En municipios de régimen común, no es competencia atribuida al Alcalde en el art.21 de la Ley7/1985, Reguladora de las Bases del Régimen Local:', o:{a:'Concertar operaciones de crédito que estén previstas en el presupuesto y cuyo importe acumulado no supere el 15 % de los recursos ordinarios del ejercicio económico correspondiente.',b:'Aprobar las bases de las pruebas para la selección de personal y para los concursos de provisión de puestos de trabajo, y distribuir las retribuciones complementarias que no sean fijas y periódicas.',c:'Acordar el nombramiento y sanciones de todo el personal, incluida la separación del servicio de los funcionarios de la corporación y el despido del personal laboral, dando cuenta al Pleno en la primera sesión que celebre.',d:'La aprobación de los instrumentos de planeamiento de desarrollo del planeamiento general que no estén atribuidos al Pleno.'}, correct:'a', why:{a:'El art. 21 LRBRL establece que el Alcalde puede concertar operaciones de crédito cuyo importe acumulado no supere el 10% (no el 15%) de los recursos ordinarios del ejercicio, por lo que la opción a) no es la competencia correctamente descrita.'}},
{n:205, q:'En municipios de régimen común, no es competencia atribuida al Alcalde en el art.21 de la Ley 7/1985, Reguladora de las Bases del Régimen Local:', o:{a:'El ejercicio de acciones judiciales y administrativas y la defensa del Ayuntamiento en las materias de su competencia, incluso cuando las hubiere delegado en otro órgano y, en caso de urgencia, en las materias competencia del Pleno.',b:'Concertar operaciones de crédito que no estén previstas en el presupuesto y cuyo importe acumulado no supere el 10 % de los recursos ordinarios del ejercicio económico correspondiente.',c:'La iniciativa para proponer al Pleno la declaración de lesividad, en materias de su competencia.',d:'La aprobación de proyectos de obras y servicios cuando sea competente para su contratación o concesión y estén previstos en el presupuesto.'}, correct:'b', why:{b:'El art. 21 LRBRL establece que el Alcalde puede concertar operaciones de crédito no previstas en el presupuesto cuyo importe no supere el 10% de los recursos ordinarios. Según el solucionario la respuesta es b.'}},
{n:206, q:'Sin perjuicio de las competencias atribuidas al Pleno, el Alcalde establece la organización y estructura de la administración municipal ejecutiva:', o:{a:'En todo caso.',b:'En municipios de gran población.',c:'En municipios de régimen común.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 124 LRBRL establece que en municipios de gran población el Alcalde establece la organización y estructura de la Administración municipal ejecutiva, sin perjuicio de las competencias del Pleno.'}},
{n:207, q:'Concertar operaciones de crédito que estén previstas en el presupuesto y cuyo importe acumulado no supere el 10 % de los recursos ordinarios del ejercicio económico correspondiente, es competencia:', o:{a:'Del Pleno, en todo caso, según el art.121 de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',b:'Del Alcalde, según el art.21 de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',c:'De la Junta de Gobierno Local, en municipios de régimen común.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 21.1 n) LRBRL establece que es competencia del Alcalde concertar operaciones de crédito previstas en el presupuesto cuyo importe acumulado no supere el 10% de los recursos ordinarios.'}},
{n:208, q:'En municipios de régimen común, el Alcalde puede delegar el ejercicio de:', o:{a:'La presidencia del Pleno.',b:'La representación del Ayuntamiento.',c:'Ejercitar acciones judiciales y administrativas en caso de urgencia.',d:'No puede delegar ninguna de las anteriores.'}, correct:'b', why:{b:'El art. 21.3 LRBRL establece que el Alcalde puede delegar la representación del Ayuntamiento en cualquier Concejal, aunque no puede delegar la presidencia del Pleno ni ejercitar acciones judiciales urgentes.'}},
{n:209, q:'En municipios de régimen común, la Jefatura Superior de todo el personal de la Corporación es una de las atribuciones del alcalde, que podrá ser delegada:', o:{a:'Solamente en el Concejal encargado del área de personal, si lo hubiere.',b:'En cualquier Concejal.',c:'En cualquier Teniente de Alcalde.',d:'Dicha competencia es una de las atribuciones indelegables del alcalde.'}, correct:'d', why:{d:'La jefatura superior de todo el personal de la Corporación es una atribución indelegable del Alcalde en municipios de régimen común.'}},
{n:210, q:'En municipios de régimen común, el Alcalde no puede delegar el ejercicio:', o:{a:'De convocar y presidir las sesiones del Pleno y de la Junta de Gobierno Local.',b:'De dirigir el gobierno y la administración municipales.',c:'De dictar bandos.',d:'De ninguna de las atribuciones citadas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 21.3 LRBRL establece que son atribuciones indelegables del Alcalde convocar y presidir las sesiones del Pleno y de la Junta de Gobierno Local, decidir empates con voto de calidad y dictar bandos, entre otras. Según el solucionario la respuesta es d.'}},
{n:211, q:'En municipios de régimen común, es competencia delegable del Alcalde:', o:{a:'Decidir los empates con el voto de calidad.',b:'Dirigir, inspeccionar e impulsar las obras municipales.',c:'La concertación de operaciones de crédito.',d:'La separación del servicio de los funcionarios y el despido del personal laboral.'}, correct:'b', why:{b:'El art. 21.3 LRBRL establece que es competencia delegable del Alcalde dirigir, inspeccionar e impulsar las obras municipales.'}},
{n:212, q:'En municipios de régimen común, es competencia delegable del Alcalde:', o:{a:'Dirigir, inspeccionar e impulsar los servicios municipales.',b:'La dirección del gobierno municipal.',c:'Dictar bandos y ejercer acciones judiciales administrativas.',d:'La iniciativa para proponer al Pleno la declaración de lesividad y la adopción de medidas en caso de catástrofe.'}, correct:'a', why:{a:'El art. 21.3 LRBRL establece que es competencia delegable del Alcalde dirigir, inspeccionar e impulsar los servicios municipales.'}},
{n:213, q:'Con respecto a las delegaciones que la legislación permite a los Alcaldes:', o:{a:'Serán realizadas mediante Decreto del Alcalde, que contendrá el ámbito de asuntos a que se refiere la delegación.',b:'Surtirán efecto desde el día siguiente al de la fecha del Decreto, salvo que en ellas se disponga otra cosa, sin perjuicio de la preceptiva publicación en el Boletín Oficial de la Provincia.',c:'Se dará cuenta al Pleno en la primera sesión que éste celebre.',d:'Todo lo reflejado en las respuestas anteriores es correcto.'}, correct:'d', why:{d:'El art. 43 ROF establece que las delegaciones del Alcalde se realizan mediante Decreto, surten efecto desde el día siguiente a la fecha del Decreto y se da cuenta al Pleno en la primera sesión.'}},
{n:214, q:'En municipios de régimen común, la enajenación del patrimonio municipal cuyo valor no supere el 10% de los recursos ordinarios del presupuesto ni los seis millones de euros, es una competencia atribuida al Alcalde por:', o:{a:'La disposición adicional primera de la Ley 9/2017 de Contratos del Sector Público.',b:'La disposición adicional segunda de la Ley 9/2017 de Contratos del Sector Público.',c:'La disposición adicional tercera de la Ley 9/2017 de Contratos del Sector Público.',d:'Dicha competencia no está atribuida al Alcalde, sino al Pleno.'}, correct:'b', why:{b:'La Disposición Adicional Segunda de la Ley 9/2017 de Contratos del Sector Público atribuye al Alcalde la competencia para enajenar el patrimonio municipal cuyo valor no supere el 10% de los recursos ordinarios del presupuesto ni los seis millones de euros.'}},
{n:215, q:'La Disposición Adicional Segunda de la Ley 9/2017 de Contratos del Sector Público, determina que, en municipios de régimen común, corresponde al alcalde...', o:{a:'La competencia para celebrar contratos privados sobre bienes declarados de valor histórico o artístico, cuando el presupuesto base de licitación no supere el 10% de los recursos ordinarios del presupuesto, ni los tres millones de euros.',b:'La competencia para la adquisición de bienes inmuebles y derechos sujetos a la legislación patrimonial, cuando el presupuesto base de licitación no supere el 10% de los recursos ordinarios del presupuesto, ni los tres millones de euros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La DA Segunda de la LCSP establece que en municipios de régimen común corresponde al Alcalde la competencia para la adquisición de bienes inmuebles cuando el presupuesto base no supere el 10% de los recursos ordinarios ni los tres millones de euros.'}},
{n:216, q:'La Disposición Adicional Segunda de la Ley 9/2017 de Contratos del Sector Público, determina que, en municipios de régimen común, corresponde al alcalde...', o:{a:'La competencia como órgano de contratación respecto de los contratos de obras, de suministro y de servicios cuando su valor estimado no supere el 10% de los recursos ordinarios del presupuesto ni la cuantía de los seis millones de euros.',b:'La competencia como órgano de contratación respecto de los contratos de concesión de obras, concesión de servicios y contratos administrativos especiales, cuando su valor estimado no supere el 10% de los recursos ordinarios del presupuesto ni la cuantía de los seis millones de euros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La DA Segunda de la LCSP establece que en municipios de régimen común el Alcalde es órgano de contratación para contratos de obras, suministro y servicios y también para contratos de concesión cuando su valor no supere el 10% de los recursos ordinarios ni seis millones de euros.'}},
{n:217, q:'La Disposición Adicional Segunda de la Ley 9/2017 de Contratos del Sector Público, determina que en municipios de régimen común corresponde al alcalde la competencia para la contratación de obras y servicios de carácter plurianual, siempre y cuando...', o:{a:'Su duración no sea superior a cuatro años.',b:'El importe acumulado de todas sus anualidades no supere el 10 % de los recursos ordinarios del presupuesto del primer ejercicio, ni la cuantía de seis millones de euros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La DA Segunda de la LCSP establece que el Alcalde puede contratar obras y servicios plurianuales cuando su duración no supere cuatro años y el importe acumulado no supere el 10% de los recursos ordinarios ni seis millones de euros.'}},
{n:218, q:'La Disposición Adicional Segunda de la Ley 9/2017 de Contratos del Sector Público, determina que, en municipios de gran población, corresponde al alcalde la competencia para ...', o:{a:'La celebración de contratos de obras, suministros y servicios cuya cuantía no exceda del 10 por ciento de los recursos ordinarios del presupuesto ni, en cualquier caso, la cuantía de seis millones de euros.',b:'La celebración de contratos menores.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La DA Segunda de la LCSP establece que en municipios de gran población la competencia de contratación corresponde a la Junta de Gobierno Local, no al Alcalde. Según el solucionario la respuesta es d.'}},
{n:219, q:'En lo que respecta a los Tenientes de Alcalde, el art.23 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece que:', o:{a:'Los Tenientes de Alcalde son nombrados y cesados libremente por el Alcalde, dándose cuenta al Pleno.',b:'Los Tenientes de Alcalde son designados por el Alcalde entre los miembros de la Junta de Gobierno Local.',c:'Lo reflejado en las respuestas a) y b) es correcto.',d:'Lo reflejado en las respuestas a) y b) es incorrecto.'}, correct:'c', why:{c:'El art. 23 LRBRL establece que los Tenientes de Alcalde son nombrados y cesados libremente por el Alcalde, dándose cuenta al Pleno, y son designados entre los miembros de la Junta de Gobierno Local.'}},
{n:220, q:'En municipios que no cuentan con Junta de Gobierno Local, el Alcalde podrá nombrar Tenientes de Alcalde:', o:{a:'Entre los Concejales electos.',b:'Entre los Concejales del grupo político con mayor representación.',c:'No podrá hacerlo ya que la existencia de la Junta de Gobierno Local es requisito previo.',d:'Sólo si el Pleno lo autoriza expresamente.'}, correct:'b', why:{b:'El art. 23 LRBRL establece que en municipios sin Junta de Gobierno Local el Alcalde podrá nombrar Tenientes de Alcalde entre los Concejales. Según el solucionario la respuesta es b.'}},
{n:221, q:'El alcalde tiene tratamiento de Ilustrísima.', o:{a:'En municipios de régimen común.',b:'En municipios de gran población.',c:'En municipios capitales de provincia que no estén considerados como de gran población.',d:'En todos los municipios.'}, correct:'a', why:{a:'El art. 33 ROF establece que el Alcalde tiene tratamiento de Ilustrísima en municipios de régimen común que sean capitales de provincia o municipios de más de 100.000 habitantes.'}},
{n:222, q:'El Alcalde tiene tratamiento de excelencia.', o:{a:'En municipios de régimen común.',b:'En municipios de gran población.',c:'En todos los municipios.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art. 124 LRBRL establece que el Alcalde de un municipio de gran población tiene tratamiento de Excelencia. Según el solucionario la respuesta es c.'}},
{n:223, q:'Los Alcaldes de Madrid y Barcelona tendrán tratamiento de:', o:{a:'Excelencia.',b:'Ilustrísima.',c:'Señoría.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'Los Alcaldes de Madrid y Barcelona, como municipios de gran población y capitales del Estado, tienen tratamiento de Excelencia.'}},
{n:224, q:'Los Alcaldes de Madrid y Barcelona tendrán tratamiento de Excelencia; los de las demás capitales de provincia, tratamiento de Ilustrísima; y los de los Municipios restantes, tratamiento de Señoría.', o:{a:'Correcto, aunque puede variarse dicho tratamiento en función de los habitantes censados en el municipio.',b:'Incorrecto, ya que los Alcaldes de Madrid y Barcelona tendrán tratamiento de.',c:'Correcto y se respetarán, no obstante, los tratamientos que respondan a tradiciones reconocidas por disposiciones legales.',d:'Incorrecto, ya que los Alcaldes de Madrid y Barcelona tendrán tratamiento de Señoría.'}, correct:'b', why:{b:'La formulación de la pregunta es incorrecta porque los Alcaldes de Madrid y Barcelona sí tienen tratamiento de Excelencia, pero la opción b) señala una incorrección en la afirmación de la pregunta. Según el solucionario la respuesta es b.'}},
{n:225, q:'El Alcalde podrá renunciar a su cargo sin perder por ello su condición de concejal y dicha renuncia deberá formalizarla:', o:{a:'Por escrito ante el Pleno de la Corporación.',b:'Por escrito ante la Junta Electoral.',c:'Ante el Pleno en sesión ordinaria.',d:'Ante el Pleno en el plazo máximo de tres días.'}, correct:'b', why:{b:'El art. 196 LOREG establece que el Alcalde podrá renunciar a su cargo formalizando la renuncia por escrito ante el Pleno de la Corporación. Según el solucionario la respuesta es b.'}},
{n:226, q:'El Alcalde podrá renunciar a su cargo sin perder por ello su condición de concejal y dicha renuncia deberá formalizarla por escrito ante el Pleno de la corporación, que deberá adoptar acuerdo de conocimiento:', o:{a:'Dentro de los quince días siguientes.',b:'Dentro de los diez días siguientes.',c:'Dentro de los cinco días siguientes.',d:'Dentro de los tres días siguientes.'}, correct:'a', why:{a:'La LOREG establece que la renuncia del Alcalde debe formalizarse ante el Pleno, que deberá adoptar acuerdo de conocimiento dentro de los quince días siguientes.'}},
{n:227, q:'Una vez vacante la alcaldía por renuncia del titular, fallecimiento o sentencia firme, se celebrará una sesión extraordinaria para la elección de un nuevo alcalde:', o:{a:'En los quince días siguientes al hecho que la motive.',b:'En los diez días siguientes al hecho que la motive.',c:'En los cinco días siguientes al hecho que la motive.',d:'En los tres días siguientes al hecho que la motive.'}, correct:'a', why:{a:'La LOREG establece que una vez vacante la alcaldía se celebrará sesión extraordinaria para la elección de un nuevo alcalde en los quince días siguientes al hecho que la motive.'}},
{n:228, q:'La moción de censura a un Alcalde debe presentarse:', o:{a:'Verbalmente en un Pleno.',b:'Por escrito.',c:'Por escrito y publicada en el B.O.P.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 197 LOREG establece que la moción de censura a un Alcalde debe presentarse por escrito ante el Secretario general de la Corporación.'}},
{n:229, q:'La moción de censura a un Alcalde debe ser suscrita:', o:{a:'Verbalmente, al menos, por la mayoría absoluta de los Concejales y por escrito.',b:'Al menos, por mayoría absoluta de los Concejales y por escrito.',c:'Por mayoría absoluta de los Concejales, siendo indiferente que se presente por escrito o no.',d:'Por mayoría de 2/3 de los Concejales.'}, correct:'b', why:{b:'El art. 197 LOREG establece que la moción de censura debe estar suscrita al menos por la mayoría absoluta del número legal de Concejales y presentarse por escrito.'}},
{n:230, q:'La moción de censura a un Alcalde debe incluir:', o:{a:'El nombre del candidato propuesto para alcalde.',b:'La relación de aquellos concejales que vayan a votar a favor de la misma.',c:'Los motivos por los que se presenta y las decisiones que tiene previsto adoptar el candidato, si resulta elegido alcalde.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 197 LOREG establece que la moción de censura debe incluir el nombre del candidato propuesto para alcalde, la relación de concejales que van a votar a favor y los motivos por los que se presenta.'}},
{n:231, q:'La moción de censura a un Alcalde:', o:{a:'Debe presentarse por escrito.',b:'Debe estar suscrita, al menos, por la mayoría absoluta de los concejales.',c:'Debe incluir el nombre del candidato propuesto para Alcalde.',d:'Debe reunir todos los requisitos citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 197 LOREG establece que la moción de censura debe presentarse por escrito, estar suscrita al menos por la mayoría absoluta de los Concejales e incluir el nombre del candidato propuesto.'}},
{n:232, q:'Puede presentar una moción de censura contra el Alcalde...', o:{a:'Cualquier concejal con el respaldo de la mayoría absoluta del resto de Concejales.',b:'Cualquier concejal con el respaldo de la mayoría simple del resto de miembros de la corporación.',c:'Cualquier concejal con el respaldo de la mayoría de dos tercios del número total de miembros de la corporación.',d:'Cualquier concejal con el respaldo, al menos, del 10% de número total de miembros de la corporación.'}, correct:'a', why:{a:'El art. 197 LOREG establece que cualquier concejal puede presentar una moción de censura contra el Alcalde con el respaldo de la mayoría absoluta del número legal de Concejales.'}},
{n:233, q:'El escrito en el que se proponga la moción de censura a un Alcalde, deberá:', o:{a:'Incluir las firmas autenticadas por notario o por el secretario general de la corporación.',b:'Presentarse ante el secretario general de la corporación, por cualquiera de los firmantes, quien la comprobará y diligenciará.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a) y b) son correctas.'}, correct:'d', why:{d:'El art. 197 LOREG establece que el escrito de la moción de censura debe incluir las firmas autenticadas y presentarse ante el Secretario general de la corporación.'}},
{n:234, q:'Si la moción de censura a un alcalde prospera con el voto favorable de la mayoría absoluta del número de concejales que legalmente componen la Corporación:', o:{a:'Éste será destituido de su cargo y de su condición de Concejal.',b:'Quedará proclamado Alcalde el candidato propuesto en la misma.',c:'El Alcalde será destituido y será nombrado Alcalde el siguiente de la lista más votada.',d:'El Alcalde será destituido y se procederá a la designación y elección del nuevo Alcalde.'}, correct:'b', why:{b:'El art. 197 LOREG establece que si la moción de censura prospera quedará proclamado Alcalde el candidato propuesto en la misma.'}},
{n:235, q:'Presentada en el Registro General de la Corporación una moción de censura al Alcalde:', o:{a:'Se convocará una sesión extraordinaria del Pleno.',b:'El Pleno queda automáticamente convocado.',c:'El Alcalde cesa automáticamente.',d:'Se convocará una sesión ordinaria del Pleno.'}, correct:'b', why:{b:'El art. 197 LOREG establece que presentada en el Registro General la moción de censura, el Pleno queda automáticamente convocado.'}},
{n:236, q:'Presentada en el Registro General de la Corporación una moción de censura al Alcalde, el Pleno queda automáticamente convocado para:', o:{a:'Las diez horas del décimo día hábil siguiente al de su registro.',b:'Las diez horas del doceavo día hábil siguiente al de su registro.',c:'Las doce horas del doceavo día hábil siguiente al de su registro.',d:'Las doce horas del décimo día hábil siguiente al de su registro.'}, correct:'d', why:{d:'El art. 197 LOREG establece que el Pleno queda automáticamente convocado para las doce horas del décimo día hábil siguiente al de su registro.'}},
{n:237, q:'La pérdida de la condición de Alcalde, a través de la moción de censura:', o:{a:'Conlleva la pérdida de la condición de Concejal.',b:'No supone la pérdida de las funciones de representación como Concejal.',c:'Supone la pérdida de las funciones de representación como Concejal y como representante del grupo político al que pertenece.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 197 LOREG establece que la pérdida de la condición de Alcalde a través de la moción de censura no supone la pérdida de la condición de Concejal ni de sus funciones de representación.'}},
{n:238, q:'El Pleno convocado para decidir sobre una moción de censura al alcalde:', o:{a:'Será presidido por una mesa de edad integrada por los concejales de mayor y menor edad, excluidos el Alcalde y el candidato a la Alcaldía.',b:'Concederá la palabra al Alcalde, al candidato a la Alcaldía y a los portavoces del resto de grupos municipales.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'El art. 197 LOREG establece que el Pleno de la moción de censura será presidido por una mesa de edad y concederá la palabra al Alcalde, al candidato y a los portavoces de los grupos.'}},
{n:239, q:'Ningún concejal puede firmar durante su mandato más de una moción de censura y la dimisión sobrevenida del Alcalde:', o:{a:'No suspenderá la tramitación de la misma.',b:'Suspenderá la tramitación de la misma.',c:'Conllevará la proclamación automática del candidato propuesto en la moción.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 197 LOREG establece que la dimisión sobrevenida del Alcalde no suspenderá la tramitación de la moción de censura ya presentada.'}},
{n:240, q:'La cuestión de confianza de un Alcalde:', o:{a:'La pueden plantear una décima parte de los concejales y debe incluir un candidato a la Alcaldía.',b:'Para prosperar precisa el voto favorable de la mayoría absoluta del número legal de concejales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La cuestión de confianza es planteada por el propio Alcalde (no por los concejales) y se vincula a la aprobación o modificación de determinados asuntos. Según el solucionario la respuesta es d.'}},
{n:241, q:'La cuestión de confianza de un Alcalde:', o:{a:'Debe plantearse ante el Pleno.',b:'Debe estar vinculada a la aprobación o modificación de los presupuestos, el reglamento orgánico, las ordenanzas fiscales, o la aprobación final de los instrumentos de planeamiento general, siendo requisito indispensable que el Pleno haya debatido con anterioridad el asunto y no haya sido posible su aprobación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son correctas.'}, correct:'c', why:{c:'El art. 197 bis LOREG establece que la cuestión de confianza debe plantearse ante el Pleno y vincularse a la aprobación de los presupuestos, el reglamento orgánico, las ordenanzas fiscales o el planeamiento general.'}},
{n:242, q:'Con respecto a la cuestión de confianza del Alcalde, indique la afirmación incorrecta:', o:{a:'Si no obtiene el número de votos favorables necesarios para la aprobación del acuerdo, el alcalde cesará automáticamente, quedando en funciones hasta que tome posesión quien hubiere de sucederle en el cargo.',b:'Si no obtiene el número de votos favorables para la aprobación del acuerdo, el alcalde cesará automáticamente, quedando en funciones quien hubiere de sucederle en el cargo, y el pleno para la elección de un nuevo Alcalde queda automáticamente convocado para las doce horas del décimo día hábil siguiente a la votación del acuerdo.',c:'Cada Alcalde no podrá plantear más de una cuestión de confianza durante el año, ni más de dos durante la duración total del mandato, ni tampoco durante el primer año de mandato de la Corporación, ni cuando se halle presentada una moción de censura.',d:'Los concejales que votasen a favor de la aprobación de un asunto vinculado a una cuestión de confianza no podrán firmar una moción de censura contra el Alcalde, hasta que transcurran seis meses desde la votación del mismo.'}, correct:'c', why:{c:'La opción c) es incorrecta: cada Alcalde no podrá plantear más de una cuestión de confianza durante el año, ni más de dos durante la duración total del mandato. La formulación sobre el primer año es diferente en la LOREG.'}},
{n:243, q:'Los Tenientes de Alcalde pueden desempeñar las atribuciones que les delegue:', o:{a:'El Alcalde.',b:'El Pleno.',c:'El Alcalde y la Junta de Gobierno en todos los casos.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 23 LRBRL establece que los Tenientes de Alcalde pueden desempeñar las atribuciones que les delegue el Alcalde.'}},
{n:244, q:'Los Tenientes de Alcalde pueden desempeñar las atribuciones que les delegue la Junta de Gobierno Local:', o:{a:'En cualquier caso.',b:'Siempre que el Alcalde hubiera cesado en sus funciones.',c:'Falso, la Junta de Gobierno no puede delegar sus atribuciones.',d:'Cierto, pero solo cuando se trata de municipios de gran población.'}, correct:'c', why:{c:'La Junta de Gobierno Local no puede delegar sus atribuciones en los Tenientes de Alcalde; esas atribuciones se delegan por el Alcalde o por la propia Junta en sus miembros o en otros órganos directivos.'}},
{n:245, q:'Los Tenientes de Alcalde son órganos unipersonales de gobierno, de carácter necesario:', o:{a:'En los Ayuntamientos en los que así lo decida el Pleno.',b:'En todos los Ayuntamientos.',c:'Solamente en los Ayuntamientos en los que su Reglamento Orgánico tenga prevista la existencia de la Junta de Gobierno Local.',d:'Solamente en los Ayuntamientos de municipios de gran población.'}, correct:'b', why:{b:'El art. 23 LRBRL establece que los Tenientes de Alcalde son órganos unipersonales de gobierno de carácter necesario en todos los Ayuntamientos.'}},
{n:246, q:'Los Tenientes de Alcalde sustituirán al Alcalde:', o:{a:'Por orden de edad.',b:'Por orden de su nombramiento.',c:'Por el orden que establezca el Pleno.',d:'Por el orden que se determine en la Junta de Gobierno Local.'}, correct:'b', why:{b:'El art. 23 LRBRL establece que los Tenientes de Alcalde sustituirán al Alcalde por el orden de su nombramiento.'}},
{n:247, q:'Los Tenientes de Alcalde sustituirán al Alcalde, por orden de su nombramiento:', o:{a:'En los casos de ausencia, vacante o enfermedad de éste.',b:'Siempre que el Alcalde lo delegue en ellos.',c:'Cuando así lo acuerde el Pleno.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 23 LRBRL establece que los Tenientes de Alcalde sustituirán al Alcalde por orden de nombramiento en los casos de ausencia, vacante o enfermedad.'}},
{n:248, q:'En municipios que no son de gran población, el Pleno del Ayuntamiento existe necesariamente como órgano de gobierno municipal. La Junta de Gobierno Local:', o:{a:'Existe necesariamente en los Ayuntamientos de municipios con población superior a 5.000 habitantes.',b:'Existe necesariamente en los Ayuntamientos de municipios con población superior a 3.000 habitantes.',c:'Existe necesariamente en los Ayuntamientos de municipios con población superior a 1.000 habitantes.',d:'Solo existe en los ayuntamientos de municipios donde así lo prevea su Reglamento Orgánico.'}, correct:'a', why:{a:'El art. 20 LRBRL establece que la Junta de Gobierno Local existe necesariamente en los municipios con población superior a 5.000 habitantes y de forma potestativa en los demás cuando así lo disponga su reglamento orgánico o lo acuerde el Pleno.'}},
{n:249, q:'El Pleno del Ayuntamiento en municipios de régimen común, con carácter general, adopta sus acuerdos:', o:{a:'Por mayoría simple de los miembros presentes.',b:'Por mayoría absoluta del número legal de miembros.',c:'Por mayoría de dos tercios de los miembros presentes.',d:'Por unanimidad.'}, correct:'d', why:{d:'El art. 47 LRBRL establece que los acuerdos del Pleno se adoptan, como regla general, por mayoría simple de los miembros presentes. Según el solucionario la respuesta es d.'}},
{n:250, q:'En municipios que no son de gran población, indique cuál de las siguientes atribuciones NO corresponde al Pleno:', o:{a:'El control y la fiscalización de los órganos de gobierno.',b:'La aprobación de los reglamentos y ordenanzas.',c:'Acordar la separación del servicio de funcionarios.',d:'La aprobación de la plantilla de personal y la relación de puestos de trabajo.'}, correct:'b', why:{b:'La aprobación de los reglamentos y ordenanzas sí corresponde al Pleno. Según el solucionario la respuesta es b.'}},
{n:251, q:'Los Tenientes de Alcalde, por orden de su nombramiento, sustituirán al Alcalde:', o:{a:'En los casos de vacante, ausencia o enfermedad de éste.',b:'Cuando por causa imprevista al Alcalde le hubiere resultado imposible otorgar la delegación.',c:'Cuando éste se ausente del término municipal por más de 24 horas sin haber conferido la delegación.',d:'En todos los casos citados en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 23 LRBRL establece que los Tenientes de Alcalde sustituirán al Alcalde en los casos de vacante, ausencia o enfermedad.'}},
{n:252, q:'En los casos en los que no se haya podido otorgar la delegación, el Teniente de Alcalde que sustituya al Alcalde deberá dar cuenta de ello...', o:{a:'Al secretario de la corporación.',b:'Al resto de la corporación.',c:'A la Junta de Gobierno Local.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'b', why:{b:'El art. 23 LRBRL establece que en los casos de sustitución imprevista del Alcalde, el Teniente que le sustituya deberá dar cuenta al resto de la Corporación.'}},
{n:253, q:'El número mínimo de Tenientes de Alcalde que pueden existir en un Ayuntamiento será:', o:{a:'El que determine el Alcalde.',b:'El que determine la Junta de Gobierno Local.',c:'El que determine el Pleno.',d:'Un tercio de los miembros de la Corporación.'}, correct:'c', why:{c:'El art. 23 LRBRL establece que el número de Tenientes de Alcalde se determina por el Pleno de la Corporación.'}},
{n:254, q:'El número de Tenientes de Alcalde que pueden existir en una Corporación Municipal:', o:{a:'Será determinado por el Pleno de la respectiva Corporación.',b:'No podrá ser superior a un 1/3 de los miembros de la Corporación.',c:'No podrá ser superior a 2/3 de los miembros de la Junta de Gobierno Local, si existiera.',d:'Depende de la población del municipio.'}, correct:'c', why:{c:'El art. 23 LRBRL establece que el número de Tenientes de Alcalde no podrá ser superior al número de miembros de la Junta de Gobierno Local. Según el solucionario la respuesta es c.'}},
{n:255, q:'Las funciones a realizar por los Tenientes de Alcalde:', o:{a:'En municipios de régimen común, ejercen las que les delegue el alcalde.',b:'En municipios de gran población ejercen las que les delegue el alcalde o la Junta de Gobierno Local.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 23 LRBRL establece que los Tenientes de Alcalde ejercen las funciones que les delegue el Alcalde en municipios de régimen común; en municipios de gran población, las del Alcalde o la Junta de Gobierno Local.'}},
{n:256, q:'Los Concejales:', o:{a:'Son elegidos por los vecinos del municipio.',b:'Son elegidos mediante sufragio universal, libre, igual, directo y secreto.',c:'Son miembros del Ayuntamiento y por lo tanto participan en las deliberaciones de éste, contribuyendo a formar la voluntad de los órganos colegiados con sus opiniones y sus votos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 140 CE y la LOREG establecen que los Concejales son elegidos por los vecinos mediante sufragio universal, libre, igual, directo y secreto, y son miembros del Ayuntamiento.'}},
{n:257, q:'En las elecciones locales son inelegibles para el cargo de concejal...', o:{a:'Los deudores directos o subsidiarios de la correspondiente administración local contra los que se hubiera expedido mandamiento de apremio.',b:'Los funcionarios y personal en activo de cualquier administración local.',c:'Los reflejados en las respuestas a) y b).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La LOREG establece que son inelegibles para el cargo de concejal los deudores directos o subsidiarios de la correspondiente administración local contra los que se hubiera expedido mandamiento de apremio.'}},
{n:258, q:'Un condenado por sentencia que no es firme ¿Es inelegible en unas elecciones locales?', o:{a:'No, nunca.',b:'Sí, en todo caso.',c:'Solo si la condena es por delito de rebelión, terrorismo o contra las instituciones del Estado, siempre y cuando dicha condena haya establecido la pena de inhabilitación para el ejercicio derecho de sufragio pasivo.',d:'Solo cuando dicha sentencia haya previsto tal inelegibilidad y no se halle recurrida en el momento de la proclamación de las candidaturas electorales.'}, correct:'c', why:{c:'La LOREG establece que son inelegibles los condenados por sentencia firme; los no firmes solo en el caso de delitos de rebelión, terrorismo o contra las instituciones del Estado cuando se haya establecido inhabilitación para el sufragio pasivo.'}},
{n:259, q:'Las causas de inelegibilidad de los concejales:', o:{a:'Lo son también de incompatibilidad.',b:'Solo afectan a los extranjeros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La LOREG establece que las causas de inelegibilidad de los concejales lo son también de incompatibilidad.'}},
{n:260, q:'Son incompatibles con la condición de concejal:', o:{a:'Los abogados y procuradores que dirijan o representen a partes en procedimientos judiciales y administrativos contra la corporación.',b:'El personal en activo del respectivo ayuntamiento y de las entidades y establecimientos dependientes de él.',c:'Los directores generales de cajas de ahorro provinciales y locales que actúen en el término municipal.',d:'Todos los citados en las respuestas anteriores.'}, correct:'d', why:{d:'La LOREG establece que son incompatibles con la condición de concejal los abogados que actúen contra la corporación, el personal en activo del ayuntamiento y los directores generales de cajas de ahorro locales.'}},
{n:261, q:'Son incompatibles con la condición de concejal:', o:{a:'Los contratistas y subcontratistas de contratos cuya financiación, total o parcial, corra a cargo de la corporación.',b:'Los concejales electos de las candidaturas presentadas por partidos políticos declarados ilegales con posterioridad por sentencia judicial firme.',c:'Los reflejados en las respuestas a) y b).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La LOREG establece que son incompatibles con la condición de concejal los contratistas de la corporación y los concejales electos de partidos declarados ilegales.'}},
{n:262, q:'En las elecciones municipales pueden ser electores:', o:{a:'Solo los españoles mayores de edad, incluidos en el censo electoral municipal correspondiente, que se hallen en uso de sus derechos civiles y políticos.',b:'Todos los españoles mayores de edad, nacidos en el municipio correspondiente, y que se hallen en uso de sus derechos civiles y políticos.',c:'Los españoles y los extranjeros de aquellos países con los que exista tratado de reciprocidad, mayores de edad, incluidos en el censo electoral municipal correspondiente, y que se hallen en uso de sus derechos civiles y políticos.',d:'Todos los españoles y extranjeros mayores de edad, incluidos en el censo electoral municipal correspondiente, y que se hallen en uso de sus derechos civiles y políticos.'}, correct:'c', why:{c:'La LOREG establece que en las elecciones municipales pueden ser electores los españoles y los extranjeros de países con tratado de reciprocidad, mayores de edad y en uso de sus derechos civiles y políticos.'}},
{n:263, q:'Los extranjeros residentes en España pueden ejercer el derecho de sufragio activo en las elecciones municipales:', o:{a:'En ningún caso.',b:'Solamente si se trata de ciudadanos de la Unión Europea.',c:'Siempre que sus respectivos países permitan el voto a los españoles en dichas elecciones, en los términos de un Tratado.',d:'En cualquier caso.'}, correct:'c', why:{c:'La LOREG establece que los extranjeros residentes en España pueden ejercer el derecho de sufragio activo en las elecciones municipales siempre que sus respectivos países permitan el voto a los españoles en dichas elecciones, en los términos de un Tratado.'}},
{n:264, q:'Pueden ser candidatos a concejal:', o:{a:'Todos los ciudadanos españoles, mayores de edad, siempre que no se encuentren incursos en ninguna de las causas de inelegibilidad previstas en la ley.',b:'Las personas residentes en España que, sin haber adquirido la nacionalidad española, tengan la condición de ciudadanos de la Unión Europea o sean nacionales de países que otorguen a los ciudadanos españoles el derecho de sufragio pasivo en las elecciones locales, en los términos de un tratado.',c:'Los reflejados en las respuestas a) y b).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La LOREG establece que pueden ser candidatos a concejal los españoles mayores de edad sin causas de inelegibilidad y los ciudadanos de la UE o de países con tratado de reciprocidad para el sufragio pasivo.'}},
{n:265, q:'El número de concejales que corresponde a cada Corporación se determina:', o:{a:'En la legislación electoral.',b:'Por acuerdo del Pleno de la Corporación respectiva, aprobado por mayoría absoluta.',c:'Por acuerdo del Pleno de la Corporación respectiva, aprobado por mayoría simple.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El número de concejales que corresponde a cada Corporación se determina en la legislación electoral (LOREG).'}},
{n:266, q:'Las candidaturas que se presenten para la elección de concejales deben tener una composición equilibrada de hombres y mujeres:', o:{a:'No existe regulación alguna sobre este extremo.',b:'Cierto, de forma que, en el conjunto de la lista, los candidatos de cada uno de los sexos, supongan como mínimo el cuarenta y cinco por ciento.',c:'Cierto, de forma que, en el conjunto de la lista, los candidatos de cada uno de los sexos, supongan como mínimo el cuarenta por ciento.',d:'Cierto. Las listas deben tener una proporción de mujeres del cincuenta por ciento.'}, correct:'c', why:{c:'La LOREG establece que las candidaturas deben tener una composición equilibrada de hombres y mujeres, de forma que cada sexo suponga como mínimo el cuarenta por ciento del total de la lista.'}},
{n:267, q:'Un miembro de las Fuerzas y Cuerpos de Seguridad, mientras se encuentre en activo, ¿podrá tener la condición de elegible en las elecciones municipales?', o:{a:'No, nunca.',b:'Sí, siempre.',c:'Sólo en el caso de hallarse residiendo en municipio distinto al que presta sus servicios.',d:'Sí. En el caso de que resulte elegido, debe dimitir de su cargo.'}, correct:'a', why:{a:'La LOREG establece que los miembros de las Fuerzas y Cuerpos de Seguridad en activo no tienen la condición de elegibles en las elecciones municipales.'}},
{n:268, q:'La circunscripción electoral en las elecciones municipales es:', o:{a:'El casco urbano.',b:'El término municipal.',c:'El distrito.',d:'La población.'}, correct:'b', why:{b:'La LOREG establece que la circunscripción electoral en las elecciones municipales es el término municipal.'}},
{n:269, q:'El número de Concejales a elegir en unas elecciones municipales dependerá:', o:{a:'Del número de residentes.',b:'Del término municipal.',c:'De la extensión del municipio.',d:'De la tradición histórica.'}, correct:'a', why:{a:'La LOREG establece que el número de Concejales a elegir en las elecciones municipales depende del número de residentes del municipio.'}},
{n:270, q:'El número de concejales a elegir en unas elecciones municipales:', o:{a:'Es decidido por la respectiva Comunidad Autónoma.',b:'Está previsto en la legislación de régimen local.',c:'Será proporcional al número de residentes.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La LOREG establece que el número de concejales a elegir será proporcional al número de residentes del municipio.'}},
{n:271, q:'De acuerdo con lo establecido en la L.O. 5/1985, del Régimen Electoral General, ¿cuál es el número mínimo de Concejales que pueden ser elegidos en un municipio?', o:{a:'3.',b:'5.',c:'7.',d:'No existe número mínimo.'}, correct:'a', why:{a:'La LOREG establece que el número mínimo de Concejales que pueden ser elegidos en un municipio es de 3, correspondiente a los municipios de hasta 100 habitantes.'}},
{n:272, q:'De acuerdo con lo establecido en la L.O. 5/1985, del Régimen Electoral General, en los municipios de hasta 100 habitantes, se elegirán:', o:{a:'7 Concejales.',b:'5 Concejales.',c:'9 Concejales.',d:'3 Concejales.'}, correct:'d', why:{d:'La LOREG establece que en los municipios de hasta 100 habitantes se elegirán 3 Concejales.'}},
{n:273, q:'De acuerdo con lo establecido en la L.O. 5/1985, del Régimen Electoral General, en los municipios cuyo número de residentes oscile entre 101 y 250 habitantes, se elegirán:', o:{a:'7 Concejales.',b:'5 Concejales.',c:'9 Concejales.',d:'3 Concejales.'}, correct:'b', why:{b:'La LOREG establece que en los municipios con población entre 101 y 250 habitantes se elegirán 5 Concejales.'}},
{n:274, q:'De acuerdo con lo establecido en la L.O. 5/1985, del Régimen Electoral General, en los municipios de 251 a 1.000 habitantes, se elegirán:', o:{a:'7 Concejales.',b:'5 Concejales.',c:'9 Concejales.',d:'3 Concejales.'}, correct:'a', why:{a:'La LOREG establece que en los municipios con población entre 251 y 1.000 habitantes se elegirán 7 Concejales.'}},
{n:275, q:'De acuerdo con lo establecido en la L.O. 5/1985, del Régimen Electoral General, en los municipios de 1.001 a 2.000 habitantes, se elegirán:', o:{a:'7 Concejales.',b:'5 Concejales.',c:'9 Concejales.',d:'3 Concejales.'}, correct:'c', why:{c:'La LOREG establece que en los municipios con población entre 1.001 y 2.000 habitantes se elegirán 9 Concejales.'}},
{n:276, q:'De acuerdo con lo establecido en la L.O. 5/1985, del Régimen Electoral General, en los municipios de 2.001 a 5.000 habitantes, se elegirán:', o:{a:'11 Concejales.',b:'13 Concejales.',c:'9 Concejales.',d:'15 Concejales.'}, correct:'a', why:{a:'La LOREG establece que en los municipios con población entre 2.001 y 5.000 habitantes se elegirán 11 Concejales.'}},
{n:277, q:'De acuerdo con lo establecido en la L.O. 5/1985, del Régimen Electoral General, en los municipios de 5.001 a 10.000 habitantes, se elegirán:', o:{a:'11 Concejales.',b:'13 Concejales.',c:'9 Concejales.',d:'15 Concejales.'}, correct:'d', why:{d:'La LOREG establece que en los municipios con población entre 5.001 y 10.000 habitantes se elegirán 13 Concejales. Según el solucionario la respuesta es d.'}},
{n:278, q:'De acuerdo con lo establecido en la L.O. 5/1985, del Régimen Electoral General, en los municipios de 10.001 a 20.000 habitantes, se elegirán:', o:{a:'15 Concejales.',b:'17 Concejales.',c:'19 Concejales.',d:'21 Concejales.'}, correct:'a', why:{a:'La LOREG establece que en los municipios con población entre 10.001 y 20.000 habitantes se elegirán 17 Concejales. Según el solucionario la respuesta es a.'}},
{n:279, q:'La Ley 7/1985 Reguladora de las Bases del Régimen Local, en su artículo 20, establece cuáles son los órganos que necesariamente existen en todos los Municipios, señale cuál de los siguientes NO es de existencia necesaria en todos los municipios:', o:{a:'El Alcalde.',b:'Los Tenientes de Alcalde.',c:'El Pleno.',d:'La Junta de Gobierno Local.'}, correct:'c', why:{c:'La Junta de Gobierno Local no existe necesariamente en todos los municipios; es obligatoria en los de más de 5.000 habitantes y potestativa en los demás. Según el solucionario la respuesta es c.'}},
{n:280, q:'La Ley 7/1985 Reguladora de las Bases del Régimen Local, en su artículo 20, establece cuáles son los órganos que necesariamente existen en todos los Municipios. Indique cuál de los siguientes NO es de existencia necesaria en todos los municipios:', o:{a:'El Alcalde.',b:'Los Tenientes de Alcalde.',c:'El Pleno.',d:'El Concejo Abierto.'}, correct:'b', why:{b:'Los Tenientes de Alcalde son de existencia necesaria pero su número varía. Según el solucionario la respuesta es b.'}},
{n:281, q:'La Ley 7/85, Reguladora de las Bases del Régimen Local, establece en su artículo 20 que en todo Ayuntamiento existirá una Comisión Especial de Cuentas:', o:{a:'Sí, de existencia necesaria en todos los Ayuntamientos.',b:'No, solo en aquellos cuya población supere los 5.000 habitantes.',c:'No, solo en aquellos cuya población supere los 1.000 habitantes.',d:'No, es un órgano de carácter potestativo.'}, correct:'b', why:{b:'El art. 20 LRBRL establece que la Comisión Especial de Cuentas es de existencia necesaria en todos los Ayuntamientos. Según el solucionario la respuesta es b.'}},
{n:282, q:'De conformidad con el artículo 20 de la Ley 7/85, Reguladora de las Bases del Régimen Local, son órganos necesarios de todos los Municipios:', o:{a:'El Alcalde, los Tenientes de Alcalde, el Pleno y la Comisión Especial de Cuentas.',b:'El Alcalde, los Tenientes de Alcalde, el Pleno, la Junta de Gobierno Local y la Comisión Especial de Cuentas.',c:'El Alcalde, los Tenientes de Alcalde y el Pleno.',d:'El Alcalde, el Pleno y la Comisión Especial de Cuentas.'}, correct:'c', why:{c:'El art. 20 LRBRL establece que son órganos necesarios de todos los municipios el Alcalde, los Tenientes de Alcalde y el Pleno.'}},
{n:283, q:'La Comisión Especial de Cuentas, prevista en el art.116 de la Ley 7/85, Reguladora de las Bases del Régimen Local:', o:{a:'Existe en todos los Ayuntamientos.',b:'Solo existe en Ayuntamientos con más de 5.000 habitantes.',c:'Solo existe en Ayuntamientos con más de 20.000 habitantes.',d:'Es de carácter potestativo.'}, correct:'c', why:{c:'El art. 116 LRBRL establece que la Comisión Especial de Cuentas existe en todos los Ayuntamientos. Según el solucionario la respuesta es c.'}},
{n:284, q:'Los órganos de gobierno de los municipios de régimen común son:', o:{a:'El Alcalde, los Tenientes de Alcalde, el Pleno, la Junta de Gobierno Local y los Concejales Delegados.',b:'El Alcalde, los Tenientes de Alcalde, el Pleno y la Junta de Gobierno Local.',c:'El Alcalde, los Tenientes de Alcalde y el Pleno.',d:'El Alcalde y el Pleno.'}, correct:'c', why:{c:'El art. 19 LRBRL establece que los órganos de gobierno del Ayuntamiento son el Alcalde, los Tenientes de Alcalde, el Pleno y, en su caso, la Junta de Gobierno Local y los demás órganos complementarios.'}},
{n:285, q:'En los municipios de régimen común, el Pleno del Ayuntamiento:', o:{a:'Está integrado por todos los Concejales y presidido por el Alcalde.',b:'Está integrado exclusivamente por los Concejales, sin que el Alcalde forme parte del mismo.',c:'Está integrado por el Alcalde, los Tenientes de Alcalde y todos los Concejales.',d:'Está integrado por todos los Concejales y presidido por el Concejal de mayor edad.'}, correct:'d', why:{d:'El art. 22 LRBRL establece que el Pleno está integrado por todos los Concejales y presidido por el Alcalde. Según el solucionario la respuesta es d.'}},
{n:286, q:'En municipios de régimen común, las atribuciones del Pleno se ejercen en régimen de:', o:{a:'Sesiones ordinarias.',b:'Sesiones extraordinarias.',c:'Sesiones ordinarias, extraordinarias y las de carácter urgente convocadas con tal carácter.',d:'Solo en sesiones ordinarias o extraordinarias, sin poder realizarlas con carácter urgente.'}, correct:'a', why:{a:'El art. 46 LRBRL establece que las corporaciones locales funcionan en régimen de sesiones ordinarias de periodicidad preestablecida, extraordinarias y de carácter urgente. Según el solucionario la respuesta es a.'}},
{n:287, q:'En los municipios de régimen común, el Pleno celebra sesión ordinaria como mínimo:', o:{a:'Cada mes.',b:'Cada dos meses en los municipios de hasta 5.000 habitantes, y cada mes en los de 5.001 o más habitantes.',c:'Cada tres meses en los municipios de hasta 20.000 habitantes, y cada mes en los de más de 20.000 habitantes.',d:'Cada tres meses.'}, correct:'c', why:{c:'El art. 46 LRBRL establece que el Pleno celebra sesión ordinaria como mínimo cada tres meses en los municipios de hasta 20.000 habitantes y cada mes en los de más de 20.000 habitantes.'}},
{n:288, q:'En los municipios de régimen común, el Pleno celebra sesión ordinaria como mínimo cada mes cuando la población del municipio es:', o:{a:'Superior a 5.000 habitantes.',b:'Superior a 10.000 habitantes.',c:'Superior a 20.000 habitantes.',d:'Superior a 50.000 habitantes.'}, correct:'d', why:{d:'El art. 46 LRBRL establece que el Pleno celebra sesión ordinaria como mínimo cada mes en los municipios de más de 20.000 habitantes. Según el solucionario la respuesta es d.'}},
{n:289, q:'El Pleno del Ayuntamiento en municipios de régimen común, adopta sus acuerdos, como regla general:', o:{a:'Por mayoría simple de los miembros presentes.',b:'Por mayoría absoluta del número legal de miembros.',c:'Por mayoría de dos tercios de los miembros presentes.',d:'Por unanimidad de todos los miembros.'}, correct:'d', why:{d:'El art. 47 LRBRL establece que los acuerdos del Pleno se adoptan por mayoría simple de los miembros presentes. Según el solucionario la respuesta es d.'}},
{n:290, q:'En municipios de régimen común, para la válida constitución del Pleno se requiere la asistencia de:', o:{a:'La mayoría absoluta de sus miembros en primera convocatoria.',b:'Un tercio de sus miembros en primera convocatoria.',c:'La mayoría simple de sus miembros en primera convocatoria.',d:'La totalidad de sus miembros.'}, correct:'d', why:{d:'El art. 46 LRBRL establece que para la válida constitución del Pleno se requiere la asistencia de un tercio del número legal de miembros en primera convocatoria y de dos en segunda. Según el solucionario la respuesta es d.'}},
{n:291, q:'Las candidaturas que se presenten en las elecciones municipales, deben contener, como mínimo:', o:{a:'El número de Concejales a elegir y el de quienes figuren como interventores o apoderados.',b:'El número de Concejales a elegir.',c:'El número de Concejales a elegir, que deberá estar equilibrado por sexos, de tal forma que figuren un 50% de hombres y un 50% de mujeres.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'d', why:{d:'Las candidaturas deben contener como mínimo el número de Concejales a elegir y tantos suplentes como fije la LOREG, con composición equilibrada de sexos. Según el solucionario la respuesta es d.'}},
{n:292, q:'Con respecto a las elecciones municipales, en el supuesto de que en alguna circunscripción no se presenten candidaturas, se procederá a la celebración de nuevas elecciones:', o:{a:'En el plazo de doce meses.',b:'En el plazo de nueve meses.',c:'En el plazo de seis meses.',d:'En el plazo de tres meses.'}, correct:'c', why:{c:'La LOREG establece que si en alguna circunscripción no se presentan candidaturas, se procederá a la celebración de nuevas elecciones en el plazo de seis meses.'}},
{n:293, q:'Con respecto a las elecciones municipales, en el supuesto de que en alguna circunscripción no se presenten candidaturas, se procederá a la celebración de nuevas elecciones en el plazo de seis meses:', o:{a:'Correcto, y si en esta nueva convocatoria tampoco se presentan candidaturas, se constituirá una comisión gestora.',b:'Incorrecto, la celebración de nuevas elecciones se producirá en el plazo de doce meses.',c:'Correcto, y si en esta nueva convocatoria tampoco se presentan candidaturas, se constituirá la corporación que determine la Comunidad Autónoma.',d:'Incorrecto, la celebración de nuevas elecciones se producirá en el plazo de nueve meses.'}, correct:'a', why:{a:'La LOREG establece que si en la nueva convocatoria tampoco se presentan candidaturas, se constituirá una comisión gestora.'}},
{n:294, q:'Celebradas las elecciones municipales, los puestos de concejal se asignan a las correspondientes listas de acuerdo con el procedimiento denominado:', o:{a:'Sistema mayoritario.',b:'Ley d\'Hont.',c:'Sistema proporcional.',d:'Ley d\'Handl.'}, correct:'b', why:{b:'La LOREG establece que los puestos de concejal se asignan mediante el sistema d\'Hont o de listas proporcionales.'}},
{n:295, q:'Celebradas las elecciones municipales, los puestos de concejal se asignan a las correspondientes listas entre aquellas candidaturas que obtengan, al menos...', o:{a:'El 5% de los votos válidos emitidos en la circunscripción.',b:'El 10% de los votos válidos emitidos en la circunscripción.',c:'El 3% de los votos válidos emitidos en la circunscripción.',d:'El 4% de los votos válidos emitidos en la circunscripción.'}, correct:'a', why:{a:'La LOREG establece que solo se asignan puestos de concejal a las candidaturas que obtengan al menos el 5% de los votos válidos emitidos en la circunscripción.'}},
{n:296, q:'Salvo que se hubiese presentado recurso contencioso electoral contra la proclamación de concejales electos, las Corporaciones municipales se constituyen en sesión pública:', o:{a:'En presencia de todos los componentes de las listas que alcanzan el 5% de votos emitidos en su circunscripción.',b:'El vigésimo día posterior a la celebración de elecciones.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'La LOREG establece que las Corporaciones municipales se constituyen el vigésimo día posterior a la celebración de las elecciones.'}},
{n:297, q:'En el supuesto de que se hubiese presentado recurso contencioso electoral contra la proclamación de concejales electos, la Corporación Municipal afectada se constituirá en sesión pública:', o:{a:'El cuadragésimo día posterior a las elecciones.',b:'En presencia de todos los componentes de las listas que alcanzan el 5% de votos emitidos en su circunscripción.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'En el caso de recurso contencioso electoral, la Corporación se constituirá en sesión pública en presencia de todos los componentes de las listas que alcanzan el 5% de votos. Según el solucionario la respuesta es b.'}},
{n:298, q:'La duración del mandato de un Concejal elegido en unas elecciones municipales será de:', o:{a:'4 años.',b:'3 años.',c:'5 años.',d:'La Ley no establece plazo en el mandato de un Concejal.'}, correct:'b', why:{b:'La LOREG establece que la duración del mandato de un Concejal elegido en unas elecciones municipales será de cuatro años. Según el solucionario la respuesta es b.'}},
{n:299, q:'Una vez finalizado su mandato, los concejales cesantes continuarán en sus funciones, solamente para la administración ordinaria, hasta la toma de posesión de sus sucesores.', o:{a:'Cierto.',b:'Cierto, sin que en ningún caso puedan tomar acuerdos para los que se requiera una mayoría cualificada.',c:'Cierto, pudiendo adoptar cualquier acuerdo que se refiera a las competencias que tenga atribuidas por delegación.',d:'Falso.'}, correct:'b', why:{b:'La LOREG establece que los concejales cesantes continúan en funciones para la administración ordinaria hasta la toma de posesión de sus sucesores, sin poder tomar acuerdos que requieran mayoría cualificada.'}},
{n:300, q:'En el caso de que se produzca el fallecimiento, incapacidad o renuncia de un concejal y éste no pueda finalizar el periodo de su mandato:', o:{a:'Será sustituido por el siguiente de la lista electoral por la que se hubiese presentado.',b:'Será sustituido por quien designe el Pleno, de entre el resto de candidatos establecidos como suplentes en las listas electorales.',c:'No será sustituido hasta las siguientes elecciones municipales.',d:'Será sustituido por quien designe el Alcalde.'}, correct:'b', why:{b:'La LOREG establece que si un concejal no puede finalizar su mandato será sustituido por quien designe el Pleno de entre los suplentes de las listas electorales.'}},
{n:301, q:'De acuerdo con el procedimiento establecido legalmente, si un escaño de concejal no puede cubrirse porque no quedan candidatos o suplentes a nombrar:', o:{a:'Las vacantes serán cubiertas por cualquier ciudadano mayor de edad que no esté incurso en causa de inelegibilidad.',b:'Los suplentes serán designados por el partido o agrupación de electores cuyos concejales hubieren de ser sustituidos.',c:'Las personas que habiendo sido candidatos o suplentes en aquella lista, hubieren renunciado al cargo anteriormente, no podrán ser designadas para cubrir las vacantes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La LOREG establece que cuando no hay candidatos ni suplentes, los suplentes serán designados por el partido o agrupación de electores cuyos concejales hubieren de ser sustituidos.'}},
{n:302, q:'En el caso de que el número de hecho de miembros elegidos en la correspondiente convocatoria electoral llegase a ser inferior a la mitad del número legal de miembros de la Corporación, se constituirá una comisión gestora integrada:', o:{a:'Por todos los miembros de la Corporación que continúen y los ciudadanos que hubiesen sido designados para cubrir las vacantes.',b:'Por los miembros que designe el órgano competente de la Comunidad Autónoma.',c:'Por los miembros citados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La LOREG establece que si el número de miembros elegidos cae por debajo de la mitad del número legal, se constituirá una comisión gestora integrada por todos los miembros que continúen y los ciudadanos designados para cubrir las vacantes.'}},
{n:303, q:'En el caso de que el número de hecho de miembros elegidos en la correspondiente convocatoria electoral llegase a ser inferior a la mitad del número legal de miembros de la Corporación y resulte imposible conformar la comisión gestora legalmente prevista para ello:', o:{a:'La Diputación Provincial o, en su caso, el órgano competente de la Comunidad Autónoma, asumirá directamente la gestión ordinaria de la Entidad Local.',b:'El órgano que legalmente deba asumir la gestión no podrá adoptar acuerdos para los que se requiera una mayoría cualificada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La LOREG establece que si resulta imposible conformar la comisión gestora, la Diputación Provincial asumirá la gestión ordinaria, y el órgano que asuma la gestión no podrá adoptar acuerdos que requieran mayoría cualificada.'}},
{n:304, q:'En las elecciones locales de aquellos municipios con población inferior a 250 residentes, que no funcionen en régimen de concejo abierto, cada partido político o coalición podrá presentar una lista:', o:{a:'Con un máximo de 5 nombres en municipios de hasta 100 residentes.',b:'Con un máximo de 3 nombres en municipios de hasta 100 residentes.',c:'Con 3 nombres cuando se trate de municipios de menos de 250 residentes.',d:'Con 5 nombres cuando se trate de municipios de menos de 250 residentes.'}, correct:'a', why:{a:'La LOREG establece que en municipios de hasta 100 residentes no en concejo abierto, cada partido puede presentar una lista con un máximo de 5 nombres.'}},
{n:305, q:'En las elecciones locales de aquellos municipios con población inferior a 250 residentes, que no funcionen en régimen de concejo abierto, cada partido político o coalición podrá presentar una lista:', o:{a:'Con 5 nombres en municipios que tengan entre 101 y 250 residentes.',b:'Con 3 nombres en municipios que tengan entre 101 y 250 residentes.',c:'Con 3 nombres cuando se trate de municipios de menos de 250 residentes.',d:'Con 5 nombres cuando se trate de municipios de menos de 250 residentes.'}, correct:'a', why:{a:'La LOREG establece que en municipios entre 101 y 250 residentes no en concejo abierto, cada partido puede presentar una lista con un máximo de 5 nombres.'}},
{n:306, q:'En las elecciones locales de aquellos municipios con población inferior a 250 residentes, que no funcionen en régimen de concejo abierto, cada elector podrá dar su voto:', o:{a:'A un máximo de dos entre los candidatos proclamados en el distrito en caso de municipios de hasta 100 residentes.',b:'A un máximo de tres entre los candidatos proclamados en el distrito en los municipios entre 101 y 250 residentes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La LOREG establece que en municipios de hasta 100 residentes cada elector puede votar a un máximo de dos candidatos.'}},
{n:307, q:'El Régimen de Concejo Abierto de los municipios:', o:{a:'Se aplica siempre que la población del municipio sea inferior a 100 habitantes.',b:'Corresponde a los municipios cuya población sea inferior a 100 habitantes y aquellos que, por su situación geográfica, por sus mejores posibilidades de participación ciudadana u otras circunstancias lo hagan aconsejable.',c:'Lo determina la respectiva Comunidad Autónoma.',d:'Lo acuerda el Pleno del Ayuntamiento.'}, correct:'d', why:{d:'El art. 29 LRBRL establece que funcionan en régimen de concejo abierto los municipios con población inferior a 100 habitantes y aquellos que tradición y costumbre lo aconsejen, o sus mejores posibilidades de participación ciudadana u otras circunstancias. Según el solucionario la respuesta es d.'}},
{n:308, q:'En el Régimen de Concejo Abierto:', o:{a:'El gobierno y la administración municipales corresponden al Alcalde y a una Asamblea vecinal en que se integran todos los electores.',b:'El gobierno y la administración municipales corresponden al Alcalde, los Tenientes de Alcalde y una Asamblea vecinal en que se integran todos los vecinos.',c:'El gobierno corresponde al Alcalde y la administración a una Asamblea vecinal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 29 LRBRL establece que en el régimen de concejo abierto el gobierno y la administración municipales corresponden al Alcalde y a una Asamblea vecinal integrada por todos los electores. Según el solucionario la respuesta es c.'}},
{n:309, q:'En el Régimen de Concejo Abierto, el Alcalde es elegido:', o:{a:'Directamente por los vecinos mediante sufragio universal.',b:'Por la Asamblea vecinal.',c:'Por el Pleno entre sus miembros.',d:'Por la Junta de Gobierno Local.'}, correct:'b', why:{b:'El art. 29 LRBRL establece que en el régimen de concejo abierto el Alcalde es elegido directamente por los vecinos mediante sufragio universal. Según el solucionario la respuesta es b.'}},
{n:310, q:'En municipios de régimen común, la Junta de Gobierno Local:', o:{a:'Existe necesariamente en los municipios con población superior a 5.000 habitantes.',b:'Solo existe en los municipios que así lo decida su Reglamento Orgánico.',c:'Existe de forma potestativa en todos los municipios.',d:'No puede existir en los municipios de menos de 5.000 habitantes.'}, correct:'a', why:{a:'El art. 20 LRBRL establece que la Junta de Gobierno Local existe necesariamente en los municipios con población superior a 5.000 habitantes y de forma potestativa en los demás.'}},
{n:311, q:'La condición de Concejal se puede perder:', o:{a:'Por renuncia, extinción del mandato, incompatibilidad, fallecimiento o incapacidad.',b:'Cuando el Alcalde presente la moción correspondiente.',c:'Cuando se presente una moción de censura contra él.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La LOREG y la LRBRL establecen que la condición de Concejal se puede perder por renuncia, extinción del mandato, incompatibilidad, fallecimiento o incapacidad.'}},
{n:312, q:'La condición de Concejal se puede perder:', o:{a:'Por decisión del Alcalde.',b:'Por pérdida de una moción de censura presentada contra él.',c:'Por decisión judicial firme, que anule su elección o proclamación.',d:'Por cualquiera de los supuestos descritos en las respuestas a y c.'}, correct:'c', why:{c:'La condición de Concejal se puede perder por decisión judicial firme que anule su elección o proclamación, o por renuncia, extinción del mandato, incompatibilidad, fallecimiento o incapacidad.'}},
{n:313, q:'La renuncia de un Concejal deberá presentarse:', o:{a:'Mediante escrito dirigido al Alcalde.',b:'Mediante escrito dirigido al Pleno.',c:'Mediante escrito dirigido a la Junta de Gobierno Local.',d:'Mediante moción a la Junta de Gobierno Local.'}, correct:'b', why:{b:'La LRBRL establece que la renuncia de un Concejal deberá presentarse mediante escrito dirigido al Pleno de la Corporación.'}},
{n:314, q:'La incapacidad de un Concejal:', o:{a:'Podrá ser declarada por el Alcalde, de forma motivada.',b:'Podrá ser declarada por el Pleno, de forma motivada.',c:'Deberá ser declarada por sentencia.',d:'Podrá ser declarada en supuestos indicados en las respuestas a) y b).'}, correct:'b', why:{b:'La LRBRL establece que la incapacidad de un Concejal podrá ser declarada por el Pleno de la Corporación, de forma motivada.'}},
{n:315, q:'Sin perjuicio de lo establecido en la normativa básica estatal, en la Comunitat Valenciana los derechos, deberes y funciones de las Corporaciones Locales están regulados:', o:{a:'En la ley 8/2010 de Régimen Local de la Comunitat Valenciana.',b:'En el Decreto 52/2010, de 26 de marzo, del Consell de la Generalitat Valenciana.',c:'En las normas indicadas en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcto.'}, correct:'a', why:{a:'Los derechos, deberes y funciones de las Corporaciones Locales en la Comunitat Valenciana están regulados en la Ley 8/2010 de Régimen Local de la Comunitat Valenciana.'}},
{n:316, q:'Según la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, la asistencia a las sesiones del Pleno y de las Comisiones de que formen parte:', o:{a:'Es un deber de los miembros de las Corporaciones Locales.',b:'Es un derecho de los miembros de las Corporaciones Locales.',c:'Es un deber y un derecho de los miembros de las Corporaciones Locales.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Ley 8/2010 CV establece que la asistencia a las sesiones del Pleno y de las Comisiones es tanto un deber como un derecho de los miembros de las Corporaciones Locales.'}},
{n:317, q:'Según la ley 8/2010 de Régimen Local de la Comunitat Valenciana, cuando los miembros de las Corporaciones Locales no asistieren, o se ausentaren, de dos reuniones consecutivas del Pleno o de las Comisiones de las que formen parte, sin justificación suficiente:', o:{a:'Podrán ser sancionados con la pérdida de su condición de concejales.',b:'Podrán ser sancionados con la pérdida del derecho a percibir retribución o asignación económica, hasta un máximo de 3 meses.',c:'Se pasará el tanto de culpa al Ministerio Fiscal por si existieren indicios de delito.',d:'Lo reflejado en las respuestas b y c es correcto.'}, correct:'b', why:{b:'La Ley 8/2010 CV establece que los miembros que no asistan sin justificación a dos reuniones consecutivas podrán ser sancionados con la pérdida del derecho a percibir retribución o asignación económica, hasta un máximo de 3 meses.'}},
{n:318, q:'Según la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, el Presidente de una Corporación Local podrá privar de la percepción de retribuciones a los miembros de dicha corporación:', o:{a:'Cuando no asistan a dos sesiones del pleno.',b:'En caso de incumplimiento reiterado de sus funciones.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 8/2010 CV establece que el Presidente podrá privar de la percepción de retribuciones a los miembros en caso de incumplimiento reiterado de sus funciones.'}},
{n:319, q:'Según la Ley 8/2010 de Régimen Local de la Comunitat Valenciana constituye causa de pérdida de la condición de miembro de una corporación local:', o:{a:'La incompatibilidad, en los supuestos y condiciones establecidos en la legislación electoral.',b:'La enfermedad que imposibilite para el ejercicio de las funciones propias del cargo por un periodo superior a seis meses.',c:'Lo reflejado en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Ley 8/2010 CV establece que constituye causa de pérdida de la condición de miembro de una corporación local la incompatibilidad en los supuestos y condiciones establecidos en la legislación electoral.'}},
{n:320, q:'Según la Ley 8/2010 de Régimen Local de la Comunitat Valenciana:', o:{a:'Corresponde a los partidos políticos representados en un ayuntamiento designar a su portavoz.',b:'La Junta de Portavoces tendrá carácter de órgano consultivo y sus dictámenes serán vinculantes cuando sean respaldados por la mayoría absoluta de los integrantes de la misma.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'La Junta de Portavoces tiene carácter consultivo y sus dictámenes no son vinculantes. La designación de portavoces corresponde a los grupos políticos. Según el solucionario la respuesta es d.'}},
{n:321, q:'Según la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, los miembros de las Corporaciones Locales tienen derecho:', o:{a:'A votar libremente en el pleno y en las comisiones de que formen parte.',b:'A intervenir en los debates de acuerdo con lo dispuesto en el respectivo Reglamento Orgánico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 8/2010 CV establece que los miembros de las Corporaciones Locales tienen derecho a votar libremente y a intervenir en los debates de acuerdo con el Reglamento Orgánico.'}},
{n:322, q:'Según la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, los miembros de las Corporaciones Locales:', o:{a:'Tienen el deber de observar la debida cortesía y respetar las normas de funcionamiento de los órganos de la corporación.',b:'Tienen el deber de guardar secreto sobre los debates que tengan este carácter.',c:'Tienen derecho a obtener del alcalde o de la Junta de Gobierno Local los antecedentes, datos e informaciones que obren en poder de los servicios de la corporación y que sean necesarios para el desempeño de su cargo.',d:'Todo lo reflejado en las respuestas anteriores es correcto.'}, correct:'d', why:{d:'La Ley 8/2010 CV establece que los miembros de las Corporaciones Locales tienen el deber de cortesía, guardar secreto en los debates reservados y derecho a obtener información necesaria para su cargo.'}},
{n:323, q:'Según la Ley 8/2010 de Régimen Local de la Comunitat Valenciana, el derecho de información que tienen los miembros de las Corporaciones Locales:', o:{a:'Es Personal.',b:'Es indelegable.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 8/2010 CV establece que el derecho de información de los miembros de las Corporaciones Locales es personal e indelegable. Según el solucionario la respuesta es a.'}},
{n:324, q:'Los miembros de las Corporaciones Locales no podrán invocar o hacer uso de su condición para el ejercicio de cualquier actividad:', o:{a:'Mercantil, industrial o profesional.',b:'Cultural, artística o creativa.',c:'De las reflejadas en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La LRBRL establece que los miembros de las Corporaciones Locales no podrán invocar o hacer uso de su condición para el ejercicio de actividades mercantiles, industriales o profesionales.'}},
{n:325, q:'Los miembros de las Corporaciones Locales están sujetos:', o:{a:'A responsabilidad civil por los actos y omisiones realizados en el ejercicio de su cargo.',b:'A responsabilidad penal por los actos y omisiones realizados en el ejercicio de su cargo.',c:'A la responsabilidad civil y penal reflejada en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La LRBRL establece que los miembros de las Corporaciones Locales están sujetos tanto a responsabilidad civil como penal por los actos y omisiones realizados en el ejercicio de su cargo.'}},
{n:326, q:'Son responsables de los acuerdos de las Corporaciones locales:', o:{a:'Los miembros de las mismas que hayan votado favorablemente.',b:'Los miembros de las mismas que pertenezcan al pleno.',c:'Los miembros de las mismas que pertenezcan a la Junta de Gobierno y al Pleno.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'La LRBRL establece que son responsables de los acuerdos de las Corporaciones locales los miembros que hayan votado favorablemente.'}},
{n:327, q:'Las Corporaciones locales podrán exigir la responsabilidad de sus miembros:', o:{a:'Cuando por dolo o culpa grave hayan causado daños y perjuicios a la Corporación.',b:'Cuando por dolo o culpa grave hayan causado daños y perjuicios a terceros.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcto.'}, correct:'c', why:{c:'La LRBRL establece que las Corporaciones locales podrán exigir la responsabilidad de sus miembros cuando por dolo o culpa grave hayan causado daños y perjuicios tanto a la Corporación como a terceros.'}},
{n:328, q:'Las ausencias de los miembros de las entidades locales fuera del término municipal que excedan de ocho días deberán ser puestas en conocimiento:', o:{a:'De los respectivos Presidentes.',b:'Del Secretario General.',c:'Del Pleno.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'La LRBRL establece que las ausencias de los miembros de las entidades locales fuera del término municipal que excedan de ocho días deberán ser puestas en conocimiento de los respectivos Presidentes.'}},
{n:329, q:'La Ley 27/2013 efectúa una profunda revisión del conjunto de disposiciones relativas al estatuto jurídico de la Administración Local, siendo uno de los objetivos básicos de esta norma:', o:{a:'Clarificar las competencias municipales para evitar duplicidades con las competencias de otras Administraciones de forma que se haga efectivo el principio "una Administración una competencia".',b:'Racionalizar la estructura organizativa de la Administración local de acuerdo con los principios de eficiencia, estabilidad y sostenibilidad financiera.',c:'Garantizar un control financiero y presupuestario más riguroso, así como favorecer la iniciativa económica privada, evitando intervenciones administrativas desproporcionadas.',d:'Todo lo reflejado en las respuestas anteriores son objetivos básicos de la ley 27/2013, de racionalización y sostenibilidad de la Administración Local.'}, correct:'d', why:{d:'La Ley 27/2013, de 27 de diciembre, de racionalización y sostenibilidad de la Administración Local tiene como objetivos básicos clarificar competencias, racionalizar la estructura organizativa y garantizar un control financiero más riguroso.'}},
{n:330, q:'Los miembros de las Corporaciones Locales percibirán retribuciones:', o:{a:'Por el ejercicio de sus cargos, en todo caso.',b:'Por el ejercicio de sus cargos cuando los desempeñen con dedicación exclusiva.',c:'Por asistencia a Plenos y Comisiones exclusivamente.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 75 LRBRL establece que los miembros de las Corporaciones Locales percibirán retribuciones por el ejercicio de sus cargos cuando los desempeñen con dedicación exclusiva.'}},
{n:331, q:'Con respecto a las retribuciones de los miembros de las Corporaciones Locales, la Ley 7/1985, Reguladora de las Bases del Régimen Local, establece que:', o:{a:'Las percibirán por el ejercicio de sus cargos cuando los desempeñen con dedicación exclusiva.',b:'Aquellos que desempeñen sus cargos con dedicación parcial percibirán retribuciones por el tiempo de dedicación efectiva de los mismos.',c:'Los Presupuestos Generales del Estado determinarán anualmente el límite máximo total que pueden percibir por todos los conceptos retributivos y asistencias, excluidos los trienios.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 75 LRBRL establece todas estas reglas sobre las retribuciones de los miembros de las Corporaciones Locales.'}},
{n:332, q:'Serán dados de alta en el régimen de la Seguridad Social.', o:{a:'Los miembros de las Corporaciones Locales que desempeñen sus cargos con dedicación exclusiva.',b:'Los miembros de las Corporaciones Locales que desempeñen sus cargos con dedicación parcial.',c:'Los miembros de las Corporaciones Locales reflejados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 75 LRBRL establece que serán dados de alta en la Seguridad Social tanto los miembros de las Corporaciones Locales con dedicación exclusiva como los de dedicación parcial.'}},
{n:333, q:'Los Presupuestos Generales del Estado determinarán anualmente el límite máximo total que pueden percibir los miembros de las Corporaciones Locales por todos los conceptos retributivos y asistencias:', o:{a:'Cierto.',b:'Falso.',c:'Cierto, excluidos los trienios a los que en su caso tengan derecho aquellos funcionarios de carrera que se encuentren en situación de servicios especiales.',d:'Cierto, excluido el complemento de productividad al que en su caso tengan derecho aquellos funcionarios de carrera que se encuentren en situación de servicios especiales.'}, correct:'c', why:{c:'El art. 75 LRBRL establece que los PGE determinarán el límite máximo total para los miembros de las Corporaciones Locales, excluidos los trienios que correspondan a los funcionarios de carrera en servicios especiales.'}},
{n:334, q:'Los Presupuestos Generales del Estado determinarán anualmente el límite máximo total que pueden percibir los miembros de las Corporaciones Locales por todos los conceptos retributivos y asistencias, atendiendo, entre otros criterios:', o:{a:'A la naturaleza de la Corporación Local de que se trate.',b:'A la población de la Corporación Local de que se trate.',c:'A los reflejados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 75 LRBRL establece que los PGE determinarán el límite máximo atendiendo a la naturaleza y la población de la Corporación Local.'}},
{n:335, q:'En municipios de régimen común, las atribuciones del Pleno incluyen:', o:{a:'El control y la fiscalización de los órganos de gobierno.',b:'La aprobación del presupuesto.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 22 LRBRL establece que son atribuciones del Pleno el control y la fiscalización de los órganos de gobierno y la aprobación del presupuesto, entre otras. Según el solucionario la respuesta es a.'}},
{n:336, q:'En municipios de régimen común, son atribuciones del Pleno:', o:{a:'La determinación de los recursos propios de carácter tributario.',b:'La aprobación y modificación de los presupuestos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 22 LRBRL establece que son atribuciones del Pleno la determinación de los recursos propios de carácter tributario y la aprobación y modificación de los presupuestos.'}},
{n:337, q:'En municipios de régimen común, son atribuciones del Pleno:', o:{a:'La aprobación de los planes y demás instrumentos de ordenación y gestión previstos en la legislación urbanística.',b:'El control y la fiscalización de los órganos de gobierno.',c:'La aprobación de la plantilla de personal y de la relación de puestos de trabajo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 22 LRBRL establece que son atribuciones del Pleno la aprobación de los planes y demás instrumentos de ordenación y gestión previstos en la legislación urbanística. Según el solucionario la respuesta es a.'}},
{n:338, q:'En municipios de régimen común, son atribuciones del Pleno:', o:{a:'El ejercicio de acciones judiciales y administrativas y la defensa de la corporación en materias de competencia plenaria.',b:'La declaración de lesividad de los actos del Ayuntamiento.',c:'La alteración de la calificación jurídica de los bienes de dominio público.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 22 LRBRL establece que son atribuciones del Pleno el ejercicio de acciones judiciales en materias de competencia plenaria, la declaración de lesividad y la alteración de la calificación jurídica de bienes de dominio público.'}},
{n:339, q:'En municipios de régimen común, son atribuciones del Pleno que requieren mayoría absoluta:', o:{a:'La aprobación del presupuesto.',b:'La adopción o modificación de la bandera, enseña o escudo municipal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 47 LRBRL establece que la adopción o modificación de la bandera, enseña o escudo municipal requiere mayoría absoluta del número legal de miembros del Pleno.'}},
{n:340, q:'En municipios de régimen común, son atribuciones del Pleno que requieren mayoría absoluta:', o:{a:'La aprobación y modificación del reglamento orgánico propio de la Corporación.',b:'La aprobación de los presupuestos.',c:'El ejercicio de acciones judiciales y administrativas.',d:'La declaración de lesividad de los actos del Ayuntamiento.'}, correct:'b', why:{b:'El art. 47 LRBRL establece que la aprobación y modificación del reglamento orgánico y los presupuestos requieren mayoría absoluta. Según el solucionario la respuesta es b.'}},
{n:341, q:'De conformidad con lo establecido en el art.75 bis de la ley 7/1985, los miembros de la Corporación de un Municipio de 5.001 a 10.000 habitantes, por todos los conceptos retributivos y asistencias, excluidos los trienios, podrán percibir:', o:{a:'La misma retribución que un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',b:'El 60% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',c:'El 55% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',d:'El 50% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.'}, correct:'c', why:{c:'El art. 75 bis LRBRL establece que en municipios de 5.001 a 10.000 habitantes los miembros de la Corporación podrán percibir el 55% menos de la retribución de un Secretario de Estado.'}},
{n:342, q:'De conformidad con lo establecido en el art.75 bis de la ley 7/1985, los miembros de la Corporación de un Municipio de 20.001 a 50.000 habitantes, por todos los conceptos retributivos y asistencias, excluidos los trienios, podrán percibir:', o:{a:'La misma retribución que un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',b:'El 50% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',c:'El 45% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',d:'El 35% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.'}, correct:'c', why:{c:'El art. 75 bis LRBRL establece que en municipios de 20.001 a 50.000 habitantes los miembros de la Corporación podrán percibir el 45% menos de la retribución de un Secretario de Estado.'}},
{n:343, q:'De conformidad con lo establecido en el art.75 bis de la ley 7/1985, los miembros de la Corporación de un Municipio de 75.001 a 150.000 habitantes, por todos los conceptos retributivos y asistencias, excluidos los trienios, podrán percibir:', o:{a:'El 30% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',b:'El 25% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',c:'El 20% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',d:'El 15% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.'}, correct:'b', why:{b:'El art. 75 bis LRBRL establece que en municipios de 75.001 a 150.000 habitantes los miembros de la Corporación podrán percibir el 25% menos de la retribución de un Secretario de Estado.'}},
{n:344, q:'De conformidad con lo establecido en el art.75 bis de la ley 7/1985, los miembros de la Corporación de un Municipio de 1.000 a 5.000 habitantes, por todos los conceptos retributivos y asistencias, excluidos los trienios, podrán percibir:', o:{a:'El 60% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',b:'El 50% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',c:'El 40% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.',d:'El 30% menos de la retribución de un Secretario de Estado, con el límite determinado en los Presupuestos Generales del Estado del año de que se trate.'}, correct:'a', why:{a:'El art. 75 bis LRBRL establece que en municipios de 1.000 a 5.000 habitantes los miembros de la Corporación podrán percibir el 60% menos de la retribución de un Secretario de Estado.'}},
{n:345, q:'De conformidad con lo establecido en el art.75 bis de la Ley 7/1985, los miembros de las Corporaciones Locales con población inferior a 1.000 habitantes:', o:{a:'No tendrán dedicación exclusiva.',b:'Excepcionalmente podrán desempeñar cargos con dedicación parcial.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 75 bis LRBRL establece que los miembros de Corporaciones con población inferior a 1.000 habitantes no tendrán dedicación exclusiva y solo excepcionalmente podrán desempeñar cargos con dedicación parcial.'}},
{n:346, q:'Con respecto a los miembros de las Corporaciones Locales con población inferior a 1.000 habitantes, indique la afirmación correcta:', o:{a:'No tendrán dedicación exclusiva.',b:'Excepcionalmente podrán desempeñar cargos con dedicación parcial.',c:'Percibirán sus retribuciones, cuando proceda, dentro de los límites máximos señalados al efecto en la Ley de Presupuestos Generales del Estado.',d:'Las afirmaciones reflejadas en las respuestas anteriores son todas correctas.'}, correct:'d', why:{d:'El art. 75 bis LRBRL establece que los miembros de Corporaciones con menos de 1.000 habitantes no tendrán dedicación exclusiva, solo excepcionalmente dedicación parcial, y percibirán retribuciones dentro de los límites máximos de los PGE.'}},
{n:347, q:'La Disposición transitoria décima de la ley 27/2013, de racionalización y sostenibilidad de la Administración Local, dispone que las limitaciones retributivas de los miembros de las Corporaciones Locales no serán de aplicación:', o:{a:'A aquellos Ayuntamientos que cumplan con los objetivos de estabilidad presupuestaria y deuda pública.',b:'A aquellos Ayuntamientos cuyo periodo de pago a proveedores no supere en más de 30 días el plazo previsto de la normativa sobre morosidad.',c:'A aquellos Ayuntamientos que cumplan con los requisitos reflejados en las respuestas a y b, aunque dichos ayuntamientos, en ningún caso, podrán incrementar el número de cargos con dedicación exclusiva respecto a los que disponían a 31 de diciembre de 2012.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La DT décima de la Ley 27/2013 establece que las limitaciones retributivas no serán de aplicación a los Ayuntamientos que cumplan los objetivos de estabilidad presupuestaria y de deuda pública y cuyo periodo de pago no supere en más de 30 días el plazo previsto, aunque sin posibilidad de incrementar los cargos con dedicación exclusiva.'}},
{n:348, q:'El art.75 bis de la Ley 7/1985, Reguladora de las Bases del Régimen Local establece determinados criterios sobre las retribuciones de los miembros de las Corporaciones Locales. Indique cual de los siguientes es incorrecto:', o:{a:'Los Presupuestos Generales del Estado podrán determinar, anualmente y de forma proporcional, el límite máximo total que pueden percibir los miembros de las Corporaciones Locales por todos los conceptos retributivos y asistencias.',b:'Los concejales que sean proclamados Diputados Provinciales o equivalentes deberán optar por mantener el régimen de dedicación exclusiva en una u otra Entidad Local, sin que en ningún caso puedan acumularse ambos regímenes de dedicación.',c:'Solo los miembros de la Corporación que no tengan dedicación exclusiva ni dedicación parcial percibirán asistencias por la concurrencia efectiva a las sesiones de los órganos colegiados de la Corporación de que formen parte, en la cuantía señalada por el Pleno de la misma.',d:'En el caso de los Cabildos y Consejos Insulares, sus Presidentes tendrán un límite máximo por todos los conceptos retributivos y asistencias referenciado a la retribución del tramo correspondiente al Alcalde o Presidente de la Corporación municipal más poblada de su provincia.'}, correct:'a', why:{a:'La opción a) es incorrecta: los PGE determinarán anualmente y de forma proporcional el límite máximo total, pero no solo "podrán" sino que "determinarán" obligatoriamente.'}},
{n:349, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, los ayuntamientos de municipios con menos de 1.000 habitantes:', o:{a:'Tendrán, como máximo, 1 cargo con dedicación exclusiva.',b:'Tendrán, como máximo, 2 cargos con dedicación exclusiva.',c:'Tendrán, como máximo, 3 cargos con dedicación exclusiva.',d:'No podrá tener ningún cargo con dedicación exclusiva.'}, correct:'d', why:{d:'El art. 75 ter LRBRL establece que los ayuntamientos de municipios con menos de 1.000 habitantes no podrán tener ningún cargo con dedicación exclusiva.'}},
{n:350, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 1001 y 2000 habitantes no podrá exceder de:', o:{a:'1 cargo con dedicación exclusiva.',b:'2 cargos con dedicación exclusiva.',c:'3 cargos con dedicación exclusiva.',d:'No podrá tener ningún cargo con dedicación exclusiva.'}, correct:'a', why:{a:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 1.001 y 2.000 habitantes no podrá exceder de 1 cargo con dedicación exclusiva.'}},
{n:351, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 2001 y 3000 habitantes no podrá exceder de:', o:{a:'2 cargos con dedicación exclusiva.',b:'3 cargos con dedicación exclusiva.',c:'1 cargo con dedicación exclusiva.',d:'No podrá tener ningún cargo con dedicación exclusiva.'}, correct:'a', why:{a:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 2.001 y 3.000 habitantes no podrá exceder de 2 cargos con dedicación exclusiva.'}},
{n:352, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 3001 y 10.000 habitantes no podrá exceder de:', o:{a:'1 cargo con dedicación exclusiva.',b:'2 cargos con dedicación exclusiva.',c:'3 cargos con dedicación exclusiva.',d:'No podrá tener ningún cargo con dedicación exclusiva.'}, correct:'c', why:{c:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 3.001 y 10.000 habitantes no podrá exceder de 3 cargos con dedicación exclusiva.'}},
{n:353, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 10.001 y 15.000 habitantes no podrá exceder de:', o:{a:'5 cargos con dedicación exclusiva.',b:'4 cargos con dedicación exclusiva.',c:'3 cargos con dedicación exclusiva.',d:'2 cargos con dedicación exclusiva.'}, correct:'a', why:{a:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 10.001 y 15.000 habitantes no podrá exceder de 5 cargos con dedicación exclusiva.'}},
{n:354, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 15.001 y 20.000 habitantes no podrá exceder de:', o:{a:'4 cargos con dedicación exclusiva.',b:'5 cargos con dedicación exclusiva.',c:'6 cargos con dedicación exclusiva.',d:'7 cargos con dedicación exclusiva.'}, correct:'d', why:{d:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 15.001 y 20.000 habitantes no podrá exceder de 7 cargos con dedicación exclusiva.'}},
{n:355, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 20.001 y 35.000 habitantes no podrá exceder de:', o:{a:'2 cargos con dedicación exclusiva.',b:'7 cargos con dedicación exclusiva.',c:'10 cargos con dedicación exclusiva.',d:'9 cargos con dedicación exclusiva.'}, correct:'c', why:{c:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 20.001 y 35.000 habitantes no podrá exceder de 10 cargos con dedicación exclusiva.'}},
{n:356, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 35.001 y 50.000 habitantes no podrá exceder de:', o:{a:'11 cargos con dedicación exclusiva.',b:'13 cargos con dedicación exclusiva.',c:'15 cargos con dedicación exclusiva.',d:'17 cargos con dedicación exclusiva.'}, correct:'a', why:{a:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 35.001 y 50.000 habitantes no podrá exceder de 11 cargos con dedicación exclusiva. Según el solucionario la respuesta es a.'}},
{n:357, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 51.001 y 100.000 habitantes no podrá exceder de:', o:{a:'11 cargos con dedicación exclusiva.',b:'13 cargos con dedicación exclusiva.',c:'15 cargos con dedicación exclusiva.',d:'17 cargos con dedicación exclusiva.'}, correct:'c', why:{c:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 51.001 y 100.000 habitantes no podrá exceder de 15 cargos con dedicación exclusiva.'}},
{n:358, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 100.001 y 300.000 habitantes no podrá exceder de:', o:{a:'13 cargos con dedicación exclusiva.',b:'15 cargos con dedicación exclusiva.',c:'17 cargos con dedicación exclusiva.',d:'18 cargos con dedicación exclusiva.'}, correct:'d', why:{d:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 100.001 y 300.000 habitantes no podrá exceder de 18 cargos con dedicación exclusiva.'}},
{n:359, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 300.001 y 500.000 habitantes no podrá exceder de:', o:{a:'25 cargos con dedicación exclusiva.',b:'23 cargos con dedicación exclusiva.',c:'20 cargos con dedicación exclusiva.',d:'22 cargos con dedicación exclusiva.'}, correct:'c', why:{c:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 300.001 y 500.000 habitantes no podrá exceder de 20 cargos con dedicación exclusiva. Según el solucionario la respuesta es c.'}},
{n:360, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 500.001 y 700.000 habitantes no podrá exceder de:', o:{a:'25 cargos con dedicación exclusiva.',b:'23 cargos con dedicación exclusiva.',c:'20 cargos con dedicación exclusiva.',d:'22 cargos con dedicación exclusiva.'}, correct:'d', why:{d:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 500.001 y 700.000 habitantes no podrá exceder de 22 cargos con dedicación exclusiva.'}},
{n:361, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de un Municipio de entre 700.001 y 1.000.000 habitantes no podrá exceder de:', o:{a:'25 cargos con dedicación exclusiva.',b:'23 cargos con dedicación exclusiva.',c:'20 cargos con dedicación exclusiva.',d:'22 cargos con dedicación exclusiva.'}, correct:'a', why:{a:'El art. 75 ter LRBRL establece que el Ayuntamiento de un Municipio de entre 700.001 y 1.000.000 habitantes no podrá exceder de 25 cargos con dedicación exclusiva.'}},
{n:362, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de Madrid no podrá exceder de:', o:{a:'25 cargos con dedicación exclusiva.',b:'23 cargos con dedicación exclusiva.',c:'45 cargos con dedicación exclusiva.',d:'32 cargos con dedicación exclusiva.'}, correct:'c', why:{c:'El art. 75 ter LRBRL establece que el Ayuntamiento de Madrid no podrá exceder de 45 cargos con dedicación exclusiva.'}},
{n:363, q:'De conformidad con lo establecido en el art.75 ter de la Ley 7/1985, Reguladora de las Bases del régimen Local, el Ayuntamiento de Barcelona no podrá exceder de:', o:{a:'25 cargos con dedicación exclusiva.',b:'23 cargos con dedicación exclusiva.',c:'45 cargos con dedicación exclusiva.',d:'32 cargos con dedicación exclusiva.'}, correct:'d', why:{d:'El art. 75 ter LRBRL establece que el Ayuntamiento de Barcelona no podrá exceder de 32 cargos con dedicación exclusiva.'}},
{n:364, q:'La Disposición transitoria décima de la ley 27/2013, de racionalización y sostenibilidad de la Administración Local, dispone que las limitaciones del número de cargos públicos con dedicación exclusiva, no serán de aplicación:', o:{a:'A aquellos Ayuntamientos que cumplan con los objetivos de estabilidad presupuestaria y deuda pública.',b:'A aquellos Ayuntamientos cuyo periodo de pago a proveedores no supere en más de 30 días el plazo previsto de la normativa sobre morosidad.',c:'A aquellos Ayuntamientos que cumplan con los requisitos reflejados en las respuestas a y b, aunque dichos ayuntamientos, en ningún caso, podrán incrementar el número de cargos con dedicación exclusiva respecto a los que disponían a 31 de diciembre de 2012.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La DT décima de la Ley 27/2013 establece que las limitaciones del número de cargos con dedicación exclusiva no serán de aplicación a los Ayuntamientos que cumplan los objetivos de estabilidad presupuestaria y cuyo periodo de pago no supere 30 días, aunque sin poder incrementar los cargos respecto a los existentes a 31 de diciembre de 2012.'}},
{n:365, q:'Los miembros de las Corporaciones Locales formularán declaración de sus bienes patrimoniales y de la participación en sociedades de todo tipo:', o:{a:'Antes de la toma de posesión, con ocasión del cese y al final del mandato, así como cuando se modifiquen las circunstancias de hecho.',b:'Antes de la toma de posesión, cuando se modifiquen las circunstancias de hecho y cuando se lo requiera el Presidente de su respectiva Corporación.',c:'Antes de la toma de posesión, al final del mandato y cuando se lo requiera el Presidente de su respectiva Corporación.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 75 LRBRL establece que los miembros de las Corporaciones Locales formularán declaración de sus bienes patrimoniales antes de la toma de posesión, con ocasión del cese y al final del mandato, así como cuando se modifiquen las circunstancias de hecho.'}},
{n:366, q:'De conformidad con lo establecido en el art 75 de la Ley 7/85, formularán declaración sobre causas de posible incompatibilidad y sobre cualquier actividad que les proporcione o pueda proporcionar ingresos económicos:', o:{a:'Los representantes locales.',b:'Los miembros no electos de la Junta de Gobierno Local.',c:'Los citados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 75 LRBRL establece que tanto los representantes locales como los miembros no electos de la Junta de Gobierno Local formularán declaración sobre causas de posible incompatibilidad y sobre cualquier actividad que les proporcione ingresos económicos.'}},
{n:367, q:'La declaración de bienes y actividades privadas que deben realizar los miembros de las Corporaciones Locales antes de su toma de posesión, cuando cesen, al final de su mandato y cuando se modifiquen las circunstancias de hecho:', o:{a:'Debe realizarse ante la Secretaría de la respectiva Corporación.',b:'Puede realizarse ante el Secretario de la Diputación Provincial u órgano competente de la respectiva Comunidad Autónoma cuando el interesado considere amenazada su seguridad personal y familiar, o la de sus bienes y negocios.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El art. 75 LRBRL establece que la declaración debe realizarse ante la Secretaría de la respectiva Corporación, pudiendo hacerse ante el Secretario de la Diputación Provincial cuando el interesado considere amenazada su seguridad. Las opciones a) y b) son parcialmente correctas pero c) y d) deben verificarse. Según el solucionario la respuesta es d.'}},
{n:368, q:'La declaración de bienes patrimoniales y de la participación en sociedades de todo tipo que deben realizar los miembros de las Corporaciones Locales, las formularán:', o:{a:'Antes de la toma de posesión, con ocasión del cese y al final del mandato, así como cuando se modifiquen las circunstancias de hecho.',b:'En los modelos aprobados por los plenos respectivos.',c:'Ante la Secretaría de la respectiva Corporación.',d:'Todo lo reflejado en las respuestas anteriores es correcto.'}, correct:'d', why:{d:'El art. 75 LRBRL establece que la declaración de bienes patrimoniales se realiza en los momentos descritos, en los modelos aprobados por los plenos respectivos y ante la Secretaría de la respectiva Corporación.'}},
{n:369, q:'Durante los dos años siguientes a la finalización de su mandato, a los representantes locales que hayan ostentado responsabilidades ejecutivas en el gobierno local, se les aplicarán las incompatibilidades previstas:', o:{a:'En la Ley 3/2015.',b:'En la Ley 5/2008.',c:'En la Ley orgánica 6/2005.',d:'En la ley orgánica 5/2008.'}, correct:'a', why:{a:'El art. 75 LRBRL establece que durante los dos años siguientes a la finalización del mandato, a los representantes locales con responsabilidades ejecutivas se les aplicarán las incompatibilidades previstas en la Ley 3/2015, de 30 de marzo, reguladora del ejercicio del alto cargo de la Administración General del Estado.'}},
{n:370, q:'Según el artículo 73 de la Ley 7/1985, a efectos de su actuación corporativa, los concejales se constituyen en grupos políticos, con excepción de aquellos que no se integren en el grupo político por el que fueron elegidos, o abandonaren éste, que tendrán la consideración de no adscritos, y...', o:{a:'Sus derechos económicos no podrán ser superiores a los que les hubieren correspondido de permanecer en el grupo de procedencia.',b:'Sus derechos políticos no podrán ser superiores a los que les hubieren correspondido de permanecer en el grupo de procedencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 73 LRBRL establece que los concejales no adscritos tendrán derechos económicos y políticos no superiores a los que les hubieren correspondido de permanecer en el grupo de procedencia.'}},
];
